/* ================================================================== *
 *  3D scenes (walking, cycling). Kept in their own scope.
 * ================================================================== */
const LWG3D = (() => {
/* ------------------------------------------------------------------ *
 *  3D scenes for Weather Go by Lutarym.
 *  Rendering with three.js (bundled above as LTHREE, MIT license).
 *
 *  Poses are still worked out in a side view plane, in "figure units"
 *  (1 unit = 2 cm): x forward, y down, ground at y = 0. The 3D rigs turn
 *  these poses into real bodies with depth, light and shadow.
 * ------------------------------------------------------------------ */
const T3 = LTHREE;

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, f) => a + (b - a) * f;
const lerpPt = (a, b, f) => [lerp(a[0], b[0], f), lerp(a[1], b[1], f)];
const ease = (f) => {
  const x = clamp(f, 0, 1);
  return x * x * (3 - 2 * x);
};
const wrap = (v, a, b) => {
  const r = b - a;
  return ((((v - a) % r) + r) % r) + a;
};
const rnd = (a, b) => a + Math.random() * (b - a);
const RAD = Math.PI / 180;

/** Deterministic pseudo random number 0..1 for an integer seed. */
function hash1(n) {
  const v = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return v - Math.floor(v);
}

/** Two bone inverse kinematics in the side plane. side picks the bend. */
function ik(a, b, l1, l2, side) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const d = clamp(Math.hypot(dx, dy), Math.abs(l1 - l2) + 0.01, l1 + l2 - 0.01);
  const base = Math.atan2(dy, dx);
  const c = clamp((l1 * l1 + d * d - l2 * l2) / (2 * l1 * d), -1, 1);
  const ang = base - side * Math.acos(c);
  return [a[0] + Math.cos(ang) * l1, a[1] + Math.sin(ang) * l1];
}

/** Rotates p around c; positive degrees turn clockwise on screen (y down). */
function rotAround(p, c, d) {
  const r = d * RAD;
  const dx = p[0] - c[0];
  const dy = p[1] - c[1];
  return [c[0] + dx * Math.cos(r) - dy * Math.sin(r), c[1] + dx * Math.sin(r) + dy * Math.cos(r)];
}

/** Slow, irregular motion in about -1..1, used for gusts and sway. */
function wobble(t, seed = 0) {
  return (Math.sin(t * 1.3 + seed) + 0.6 * Math.sin(t * 2.7 + seed * 1.9) + 0.35 * Math.sin(t * 4.9 + seed * 0.6)) / 1.95;
}

/** Fine, uneven shivering in about -1..1. */
function tremor(t, seed = 0) {
  return 0.55 * Math.sin(t * 47 + seed) + 0.3 * Math.sin(t * 61 + seed * 2.3) + 0.15 * Math.sin(t * 83 + seed * 0.4);
}

const polar = (p, len, ang) => [p[0] + Math.cos(ang) * len, p[1] + Math.sin(ang) * len];

/** Interpolates between key poses: keys = [[time, value], ...] sorted. */
function keyed(keys, time, mixFn) {
  if (time <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i += 1) {
    if (time <= keys[i][0]) {
      const f = ease((time - keys[i - 1][0]) / (keys[i][0] - keys[i - 1][0]));
      return mixFn(keys[i - 1][1], keys[i][1], f);
    }
  }
  return keys[keys.length - 1][1];
}

/** Leans the upper body around the hip. */
function leanPose(P, d) {
  ['shoulder', 'head', 'elbow', 'hand', 'elbow2', 'hand2'].forEach((k) => {
    if (P[k]) P[k] = rotAround(P[k], P.hip, d);
  });
  return P;
}

/** The reason that shapes the pose; rain first, it is the most visible. */
function moodReason(mood) {
  if (!mood) return null;
  return ['rain', 'cold', 'wind', 'hot'].find((k) => mood[k] >= 1) || null;
}

/** Fades a reaction in and out over about half a second. */
function moodBlend(fig, mood, dt, active) {
  const reason = active ? moodReason(mood) : null;
  if (reason) fig.moodLast = reason;
  fig.moodW = lerp(fig.moodW || 0, reason ? 1 : 0, Math.min(1, dt * 2.2));
  if (fig.moodW < 0.01 && !reason) fig.moodLast = null;
  return { reason: fig.moodLast || null, w: ease(clamp(fig.moodW, 0, 1)) };
}

/**
 * Pose for a reason, built from a copy of the normal pose.
 *   o.arm            [upper arm, forearm] lengths, elbows follow by IK
 *   o.keepNear/Far   that arm holds something (umbrella, handlebar)
 *   o.standing       the feet may step on the spot
 *   o.handsToMouth   blow into the hands instead of rubbing the arms
 */
function reactionPose(P0, reason, t, o) {
  const P = { ...P0 };
  const [ua, fa] = o.arm;
  const setNear = (hand, side) => {
    if (o.keepNear) return;
    P.hand = hand;
    P.elbow = ik(P.shoulder, hand, ua, fa, side);
  };
  const setFar = (hand, side) => {
    if (o.keepFar) return;
    P.hand2 = hand;
    P.elbow2 = ik(P.shoulder, hand, ua, fa, side);
  };
  P.lean = 0;
  P.headTilt = P0.headTilt || 0;
  if (reason === 'cold') {
    const tr = tremor(t) * 0.45;
    const tr2 = tremor(t, 2) * 0.4;
    P.lean = 4;
    P.shoulder = [P.shoulder[0] + tr, P.shoulder[1] - 1.2 + tr2];
    P.head = [P.head[0] - 0.4 + tr * 0.6, P.head[1] + 1.8 + tr2 * 0.6];
    P.headTilt = 9;
    const sh = P.shoulder;
    const hd = P.head;
    if (o.handsToMouth) {
      const rub = Math.sin(t * 13) * 0.9;
      setNear([hd[0] + 7.5 + rub, hd[1] + 5.5], -1);
      setFar([hd[0] + 6.2 - rub, hd[1] + 6.5], -1);
      P.handsMouth = true;
    } else {
      const rub = Math.sin(t * 5.6) * 2.6;
      setNear([sh[0] - 2.5 + tr, sh[1] + 6 + rub], 1);
      setFar([sh[0] + 3.5 + tr2, sh[1] + 7 - rub], 1);
    }
  } else if (reason === 'rain') {
    P.head = [P.head[0] + 1, P.head[1] + 2.2];
    P.headTilt = 14;
    const hd = P.head;
    P.lean = 6;
    setNear([hd[0] + 3, hd[1] - 7.5], -1);
    setFar([hd[0] - 4, hd[1] - 8], 1);
    P.handsHead = true;
  } else if (reason === 'wind') {
    const g = 0.5 + 0.5 * wobble(t * 1.1, 1);
    P.lean = 5 + 7 * g;
    P.headTilt = 11;
    const sh = P.shoulder;
    const hd = P.head;
    setNear([hd[0] + 8.5, hd[1] - 0.5 + wobble(t * 3, 4) * 0.8], -1);
    setFar([sh[0] - 10 - 4 * g, sh[1] + 21], 1);
    P.handEyes = true;
  } else if (reason === 'hot') {
    const breathe = Math.sin(t * 2.4) * 0.6;
    P.lean = 2;
    P.shoulder = [P.shoulder[0], P.shoulder[1] + 1 + breathe];
    P.head = [P.head[0], P.head[1] + 1.2 + breathe];
    P.headTilt = 6;
    const sh = P.shoulder;
    const hd = P.head;
    const tau = t % 5;
    const fan = tau > 2.2 ? Math.sin((tau - 2.2) * 12) * 3.2 : 0;
    const hand = keyed([
      [0, [hd[0] + 11, hd[1] + 7]],
      [0.7, [hd[0] + 8, hd[1] - 4]],
      [1.5, [hd[0] - 2.5, hd[1] - 5]],
      [2.2, [hd[0] + 11, hd[1] + 6]],
      [5, [hd[0] + 11, hd[1] + 7]],
    ], tau, lerpPt);
    setNear([hand[0], hand[1] + fan], -1);
    setFar([sh[0] + 1.5, sh[1] + 25], -1);
    P.handFace = true;
  }
  if (P.lean) leanPose(P, P.lean);
  return P;
}

/* ------------------------------------------------------------------ *
 *  Gait: walking and running from joint angle curves, as measured in
 *  human gait analysis. Phase 0 is heel strike of the near leg.
 *    hip   thigh angle from vertical, positive = forward
 *    knee  knee flexion, 0 = straight
 *    foot  sole angle, positive = toes down
 *  The hip height follows from the foot on the ground, so the body rises
 *  over the straight stance leg and dips when both feet touch. A planted
 *  foot never slides: the stride sets the step rate.
 * ------------------------------------------------------------------ */
const LEG = { thigh: 21.5, shin: 21.5, ankle: 3, heel: 3, toe: 8.5, torso: 24 };
const STAND_HIP = LEG.thigh + LEG.shin + LEG.ankle - 0.4;

/** Smooth periodic interpolation through [phase, value] keys. */
function curve(keys, p) {
  const q = ((p % 1) + 1) % 1;
  for (let i = 1; i < keys.length; i += 1) {
    if (q <= keys[i][0]) {
      const a = keys[i - 1];
      const b = keys[i];
      const f = (q - a[0]) / (b[0] - a[0] || 1);
      return a[1] + (b[1] - a[1]) * (0.5 - 0.5 * Math.cos(f * Math.PI));
    }
  }
  return keys[keys.length - 1][1];
}

const GAITS = {
  walk: {
    stance: 0.6,
    hip: [[0, 22], [0.5, -10], [0.62, -8], [0.88, 25], [1, 22]],
    knee: [[0, 3], [0.14, 16], [0.38, 3], [0.6, 38], [0.72, 62], [0.86, 28], [0.96, 2], [1, 3]],
    foot: [[0, -14], [0.08, 0], [0.42, 0], [0.6, 26], [0.7, 14], [0.86, -2], [0.96, -12], [1, -14]],
    bump: 0,
    lean: 3,
    hipMean: 7,
    arm: { swing: 17, elbow: 12, extra: 12 },
  },
  run: {
    stance: 0.36,
    hip: [[0, 30], [0.34, -14], [0.44, -16], [0.7, 30], [0.86, 40], [1, 30]],
    knee: [[0, 16], [0.12, 38], [0.32, 20], [0.45, 60], [0.62, 118], [0.78, 80], [0.92, 22], [1, 16]],
    foot: [[0, -6], [0.07, 0], [0.24, 4], [0.38, 34], [0.58, 42], [0.78, 10], [0.93, -8], [1, -6]],
    bump: 3.2,
    lean: 9,
    hipMean: 10,
    arm: { swing: 34, elbow: 88, extra: 14 },
  },
};

function rot(v, a) {
  const r = (a * Math.PI) / 180;
  return [v[0] * Math.cos(r) - v[1] * Math.sin(r), v[0] * Math.sin(r) + v[1] * Math.cos(r)];
}

/** One leg relative to the hip at (0, 0); amp scales the motion. */
function legFK(g, p, amp) {
  const th = curve(g.hip, p) * amp;
  const kn = curve(g.knee, p) * (0.25 + 0.75 * amp);
  const ft = curve(g.foot, p) * amp;
  const t1 = (th * Math.PI) / 180;
  const t2 = ((th - kn) * Math.PI) / 180;
  const knee = [Math.sin(t1) * LEG.thigh, Math.cos(t1) * LEG.thigh];
  const ankle = [knee[0] + Math.sin(t2) * LEG.shin, knee[1] + Math.cos(t2) * LEG.shin];
  const h = rot([-LEG.heel, LEG.ankle], ft);
  const tt = rot([LEG.toe, LEG.ankle], ft);
  const heel = [ankle[0] + h[0], ankle[1] + h[1]];
  const toe = [ankle[0] + tt[0], ankle[1] + tt[1]];
  return { knee, ankle, foot: ft, low: Math.max(heel[1], toe[1]), heelX: heel[0] };
}

/** How far the body travels in one full cycle, from the planted foot. */
function strideOf(g, amp) {
  const a = legFK(g, 0, amp);
  const b = legFK(g, g.stance, amp);
  return Math.max(4, (a.ankle[0] - b.ankle[0]) / g.stance);
}

/**
 * Pose for a phase. Returns hip height above the ground and both legs,
 * relative to the hip. In flight (running) the hip follows an arc between
 * take off and landing.
 */
function gaitFrame(g, p, amp) {
  const L = [legFK(g, p, amp), legFK(g, p + 0.5, amp)];
  const inStance = (q) => (((q % 1) + 1) % 1) < g.stance;
  const stanceLow = [];
  if (inStance(p)) stanceLow.push(L[0].low);
  if (inStance(p + 0.5)) stanceLow.push(L[1].low);
  let hipH;
  if (stanceLow.length) {
    hipH = Math.max(...stanceLow);
  } else {
    // Flight: from toe off of one leg to the landing of the other.
    const qq = (((p % 0.5) + 0.5) % 0.5);
    const f = clamp((qq - g.stance) / (0.5 - g.stance), 0, 1);
    hipH = lerp(legFK(g, g.stance, amp).low, legFK(g, 0, amp).low, f) + Math.sin(f * Math.PI) * g.bump * amp;
  }
  return { hipH, legs: L };
}

/**
 * Builds a full person pose (in figure units, ground at y = 0) from a gait
 * phase. w blends between standing (0) and the gait (1).
 */
function gaitPose(g, p, amp, w, extraLean = 0) {
  const fr = gaitFrame(g, p, amp);
  const hipH = lerp(STAND_HIP, fr.hipH, w);
  const hip = [0, -hipH];
  const P = { hip };
  const leg = (i, standX) => {
    const l = fr.legs[i];
    const sk = [standX * 0.4, LEG.thigh - 0.2];
    const sa = [standX, LEG.thigh + LEG.shin - 0.4];
    const knee = lerpPt(sk, l.knee, w);
    const ankle = lerpPt(sa, l.ankle, w);
    return { knee: [knee[0], knee[1] - hipH], ankle: [ankle[0], ankle[1] - hipH], foot: l.foot * w };
  };
  const a = leg(0, 1.5);
  const b = leg(1, -1.5);
  P.knee = a.knee; P.ankle = a.ankle; P.footAng = a.foot;
  P.knee2 = b.knee; P.ankle2 = b.ankle; P.footAng2 = b.foot;
  P.foot = [a.ankle[0], a.ankle[1] + LEG.ankle];
  P.foot2 = [b.ankle[0], b.ankle[1] + LEG.ankle];

  const lean = (g.lean * w + extraLean) * (Math.PI / 180);
  P.shoulder = [hip[0] + Math.sin(lean) * LEG.torso, hip[1] - Math.cos(lean) * LEG.torso];
  P.head = [P.shoulder[0] + Math.sin(lean) * 10 + 1.2, P.shoulder[1] - Math.cos(lean) * 10.5];
  P.headTilt = 0;

  // Arms swing against the legs; elbows bend more on the forward swing.
  const arm = (q) => {
    const fwd = (curve(g.hip, q + 0.5) - g.hipMean) / 30;
    const ang = g.arm.swing * fwd * amp * w;
    const flex = lerp(8, g.arm.elbow, w) + Math.max(0, ang) * (g.arm.extra / 20);
    const e = [P.shoulder[0] + Math.sin((ang * Math.PI) / 180) * 14, P.shoulder[1] + Math.cos((ang * Math.PI) / 180) * 14];
    const fa = ((ang + flex) * Math.PI) / 180;
    return [e, [e[0] + Math.sin(fa) * 13, e[1] + Math.cos(fa) * 13]];
  };
  [P.elbow, P.hand] = arm(p);
  [P.elbow2, P.hand2] = arm(p + 0.5);
  return P;
}

/** Knee for a person whose foot stands at a given point (ground contact). */
function legTo(hip, foot) {
  return ik(hip, [foot[0], foot[1] - LEG.ankle], LEG.thigh, LEG.shin, 1);
}

/** Copy of a pose, so changes do not leak between frames. */
function clonePose(P) {
  const o = {};
  Object.keys(P).forEach((k) => { o[k] = Array.isArray(P[k]) ? P[k].slice() : P[k]; });
  return o;
}

/** Blends two poses point by point. */
function mixPose(A, B, f) {
  const o = {};
  Object.keys(B).forEach((key) => {
    const a = A[key];
    const b = B[key];
    if (Array.isArray(b) && Array.isArray(a)) o[key] = lerpPt(a, b, f);
    else if (typeof b === 'number' && typeof a === 'number') o[key] = lerp(a, b, f);
    else o[key] = b;
  });
  return o;
}

/** Piecewise keys [time, value, ease into this key]. */
function keyAt(keys, x) {
  if (x <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i += 1) {
    if (x <= keys[i][0]) {
      const a = keys[i - 1];
      const b = keys[i];
      let f = (x - a[0]) / (b[0] - a[0] || 1);
      if (b[2]) f = ease(f);
      return a[1] + (b[1] - a[1]) * f;
    }
  }
  return keys[keys.length - 1][1];
}

/* ------------------------------------------------------------------ *
 *  Small three.js helpers
 * ------------------------------------------------------------------ */
const V3 = (x = 0, y = 0, z = 0) => new T3.Vector3(x, y, z);
const UP = V3(0, 1, 0);
const _tmpV = V3();
const _tmpQ = new T3.Quaternion();

const MAT_CACHE = new Map();
/** Soft matte material, shared per colour and options. */
function mat(color, o = {}) {
  const key = `${color}|${o.rough ?? 0.78}|${o.metal ?? 0}|${o.emissive || ''}|${o.opacity ?? 1}|${o.side || 0}|${o.flat ? 1 : 0}`;
  if (!o.unique && MAT_CACHE.has(key)) return MAT_CACHE.get(key);
  const m = new T3.MeshStandardMaterial({
    color,
    roughness: o.rough ?? 0.78,
    metalness: o.metal ?? 0,
    flatShading: !!o.flat,
  });
  if (o.emissive) { m.emissive = new T3.Color(o.emissive); m.emissiveIntensity = o.emissiveIntensity ?? 1; }
  if (o.opacity !== undefined && o.opacity < 1) { m.transparent = true; m.opacity = o.opacity; m.depthWrite = false; }
  if (o.side) m.side = o.side;
  if (!o.unique) MAT_CACHE.set(key, m);
  return m;
}

const GEO_CACHE = new Map();
function geo(key, make) {
  if (!GEO_CACHE.has(key)) GEO_CACHE.set(key, make());
  return GEO_CACHE.get(key);
}
const sphereGeo = () => geo('sphere', () => new T3.SphereGeometry(1, 24, 16));
const lowSphereGeo = () => geo('sphere-low', () => new T3.SphereGeometry(1, 14, 10));

/** A mesh that casts and receives shadows. */
function mesh(g, m, shadow = true) {
  const o = new T3.Mesh(g, m);
  o.castShadow = shadow;
  o.receiveShadow = shadow;
  return o;
}

/** Ellipsoid from the shared unit sphere. */
function blob(color, sx, sy, sz, o = {}) {
  const m = mesh(o.low ? lowSphereGeo() : sphereGeo(), o.material || mat(color, o), o.shadow !== false);
  m.scale.set(sx, sy, sz);
  return m;
}

/** Places a capsule (built along +y, length len) between two points. */
function boneTo(o, a, b, len) {
  _tmpV.subVectors(b, a);
  const d = _tmpV.length();
  if (d < 1e-6) return;
  o.position.copy(a).addScaledVector(_tmpV, 0.5);
  _tmpV.multiplyScalar(1 / d);
  o.quaternion.setFromUnitVectors(UP, _tmpV);
  o.scale.set(1, d / len, 1);
}

/** One geometry from several (non indexed, positions and normals). */
function mergeGeos(list) {
  const pos = [];
  const nor = [];
  list.forEach((g0) => {
    const g = g0.index ? g0.toNonIndexed() : g0;
    if (!g.attributes.normal) g.computeVertexNormals();
    pos.push(...g.attributes.position.array);
    nor.push(...g.attributes.normal.array);
  });
  const out = new T3.BufferGeometry();
  out.setAttribute('position', new T3.Float32BufferAttribute(pos, 3));
  out.setAttribute('normal', new T3.Float32BufferAttribute(nor, 3));
  return out;
}

/** Cylinder from a to b (radius r, at b r1) as a geometry. */
function tubeGeo(a, b, r, seg = 8, r1 = r) {
  const d = new T3.Vector3().subVectors(b, a);
  const len = d.length();
  const g = new T3.CylinderGeometry(r1, r, len, seg, 1);
  const q = new T3.Quaternion().setFromUnitVectors(UP, d.clone().normalize());
  g.applyQuaternion(q);
  const m = new T3.Vector3().addVectors(a, b).multiplyScalar(0.5);
  g.translate(m.x, m.y, m.z);
  return g;
}
/** Canvas based texture (for sprites and the sky). */
function canvasTex(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new T3.CanvasTexture(c);
  t.colorSpace = T3.SRGBColorSpace;
  return t;
}

/** Soft round dot, used for snow, puffs and glows. */
function dotTex() {
  return geo('dot-tex', () => canvasTex(64, 64, (g, w, h) => {
    const r = g.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    r.addColorStop(0, 'rgba(255,255,255,1)');
    r.addColorStop(0.45, 'rgba(255,255,255,0.85)');
    r.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = r;
    g.fillRect(0, 0, w, h);
  }));
}

/** Text sprite, e.g. the Z of a nap. */
function textSprite(text, color = '#E8EDF4', px = 64) {
  const tex = canvasTex(px, px, (g, w, h) => {
    g.font = `800 ${Math.round(px * 0.8)}px Roboto, Arial, sans-serif`;
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    g.lineWidth = px * 0.08;
    g.strokeStyle = 'rgba(11,16,23,0.8)';
    g.strokeText(text, w / 2, h / 2);
    g.fillStyle = color;
    g.fillText(text, w / 2, h / 2);
  });
  const s = new T3.Sprite(new T3.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
  return s;
}

/* ------------------------------------------------------------------ *
 *  Person3D: a soft, stylised person built from rounded body parts.
 *  Faces +x, up is +y, the near side (towards the camera) is +z.
 *  apply(P) takes a side view pose (figure units, y down) and sets every
 *  part; the near limbs sit at +z, the far limbs at -z.
 * ------------------------------------------------------------------ */
const SKIN3 = '#E8BE98';
const HIP_W = 4.4;     // half distance between the hip joints
const SHO_W = 9.4;     // half distance between the shoulder joints

/** Torso as a lathe: radius along the height, from the hip (0) upwards. */
function torsoGeo(kind) {
  return geo(`torso-${kind}`, () => {
    const pts = kind === 'woman'
      ? [[0, -4], [6.8, -3.4], [8.2, -1], [8.3, 2], [7.2, 6.5], [6.6, 9], [7.8, 14], [8.3, 17.5], [8.1, 21], [7.1, 24.2], [4.8, 26.2], [0, 27]]
      : [[0, -4], [7.4, -3.2], [8.8, -0.5], [8.9, 3], [8.5, 7.5], [8.9, 12], [9.6, 17], [9.6, 21], [8.6, 24.4], [5.6, 26.6], [0, 27.4]];
    const g = new T3.LatheGeometry(pts.map(([r, y]) => new T3.Vector2(r, y)), 28);
    g.computeVertexNormals();
    return g;
  });
}

/** Skirt: an open bell that hangs from the waist (local -y). */
function skirtGeo() {
  return geo('skirt', () => {
    const pts = [[7.6, 0.5], [8.2, -1], [9.6, -5], [11.4, -10], [12.6, -13.4], [12.4, -14]];
    const g = new T3.LatheGeometry(pts.map(([r, y]) => new T3.Vector2(r, y)), 28);
    g.computeVertexNormals();
    return g;
  });
}

/** Shoe: rounded toe cap, flat sole. Ankle at the origin, toes towards +x. */
function shoeGeo() {
  return geo('shoe', () => {
    const g = new T3.CapsuleGeometry(2.7, 7.4, 6, 14);
    g.rotateZ(Math.PI / 2);
    g.scale(1, 0.78, 1.02);
    g.translate(2.6, -1.25, 0);
    // Flatten the sole a little.
    const p = g.attributes.position;
    for (let i = 0; i < p.count; i += 1) if (p.getY(i) < -2.9) p.setY(i, -2.9 + (p.getY(i) + 2.9) * 0.25);
    g.computeVertexNormals();
    return g;
  });
}

/** Head: one soft egg shape with a narrower jaw and a small chin. */
function headGeo() {
  return geo('head', () => {
    const g = new T3.SphereGeometry(1, 36, 26);
    const p = g.attributes.position;
    for (let i = 0; i < p.count; i += 1) {
      let x = p.getX(i);
      const y = p.getY(i);
      let z = p.getZ(i);
      if (y < 0) {
        z *= 1 - 0.16 * -y;
        x += 0.07 * -y * Math.max(0, x);
      } else {
        x -= 0.05 * y * y;
      }
      p.setXYZ(i, x * 0.98, y * 1.06, z * 0.93);
    }
    g.computeVertexNormals();
    return g;
  });
}

function capGeo(r, len) {
  return geo(`cap-${r}-${len}`, () => new T3.CapsuleGeometry(r, len, 6, 14));
}

/** Arc used for the mouth: a bent tube in the y-z plane (facing +x). */
function arcGeo(radius, tube, arc, key) {
  return geo(`arc-${key}`, () => {
    const g = new T3.TorusGeometry(radius, tube, 6, 16, arc);
    g.rotateZ(-Math.PI / 2 - arc / 2); // centre of the arc points down: a smile
    g.rotateY(Math.PI / 2);            // face +x
    return g;
  });
}

class Person3D {
  /**
   * o = { kind: 'man'|'woman', skin, shirt, sleeves: 'long'|'short', pants,
   *       legs ('pants'|'skin'), shoes, hair, skirt, scale }
   */
  constructor(o) {
    this.o = o;
    this.kind = o.kind;
    this.root = new T3.Group();          // placed in the world by the scene
    this.body = new T3.Group();          // scaled body, poses in figure units
    this.body.scale.setScalar(o.scale || 1);
    this.root.add(this.body);
    const skin = mat(o.skin || SKIN3, { rough: 0.62 });
    // Clothes get their own materials, so they can darken when wet.
    this.mShirt = mat(o.shirt, { unique: true, rough: 0.85 });
    this.mPants = mat(o.pants, { rough: 0.85 });
    this.mShoes = mat(o.shoes, { rough: 0.5 });
    this.mSkin = skin;
    this.shirtColor = new T3.Color(o.shirt);
    this.wetColor = new T3.Color(o.shirt).multiplyScalar(0.55);

    const B = this.body;
    const add = (m) => { B.add(m); return m; };

    // Torso and neck.
    this.torso = new T3.Group();
    this.torsoMesh = mesh(torsoGeo(o.kind), this.mShirt);
    this.torsoMesh.scale.set(o.kind === 'woman' ? 0.66 : 0.64, 1, 1);
    this.torso.add(this.torsoMesh);
    add(this.torso);
    this.neck = add(mesh(capGeo(2.7, 5), skin));

    // Legs: thigh, shin, shoe for near (n) and far (f).
    const legM = o.legs === 'skin' ? skin : this.mPants;
    const thighM = o.skirt ? skin : this.mPants;
    this.leg = {};
    ['n', 'f'].forEach((s) => {
      this.leg[s] = {
        thigh: add(mesh(capGeo(o.kind === 'woman' ? 3.5 : 4.0, LEG.thigh), thighM)),
        shin: add(mesh(capGeo(o.kind === 'woman' ? 2.6 : 3.1, LEG.shin), legM)),
        shoe: add(mesh(shoeGeo(), this.mShoes)),
      };
    });

    // Arms: upper arm, forearm, hand. Short sleeves show skin below.
    const longSleeves = o.sleeves !== 'short';
    this.arm = {};
    ['n', 'f'].forEach((s) => {
      const a = {
        upper: add(mesh(capGeo(o.kind === 'woman' ? 2.2 : 2.65, 14), longSleeves ? this.mShirt : skin)),
        fore: add(mesh(capGeo(o.kind === 'woman' ? 1.9 : 2.3, 13), longSleeves ? this.mShirt : skin)),
        hand: add(blob(SKIN3, 2.2, 2.7, 1.7, { material: skin })),
      };
      if (!longSleeves) a.sleeve = add(mesh(capGeo(2.9, 4.2), this.mShirt));
      this.arm[s] = a;
    });

    // Skirt over the thighs.
    if (o.skirt) {
      this.skirt = new T3.Group();
      const sk = mesh(skirtGeo(), mat(o.skirt, { side: T3.DoubleSide, rough: 0.9 }));
      this.skirt.add(sk);
      add(this.skirt);
    }

    this._buildHead(o, skin);
  }

  _buildHead(o, skin) {
    const H = new T3.Group();
    H.rotation.order = 'YZX';
    this.head = H;
    this.body.add(H);
    const R = 8.6;
    this.headR = R;
    const skull = mesh(headGeo(), skin);
    skull.scale.setScalar(R);
    H.add(skull);
    // Ears.
    [1, -1].forEach((sd) => {
      const ear = blob(SKIN3, 1.4, 2.3, 1.0, { material: skin });
      ear.position.set(-0.6, 0.2, sd * R * 0.9);
      H.add(ear);
    });
    // Nose.
    this.nose = blob(SKIN3, 1.5, 1.7, 1.4, { material: skin });
    this.nose.position.set(R * 0.97, -0.6, 0);
    H.add(this.nose);
    // Eyes with a small highlight; brows above.
    const eyeM = mat('#1A1F27', { rough: 0.3 });
    const hiM = mat('#FFFFFF', { rough: 0.2, emissive: '#FFFFFF', emissiveIntensity: 0.6 });
    this.eyes = [];
    this.brows = [];
    [1, -1].forEach((sd) => {
      const e = new T3.Group();
      const ball = blob('#1A1F27', 1.05, 1.3, 0.9, { material: eyeM, shadow: false });
      const hl = blob('#FFFFFF', 0.32, 0.32, 0.32, { material: hiM, shadow: false });
      hl.position.set(0.55, 0.45, sd * 0.25);
      e.add(ball);
      e.add(hl);
      e.position.set(R * 0.83, 1.7, sd * 3.0);
      H.add(e);
      this.eyes.push(e);
      const b = mesh(capGeo(0.42, 2.2), mat(o.brow || o.hair || '#4A3426'), false);
      b.rotation.x = Math.PI / 2;
      const bg = new T3.Group();
      bg.add(b);
      bg.position.set(R * 0.86, 4.1, sd * 3.1);
      H.add(bg);
      this.brows.push({ g: bg, sd });
    });
    // Mouths: one shape per expression, only one is visible.
    const lipM = mat('#9C4A3C', { rough: 0.5 });
    const inM = mat('#5A1F1F', { rough: 0.7 });
    this.mouths = {};
    const mouthAt = (m) => { m.position.set(R * 0.9, -3.1, 0); H.add(m); return m; };
    this.mouths.calm = mouthAt(mesh(arcGeo(1.5, 0.3, Math.PI * 0.55, 'calm'), lipM, false));
    this.mouths.smile = mouthAt(mesh(arcGeo(2.0, 0.34, Math.PI * 0.85, 'smile'), lipM, false));
    const frown = mesh(arcGeo(1.7, 0.32, Math.PI * 0.7, 'frown'), lipM, false);
    frown.rotation.x = Math.PI;
    frown.position.y = -0.8;
    this.mouths.frown = mouthAt(frown);
    frown.position.y = -3.9;
    const laugh = new T3.Group();
    const lg = geo('laugh', () => {
      const g = new T3.SphereGeometry(1, 16, 10, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2);
      return g;
    });
    const lm = mesh(lg, inM, false);
    lm.scale.set(1.2, 2.2, 2.6);
    laugh.add(lm);
    const teeth = blob('#FFFFFF', 0.5, 0.45, 1.8, { shadow: false });
    teeth.position.set(0.6, -0.25, 0);
    laugh.add(teeth);
    this.mouths.laugh = mouthAt(laugh);
    laugh.position.set(R * 0.86, -2.6, 0);
    const open = blob('#5A1F1F', 0.9, 1.35, 1.1, { material: inM, shadow: false });
    this.mouths.open = mouthAt(open);
    open.position.set(R * 0.93, -3.3, 0);
    this.setMouth('smile');

    // Cheeks (blush when cold or hot).
    this.blushM = mat('#FF6F7A', { unique: true, opacity: 0.0001 });
    this.blush = [];
    [1, -1].forEach((sd) => {
      const c = blob('#FF6F7A', 0.6, 1.5, 2.0, { material: this.blushM, shadow: false });
      c.position.set(R * 0.74, -1.6, sd * 4.9);
      H.add(c);
      this.blush.push(c);
    });

    // Hair.
    const hairM = mat(o.hair, { rough: 0.9 });
    if (o.kind === 'man' && o.hairStyle === 'short') {
      // Short hair: a cap over the top, down to the neck at the back.
      const top = mesh(new T3.SphereGeometry(R * 1.045, 28, 10, 0, Math.PI * 2, 0, 0.98), hairM);
      top.scale.set(1, 1.03, 0.95);
      H.add(top);
      const back = mesh(new T3.SphereGeometry(R * 1.04, 28, 10, -1.75, 3.5, 0.9, 0.85), hairM);
      back.scale.set(1, 1.03, 0.95);
      H.add(back);
      this.toupee = new T3.Group();
      H.add(this.toupee);
      this.redNose = blob('#FF2A1F', 1.9, 1.9, 1.9, { material: mat('#FF2A1F', { unique: true, emissive: '#FF2A1F', emissiveIntensity: 0.6, rough: 0.35 }) });
      this.redNose.position.copy(this.nose.position);
      this.redNose.visible = false;
      H.add(this.redNose);
    } else if (o.kind === 'man') {
      // A ring of hair at the sides and back, the top is bald ...
      const ring = mesh(new T3.SphereGeometry(R * 1.04, 28, 12, -1.5, 3.0, 0.92, 0.78), hairM);
      ring.scale.set(1, 1.04, 0.95);
      H.add(ring);
      // ... under a toupee that the wind can take.
      this.toupee = new T3.Group();
      const tp = blob(o.toupee || '#4A3426', 6.6, 2.2, 6.2, { material: mat(o.toupee || '#4A3426', { rough: 0.95 }) });
      tp.position.set(0.6, 0, 0);
      const fringe = blob(o.toupee || '#4A3426', 2.4, 1.6, 5.2, { material: mat(o.toupee || '#4A3426', { rough: 0.95 }) });
      fringe.position.set(5.6, -0.6, 0);
      this.toupee.add(tp);
      this.toupee.add(fringe);
      this.toupee.position.set(0, R * 0.9, 0);
      this.toupee.rotation.z = -0.12;
      H.add(this.toupee);
      // Red nose for the cold, with a glow.
      this.redNose = blob('#FF2A1F', 1.9, 1.9, 1.9, { material: mat('#FF2A1F', { unique: true, emissive: '#FF2A1F', emissiveIntensity: 0.6, rough: 0.35 }) });
      this.redNose.position.copy(this.nose.position);
      this.redNose.visible = false;
      H.add(this.redNose);
    } else {
      // Hair cap over top and back, side bangs, and a ponytail.
      const cap = mesh(new T3.SphereGeometry(R * 1.07, 30, 16, -2.25, 4.5, 0, 1.9), hairM);
      cap.scale.set(1, 1.04, 0.96);
      H.add(cap);
      const bang = mesh(new T3.SphereGeometry(R * 1.08, 20, 8, 2.35, 1.6, 0.25, 0.62), hairM);
      bang.scale.set(1, 1.02, 0.96);
      H.add(bang);
      this.pony = new T3.Group();
      this.pony.position.set(-R * 0.82, 2.2, 0);
      const tie = blob('#22E07A', 1.3, 1.3, 1.3, { shadow: false });
      this.pony.add(tie);
      const p1 = blob(o.hair, 2.6, 4.6, 2.6, { material: hairM });
      p1.position.set(-1.6, -3.6, 0);
      const p2 = blob(o.hair, 2.0, 3.6, 2.0, { material: hairM });
      p2.position.set(-2.4, -8.6, 0);
      this.pony.add(p1);
      this.pony.add(p2);
      H.add(this.pony);
    }
  }

  setMouth(kind) {
    if (this._mouth === kind) return;
    this._mouth = kind;
    Object.entries(this.mouths).forEach(([k, m]) => { m.visible = k === kind; });
  }

  /** Brows: 0 neutral, >0 raised/surprised, <0 angry. sad: inner ends up. */
  setBrows(lift = 0, angle = 0) {
    this.brows.forEach(({ g, sd }) => {
      g.position.y = 4.1 + lift;
      g.rotation.x = sd * angle;
    });
  }

  setEyes(open = 1) {
    this.eyes.forEach((e) => { e.scale.y = clamp(open, 0.08, 1.2); });
  }

  setBlush(v) {
    this.blushM.opacity = clamp(v, 0, 1) * 0.55;
    this.blush.forEach((b) => { b.visible = v > 0.02; });
  }

  setWet(v) {
    this.mShirt.color.copy(this.shirtColor).lerp(this.wetColor, clamp(v, 0, 1));
  }

  /**
   * Sets the body from a side view pose. Extra options:
   *   headYaw     degrees, turns the head (looking back etc.)
   *   handZ/hand2Z   lateral position of near/far hand (default: at the side)
   *   footZ/foot2Z   lateral position of the feet
   */
  apply(P, x = {}) {
    const v = (p, z) => V3(p[0], -p[1], z);
    const hip = v(P.hip, 0);
    const sh = v(P.shoulder, 0);
    // Torso: from the hip towards the shoulders.
    this.torso.position.copy(hip);
    _tmpV.subVectors(sh, hip);
    const tl = _tmpV.length();
    this.torso.rotation.set(0, 0, -Math.atan2(_tmpV.x, _tmpV.y));
    this.torsoMesh.scale.y = tl / LEG.torso;
    this.torsoMesh.rotation.y = (x.chestYaw || 0) * RAD;

    // Legs.
    const legSide = (s, kneeK, ankleK, angK, zSign, zOver) => {
      const L = this.leg[s];
      const z = zOver ?? zSign * HIP_W;
      const h = V3(hip.x, hip.y, zSign * HIP_W);
      const k = v(P[kneeK], (zSign * HIP_W + z) / 2);
      const a = v(P[ankleK], z);
      boneTo(L.thigh, h, k, LEG.thigh);
      boneTo(L.shin, k, a, LEG.shin);
      L.shoe.position.copy(a);
      L.shoe.rotation.set(0, (x[s === 'n' ? 'footYaw' : 'foot2Yaw'] || 0) * RAD, -(P[angK] || 0) * RAD);
      return { h, k };
    };
    const ln = legSide('n', 'knee', 'ankle', 'footAng', 1, x.footZ);
    const lf = legSide('f', 'knee2', 'ankle2', 'footAng2', -1, x.foot2Z);

    // Arms. Elbows come from the side view, set between shoulder and hand.
    const armSide = (s, elbowK, handK, zSign, zOver) => {
      const A = this.arm[s];
      const shoulder = V3(sh.x, sh.y - 1.2, zSign * SHO_W);
      const hz = zOver ?? zSign * (SHO_W + 0.6);
      const hand = v(P[handK], hz);
      const elbow = v(P[elbowK], lerp(shoulder.z, hz, 0.5) + zSign * 1.4);
      boneTo(A.upper, shoulder, elbow, 14);
      boneTo(A.fore, elbow, hand, 13);
      A.hand.position.copy(hand);
      A.hand.quaternion.copy(A.fore.quaternion);
      if (A.sleeve) {
        const e2 = V3().lerpVectors(shoulder, elbow, 0.42);
        boneTo(A.sleeve, shoulder, e2, 4.2);
        A.sleeve.scale.y = Math.max(0.6, A.sleeve.scale.y);
      }
    };
    armSide('n', 'elbow', 'hand', 1, x.handZ);
    armSide('f', 'elbow2', 'hand2', -1, x.hand2Z);

    // Neck and head.
    const hd = v(P.head, 0);
    const neckTop = V3().lerpVectors(sh, hd, 0.55);
    boneTo(this.neck, V3(sh.x, sh.y - 1, 0), neckTop, 5);
    this.head.position.copy(hd);
    this.head.rotation.set(0, (x.headYaw || 0) * RAD, -(P.headTilt || 0) * RAD - (x.headLean || 0) * RAD);

    // Skirt follows the thighs.
    if (this.skirt) {
      const waist = V3().lerpVectors(hip, sh, 0.2);
      const kneeMid = V3().lerpVectors(ln.k, lf.k, 0.5);
      kneeMid.z = 0;
      _tmpV.subVectors(kneeMid, waist);
      const len = _tmpV.length();
      _tmpV.normalize();
      this.skirt.position.copy(waist);
      this.skirt.quaternion.setFromUnitVectors(V3(0, -1, 0), _tmpV.lerp(V3(0, -1, 0), 0.25).normalize());
      const spread = Math.abs(ln.k.x - lf.k.x);
      this.skirt.scale.set(0.92 + spread / 60, (len * 0.82) / 14, 0.92);
    }
  }

  /** World position of a point given in this person's figure units. */
  toWorld(p, z = 0) {
    return this.body.localToWorld(V3(p[0], -p[1], z));
  }
}

/* ------------------------------------------------------------------ *
 *  Props: small 3D objects for the scenes. All in figure units.
 * ------------------------------------------------------------------ */
/**
 * Boat hull from a side profile (x, y), extruded across (z) and narrowed
 * towards the bow (-x). Centred on z = 0.
 */
function hullGeo(key, pts, depth, bowFrom, bowTo, bevel = 2.5) {
  return geo(key, () => {
    const sh = new T3.Shape();
    sh.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i += 1) {
      const p = pts[i];
      if (p.length === 4) sh.quadraticCurveTo(p[2], p[3], p[0], p[1]);
      else sh.lineTo(p[0], p[1]);
    }
    const g = new T3.ExtrudeGeometry(sh, { depth, bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 3, curveSegments: 10 });
    g.translate(0, 0, -depth / 2);
    const pp = g.attributes.position;
    for (let i = 0; i < pp.count; i += 1) {
      const x = pp.getX(i);
      if (x < bowFrom) {
        const f = clamp((bowFrom - x) / (bowFrom - bowTo), 0, 1);
        pp.setZ(i, pp.getZ(i) * (1 - f * f * 0.9));
      }
    }
    g.computeVertexNormals();
    return g;
  });
}

const PROPS = {
  /** Park bench, seat front edge along +z, length along x. */
  bench() {
    const g = new T3.Group();
    const wood = mat('#9A6E48', { rough: 0.8 });
    const wood2 = mat('#875F3D', { rough: 0.8 });
    const metal = mat('#2E3440', { rough: 0.5, metal: 0.4 });
    const box = (w, h, d, m, x, y, z, rx = 0) => {
      const b = mesh(geo(`box-${w}-${h}-${d}`, () => new T3.BoxGeometry(w, h, d)), m);
      b.position.set(x, y, z);
      b.rotation.x = rx;
      g.add(b);
      return b;
    };
    // Seat planks (top at y = 21), backrest leaning back.
    [0, 1, 2].forEach((i) => box(80, 1.6, 5.2, i % 2 ? wood2 : wood, 0, 20.2, 7 - i * 6.2));
    [0, 1].forEach((i) => box(80, 5.4, 1.6, i % 2 ? wood2 : wood, 0, 30 + i * 8.5, -9.5 - i * 1.4, -0.16));
    // Legs and arm rests.
    [-34, 34].forEach((x) => {
      box(2.4, 20, 2.4, metal, x, 10, 7);
      box(2.4, 20, 2.4, metal, x, 10, -9);
      box(2.4, 22, 2.4, metal, x, 32, -11.5, -0.16);
      box(2.4, 2.4, 18, metal, x, 19, -1);
      box(2.6, 2.4, 16, metal, x, 27, -1);
      box(2.4, 8, 2.4, metal, x, 23.5, 6.5);
    });
    return g;
  },

  /** A gnarly root lying across the path (along z). */
  root() {
    const g = new T3.Group();
    const m = mat('#6B4A33', { rough: 0.95 });
    const pts = [[-1, -52], [2, -38], [-2, -24], [1.5, -10], [-1, 4], [2, 18], [0, 30]];
    for (let i = 0; i < pts.length - 1; i += 1) {
      const a = V3(pts[i][0], 0.6 + Math.sin(i * 1.7) * 0.7, pts[i][1]);
      const b = V3(pts[i + 1][0], 0.6 + Math.sin((i + 1) * 1.7) * 0.7, pts[i + 1][1]);
      const r = 2.4 - i * 0.18;
      const c = mesh(capGeo(r, 14), m);
      boneTo(c, a, b, 14);
      g.add(c);
    }
    // Small side shoots.
    [[0, -38, 1], [0, 4, -1]].forEach(([x, z, sd]) => {
      const c = mesh(capGeo(1.1, 6), m);
      boneTo(c, V3(x, 0.8, z), V3(x + sd * 6, 0.4, z + 3), 6);
      g.add(c);
    });
    return g;
  },

  /** Flat puddle. */
  puddle() {
    const m = new T3.Mesh(geo('puddle', () => {
      const c = new T3.CircleGeometry(1, 32);
      c.rotateX(-Math.PI / 2);
      return c;
    }), new T3.MeshStandardMaterial({ color: '#6F98C8', roughness: 0.08, metalness: 0.35, transparent: true, opacity: 0.85 }));
    m.scale.set(17, 1, 9);
    m.receiveShadow = true;
    return m;
  },

  /** Umbrella: origin at the handle grip, shaft up along +y. */
  umbrella() {
    const g = new T3.Group();
    const shaft = mesh(geo('umb-shaft', () => {
      const c = new T3.CylinderGeometry(0.45, 0.45, 40, 6);
      c.translate(0, 20, 0);
      return c;
    }), mat('#2A3445', { rough: 0.4 }));
    g.add(shaft);
    const hook = mesh(geo('umb-hook', () => new T3.TorusGeometry(2.2, 0.55, 6, 12, Math.PI)), mat('#2A3445', { rough: 0.4 }));
    hook.rotation.set(0, 0, Math.PI);
    hook.position.set(-2.2, 0, 0);
    g.add(hook);
    const canopy = new T3.Group();
    canopy.position.y = 33;
    const cg = geo('umb-canopy', () => {
      const s = new T3.SphereGeometry(28, 16, 8, 0, Math.PI * 2, 0, Math.PI * 0.42);
      s.scale(1, 0.5, 1);
      // Scalloped rim between the ribs.
      const p = s.attributes.position;
      for (let i = 0; i < p.count; i += 1) {
        const x = p.getX(i);
        const z = p.getZ(i);
        const a = Math.atan2(z, x);
        const r = Math.hypot(x, z) / 28;
        p.setY(i, p.getY(i) + Math.abs(Math.sin(a * 4)) * r * r * 2.4);
      }
      s.computeVertexNormals();
      return s;
    });
    const top = mesh(cg, mat('#FF7A1A', { side: T3.DoubleSide, rough: 0.6 }));
    top.position.y = -4;
    canopy.add(top);
    const tip = blob('#2A3445', 0.9, 2.2, 0.9);
    tip.position.y = 11;
    canopy.add(tip);
    g.add(canopy);
    g.userData.canopy = canopy;
    return g;
  },

  /** Ice cream cone; origin where the hand holds it, scoop up. */
  iceCream() {
    const g = new T3.Group();
    const cone = mesh(geo('cone', () => {
      const c = new T3.ConeGeometry(2.4, 9, 12);
      c.rotateX(Math.PI);
      c.translate(0, 1.5, 0);
      return c;
    }), mat('#D9A45A', { rough: 0.9 }));
    g.add(cone);
    const scoop = blob('#FF9BB3', 3.1, 2.8, 3.1, { rough: 0.55 });
    scoop.position.y = 7.4;
    g.add(scoop);
    g.userData.scoop = scoop;
    return g;
  },

  /** Phone, screen facing -x (towards the person holding it up). */
  phone() {
    const g = new T3.Group();
    const b = mesh(geo('phone', () => new T3.BoxGeometry(0.9, 8.4, 4.4)), mat('#11161D', { rough: 0.35 }));
    g.add(b);
    const scr = mesh(geo('phone-s', () => new T3.BoxGeometry(0.1, 7.2, 3.6)), mat('#3D8BFF', { emissive: '#3D8BFF', emissiveIntensity: 0.7 }), false);
    scr.position.x = -0.5;
    g.add(scr);
    return g;
  },

  /** Sailboat; waterline at y = 0, bow towards -x (it sails to the left). */
  sailboat() {
    const g = new T3.Group();
    const profile = [[44, 10], [42, -1], [-24, -4, 10, -5], [-58, 11, -50, -2], [-60, 13], [44, 12]];
    const hull = mesh(hullGeo('hull-s', profile, 22, -14, -62), mat('#1F3A5F', { rough: 0.45 }));
    g.add(hull);
    const band = mesh(hullGeo('band-s', [[45, 8.5], [-52, 8.5, -10, 7], [-55, 10.5], [45, 10.5]], 22.6, -14, -62, 2.6), mat('#F2F6FB', { rough: 0.5 }));
    g.add(band);
    const deck = mesh(geo('deck-s', () => new T3.BoxGeometry(80, 1.2, 20)), mat('#D9C7A4', { rough: 0.8 }));
    deck.position.set(-2, 12.6, 0);
    g.add(deck);
    const mast = mesh(geo('mast', () => {
      const c = new T3.CylinderGeometry(1, 1.2, 150, 6);
      c.translate(0, 75, 0);
      return c;
    }), mat('#E8EDF4', { rough: 0.4 }));
    mast.position.set(4, 12, 0);
    g.add(mast);
    const tri = (a, b, c, color, key) => {
      const geom = geo(key, () => {
        const t = new T3.BufferGeometry();
        t.setAttribute('position', new T3.Float32BufferAttribute([...a, ...b, ...c], 3));
        t.computeVertexNormals();
        return t;
      });
      const m = mesh(geom, mat(color, { side: T3.DoubleSide, rough: 0.7 }));
      m.receiveShadow = false;
      g.add(m);
      return m;
    };
    tri([5, 20, 0], [5, 158, 0], [52, 22, 0], '#F6F8FB', 'sail-main');
    tri([3, 22, 0], [3, 140, 0], [-48, 18, 0], '#FFC9A0', 'sail-jib');
    return g;
  },

  /** Motorboat; waterline at y = 0, bow towards -x. */
  motorboat() {
    const g = new T3.Group();
    const profile = [[42, 9], [41, -1], [-26, -3, 8, -4], [-60, 9, -52, -2], [-62, 11], [42, 11]];
    const hull = mesh(hullGeo('hull-m', profile, 26, -18, -64), mat('#F4F6F8', { rough: 0.3 }));
    g.add(hull);
    const stripe = mesh(hullGeo('stripe-m', [[43, 4], [-48, 4, -8, 3], [-54, 6.4], [43, 6.4]], 26.6, -18, -64, 2.6), mat('#FF5F52', { rough: 0.5 }));
    g.add(stripe);
    const cabin = mesh(geo('cabin', () => new T3.BoxGeometry(24, 10, 20)), mat('#DCE4EE', { rough: 0.5 }));
    cabin.position.set(10, 17, 0);
    g.add(cabin);
    const glass = mesh(geo('glass', () => new T3.BoxGeometry(2, 10, 19)), mat('#3D8BFF', { rough: 0.15, metal: 0.3 }));
    glass.position.set(-4, 17, 0);
    glass.rotation.z = -0.6;
    g.add(glass);
    const roof = mesh(geo('roof-m', () => new T3.BoxGeometry(28, 1.4, 22)), mat('#2A3445', { rough: 0.5 }));
    roof.position.set(9, 22.6, 0);
    g.add(roof);
    // Wake: soft white stripes behind (towards +x).
    const wm = new T3.MeshBasicMaterial({ color: '#F4FAFF', transparent: true, opacity: 0.7, depthWrite: false });
    const wake = new T3.Group();
    [-1, 1].forEach((sd) => {
      const w = new T3.Mesh(geo('wake', () => {
        const pl = new T3.PlaneGeometry(1, 1, 8, 1);
        pl.rotateX(-Math.PI / 2);
        pl.translate(0.5, 0, 0);
        return pl;
      }), wm);
      w.scale.set(150, 1, 6);
      w.rotation.y = sd * 0.18;
      w.position.set(60, 0.6, sd * 14);
      wake.add(w);
    });
    g.add(wake);
    g.userData.wake = wake;
    return g;
  },
};

/** Small drops (splashes, drips, sweat) in world space. */
class Drops3D {
  constructor(scene, n = 40, color = '#9CC3F0') {
    this.m = new T3.InstancedMesh(lowSphereGeo(), new T3.MeshStandardMaterial({ color, roughness: 0.2, metalness: 0.1, transparent: true, opacity: 0.9 }), n);
    this.m.frustumCulled = false;
    this.list = Array.from({ length: n }, () => ({ age: 1, p: V3(), v: V3(), life: 1, size: 1, ground: 0 }));
    this.m4 = new T3.Matrix4();
    this.q = new T3.Quaternion();
    scene.add(this.m);
  }

  emit(p, v, life = 0.7, size = 1, ground = -1e9) {
    const d = this.list.find((q) => q.age >= 1);
    if (!d) return;
    d.age = 0;
    d.p.copy(p);
    d.v.copy(v);
    d.life = life;
    d.size = size;
    d.ground = ground;
  }

  /** Moves all drops sideways (new round of the route). */
  shift(dx) {
    this.list.forEach((d) => { d.p.x += dx; });
  }

  step(dt) {
    this.list.forEach((d, i) => {
      if (d.age >= 1) {
        this.m4.makeScale(0, 0, 0);
        this.m.setMatrixAt(i, this.m4);
        return;
      }
      d.age += dt / d.life;
      d.v.y -= 380 * dt;
      d.p.addScaledVector(d.v, dt);
      if (d.p.y < d.ground) { d.p.y = d.ground; d.v.set(0, 0, 0); }
      const s = d.size * (1 - d.age * 0.5);
      this.m4.compose(d.p, this.q, V3(s * 0.8, s * 1.2, s * 0.8));
      this.m.setMatrixAt(i, this.m4);
    });
    this.m.instanceMatrix.needsUpdate = true;
  }
}

/* ------------------------------------------------------------------ *
 *  Dino3D: a friendly green dinosaur. Faces +x, feet on y = 0.
 *  pose(o) takes the same angles as the side view version:
 *    lean, head, jaw, tail, arm in degrees (positive = clockwise in the
 *    side view, i.e. nose down / jaw open / tail up / arm down)
 *    brow 'angry' | 'surprised' | 'sad', pupil size, tear 0..1 or -1
 *    legs: { near: [hip, knee, ankle, footAng], far: [...] } side view points
 * ------------------------------------------------------------------ */
class Dino3D {
  constructor() {
    const G = '#58A846';
    const GD = '#3E7F33';
    const BELLY = '#D4E59A';
    const mG = mat(G, { rough: 0.7 });
    const mGD = mat(GD, { rough: 0.75 });
    this.root = new T3.Group();
    this.body = new T3.Group();
    this.root.add(this.body);

    // Legs (near +z, far -z).
    this.legs = {};
    [['near', 8.5, mG], ['far', -8.5, mGD]].forEach(([k, z, m]) => {
      const L = {
        z,
        thigh: mesh(geo('dthigh', () => new T3.CapsuleGeometry(6.2, 13, 6, 14)), m),
        shin: mesh(capGeo(3.6, 20), m),
        foot: new T3.Group(),
      };
      const f = mesh(geo('dfoot', () => {
        const g = new T3.CapsuleGeometry(3.2, 9, 4, 10);
        g.rotateZ(Math.PI / 2);
        g.scale(1, 0.7, 1.25);
        g.translate(4.5, -1, 0);
        return g;
      }), m);
      L.foot.add(f);
      [-2.2, 0, 2.2].forEach((dz) => {
        const c = mesh(geo('dclaw', () => {
          const g = new T3.ConeGeometry(0.9, 3, 6);
          g.rotateZ(-Math.PI / 2);
          return g;
        }), mat('#F2F6FB', { rough: 0.4 }), false);
        c.position.set(11.6, -2.2, dz);
        L.foot.add(c);
      });
      this.body.add(L.thigh);
      this.body.add(L.shin);
      this.body.add(L.foot);
      this.legs[k] = L;
    });

    // Upper body: pivots around the hip (0, 38).
    this.up = new T3.Group();
    this.up.position.set(0, 38, 0);
    this.body.add(this.up);
    const U = new T3.Group();
    U.position.set(0, -38, 0);
    this.up.add(U);
    const torso = blob(G, 27, 19, 16.5, { material: mG });
    torso.position.set(-2, 50, 0);
    torso.rotation.z = 0.25;
    U.add(torso);
    const belly = blob(BELLY, 15, 15, 12.5, { material: mat(BELLY, { rough: 0.8 }) });
    belly.position.set(10, 47, 0);
    belly.rotation.z = 0.35;
    U.add(belly);
    // Spots and back spikes.
    [[-12, 64, 9, 3], [-2, 68, 10, 2.6], [-20, 54, 12, 2.2], [-8, 58, -13, 2.8], [4, 63, -11, 2.2]].forEach(([x, y, z, r]) => {
      const s = blob(GD, r, r * 0.7, r, { material: mGD, shadow: false });
      s.position.set(x, y, z);
      U.add(s);
    });
    [[-30, 62, 0.9], [-20, 68, 0.75], [-9, 72, 0.6], [2, 73, 0.4], [-40, 56, 1.1]].forEach(([x, y, rz]) => {
      const sp = mesh(geo('dspike', () => new T3.ConeGeometry(3.2, 8, 6)), mGD);
      sp.position.set(x, y, 0);
      sp.rotation.z = rz;
      U.add(sp);
    });
    // Tail: three segments, the pivot at the back of the body.
    this.tail = new T3.Group();
    this.tail.position.set(-16, 52, 0);
    U.add(this.tail);
    let parent = this.tail;
    this.tailSegs = [];
    [[13, 22], [9, 20], [5.5, 18], [3, 14]].forEach(([r, len], i) => {
      const seg = new T3.Group();
      if (i > 0) seg.position.set(-[22, 20, 18][i - 1], -2.5, 0);
      const m = mesh(capGeo(r, len), i % 2 ? mGD : mG);
      m.rotation.z = Math.PI / 2 + 0.12;
      m.position.set(-len / 2, -1.2, 0);
      m.scale.set(1, 1, 0.85);
      seg.add(m);
      parent.add(seg);
      parent = seg;
      this.tailSegs.push(seg);
    });
    // Little arms.
    this.arms = [];
    [9, -9].forEach((z) => {
      const a = new T3.Group();
      a.position.set(16, 52, z);
      const up = mesh(capGeo(2.2, 6), z > 0 ? mG : mGD);
      up.rotation.z = -1.1;
      up.position.set(3, -2, 0);
      a.add(up);
      [-0.8, 0.8].forEach((dz) => {
        const c = mesh(geo('dclaw', () => null), mat('#F2F6FB', { rough: 0.4 }), false);
        c.position.set(7.5, -5.4, dz);
        c.rotation.z = -0.6;
        a.add(c);
      });
      U.add(a);
      this.arms.push(a);
    });

    // Neck and head: the head pivots at (16, 68).
    this.head = new T3.Group();
    this.head.position.set(16, 68, 0);
    U.add(this.head);
    const Hd = new T3.Group();
    Hd.position.set(-16, -68, 0);
    this.head.add(Hd);
    const neck = mesh(capGeo(8.5, 14), mG);
    neck.position.set(16, 70, 0);
    neck.rotation.z = -0.9;
    Hd.add(neck);
    const skull = blob(G, 21, 11.5, 12, { material: mG });
    skull.position.set(32, 82, 0);
    skull.rotation.z = -0.08;
    Hd.add(skull);
    const brow = blob(G, 9, 6, 11.5, { material: mG });
    brow.position.set(30, 88, 0);
    Hd.add(brow);
    // Upper teeth.
    const tm = mat('#FBFBF5', { rough: 0.3 });
    const tooth = geo('dtooth', () => {
      const g = new T3.ConeGeometry(1.1, 3.4, 5);
      g.rotateX(Math.PI);
      return g;
    });
    for (let i = 0; i < 7; i += 1) {
      [1, -1].forEach((sd) => {
        const tt = mesh(tooth, tm, false);
        const x = 30 + i * 3.4;
        tt.position.set(x, 74.2 - i * 0.1, sd * (9.2 - i * 0.7));
        Hd.add(tt);
      });
    }
    // Mouth inside, visible when the jaw opens.
    const inside = blob('#7A2430', 18, 5.5, 9.5, { material: mat('#7A2430', { rough: 0.8 }), shadow: false });
    inside.position.set(33, 73.5, 0);
    Hd.add(inside);
    // Jaw (pivot at 16, 70).
    this.jaw = new T3.Group();
    this.jaw.position.set(16, 72, 0);
    Hd.add(this.jaw);
    const J = new T3.Group();
    J.position.set(-16, -72, 0);
    this.jaw.add(J);
    const jawM = blob(G, 19.5, 5, 10.5, { material: mG });
    jawM.position.set(33, 69.5, 0);
    J.add(jawM);
    const chin = blob(BELLY, 15, 3, 8.5, { material: mat(BELLY, { rough: 0.8 }), shadow: false });
    chin.position.set(34, 66.8, 0);
    J.add(chin);
    const tooth2 = geo('dtooth2', () => new T3.ConeGeometry(1, 3, 5));
    for (let i = 0; i < 6; i += 1) {
      [1, -1].forEach((sd) => {
        const tt = mesh(tooth2, tm, false);
        tt.position.set(32 + i * 3.4, 74.5, sd * (8.2 - i * 0.7));
        J.add(tt);
      });
    }
    // Eyes, brows, nostrils, tear.
    this.pupils = [];
    this.browsD = [];
    [1, -1].forEach((sd) => {
      const eye = blob('#FFFFFF', 3.4, 3.8, 3.0, { material: mat('#FFFFFF', { rough: 0.3 }), shadow: false });
      eye.position.set(37, 86.5, sd * 8.6);
      Hd.add(eye);
      const pu = blob('#11161D', 1.6, 2.0, 1.4, { material: mat('#11161D', { rough: 0.2 }), shadow: false });
      pu.position.set(39.6, 86.6, sd * 9.8);
      Hd.add(pu);
      this.pupils.push(pu);
      const b = new T3.Group();
      b.position.set(37, 91.2, sd * 8.8);
      const bm = mesh(capGeo(0.9, 6), mat('#2C5A26'), false);
      bm.rotation.z = Math.PI / 2;
      b.add(bm);
      Hd.add(b);
      this.browsD.push(b);
      const n = blob('#2C5A26', 0.9, 0.7, 0.7, { shadow: false });
      n.position.set(52.4, 84.5, sd * 3.5);
      Hd.add(n);
    });
    this.tear = blob('#8FC4F5', 1.1, 1.6, 1.1, { material: mat('#8FC4F5', { unique: true, opacity: 0.9, rough: 0.1 }), shadow: false });
    this.tear.position.set(36, 82, 11.5);
    this.tear.visible = false;
    Hd.add(this.tear);
    // Roar: rings in front of the mouth.
    this.roarM = new T3.MeshBasicMaterial({ color: '#F2F6FB', transparent: true, opacity: 0, depthWrite: false, side: T3.DoubleSide });
    this.roar = new T3.Group();
    [0, 1, 2].forEach((i) => {
      const r = new T3.Mesh(geo(`roar${i}`, () => {
        const g = new T3.TorusGeometry(6 + i * 5, 0.7, 4, 20, Math.PI * 0.8);
        g.rotateZ(-Math.PI * 0.4);
        g.rotateY(Math.PI / 2);
        return g;
      }), this.roarM);
      r.position.set(58 + i * 7, 76, 0);
      this.roar.add(r);
    });
    Hd.add(this.roar);
    this.root.traverse((m) => { if (m.isMesh && m.material === this.roarM) m.castShadow = false; });
  }

  pose(o) {
    this.up.rotation.z = -(o.lean || 0) * RAD;
    this.up.position.y = 38 + (o.bob || 0);
    this.head.rotation.z = -(o.head || 0) * RAD;
    this.jaw.rotation.z = -(o.jaw || 0) * RAD;
    const tl = -(o.tail || 0) * RAD;
    this.tail.rotation.z = tl;
    this.tailSegs.forEach((s, i) => { if (i > 0) s.rotation.z = tl * 0.35 + Math.sin((o.t || 0) * 3 + i) * 0.04; });
    this.arms.forEach((a) => { a.rotation.z = -(o.arm || 0) * RAD; });
    const brow = o.brow || 'angry';
    this.browsD.forEach((b, i) => {
      // Brow tilt around the axis across the head.
      const sd = i === 0 ? 1 : -1;
      if (brow === 'angry') { b.rotation.set(0, 0, -0.35); b.position.y = 90.6; }
      else if (brow === 'surprised') { b.rotation.set(0, 0, 0); b.position.y = 93; }
      else { b.rotation.set(0, 0, 0.35); b.position.y = 91.4; }
      b.rotation.x = sd * 0.05;
    });
    this.pupils.forEach((p) => p.scale.set((o.pupil || 2) * 0.8, (o.pupil || 2), (o.pupil || 2) * 0.7));
    this.tear.visible = o.tear >= 0;
    if (o.tear >= 0) {
      this.tear.position.y = 82 - o.tear * 14;
      this.tear.material.opacity = 0.9 * (1 - o.tear);
    }
    this.roarM.opacity = o.roar || 0;
    this.roar.scale.setScalar(1 + (o.roar || 0) * 0.15 * Math.sin((o.t || 0) * 30));
    // Legs from side view points.
    ['near', 'far'].forEach((k) => {
      const L = this.legs[k];
      const [hip, knee, ankle, ang] = o.legs[k];
      const h = V3(hip[0], -hip[1], L.z);
      const kn = V3(knee[0], -knee[1], L.z);
      const an = V3(ankle[0], -ankle[1], L.z);
      boneTo(L.thigh, h, kn, 13 + 6.2);
      boneTo(L.shin, kn, an, 20);
      L.foot.position.copy(an);
      L.foot.rotation.set(0, 0, -(ang || 0) * RAD);
    });
  }
}

/* ------------------------------------------------------------------ *
 *  World3D: renderer, camera, light, sky, weather and a landscape along
 *  a looping route. The route runs along +x; the path is at z = 0, the
 *  camera looks from +z. Everything is periodic over the route length,
 *  so the loop restarts without a visible jump.
 *
 *  route = {
 *    length          route length in figure units
 *    height(x)       path height at x (periodic)
 *    beach(x)        0..1, how much the land at x opens to the sea
 *  }
 * ------------------------------------------------------------------ */
const PATH_Z0 = -40;   // back edge of the path
const PATH_Z1 = 24;    // front edge of the path
const SEA_Y = -16;
const MOUNT_P = 20 * 620; // the mountains repeat after this distance

/**
 * Bare branches of a leaf tree in winter, in trunk units (trunk top at
 * y = 70). Shared by all leaf trees; each one is turned a little.
 */
function bareCrownGeo() {
  return geo('bare-crown', () => {
    const parts = [];
    const twig = (a, b, r0, r1, seg) => {
      const d = new T3.Vector3().subVectors(b, a);
      const g = new T3.CylinderGeometry(r1, r0, d.length(), seg, 1, true);
      g.applyQuaternion(new T3.Quaternion().setFromUnitVectors(UP, d.clone().normalize()));
      const m = new T3.Vector3().addVectors(a, b).multiplyScalar(0.5);
      g.translate(m.x, m.y, m.z);
      parts.push(g);
    };
    const main = [
      [[0, 56, 0], [-34, 104, 8], 2.6],
      [[0, 62, 0], [32, 110, -6], 2.6],
      [[0, 64, 0], [3, 132, 2], 3.0],
      [[0, 58, 0], [-10, 98, -28], 2.0],
      [[0, 60, 0], [12, 100, 28], 2.0],
    ];
    main.forEach(([a0, b0, r], i) => {
      const a = V3(...a0);
      const b = V3(...b0);
      twig(a, b, r, r * 0.42, 5);
      const d = b.clone().sub(a).normalize();
      const h = V3(d.x, 0, d.z);
      if (h.lengthSq() < 0.01) h.set(hash1(i) - 0.5, 0, 0.5);
      h.normalize();
      // Side twig from the middle, two at the tip.
      const m = a.clone().lerp(b, 0.5);
      twig(m, m.clone().add(V3(h.x * 18 + (hash1(i * 3) - 0.5) * 10, 16, h.z * 18 + (hash1(i * 5) - 0.5) * 12)), r * 0.45, r * 0.14, 4);
      twig(b, b.clone().add(V3(h.x * 11 + 7, 13, h.z * 11 - 5)), r * 0.4, r * 0.12, 4);
      twig(b, b.clone().add(V3(h.x * 11 - 7, 11, h.z * 11 + 6)), r * 0.38, r * 0.12, 4);
    });
    return mergeGeos(parts);
  });
}

class World3D {
  constructor(canvas, route) {
    this.canvas = canvas;
    this.route = route;
    this.L = route.length;
    // The way: a footpath (default) or a road with markings.
    this.style = route.style || 'path';
    this.z0 = route.z0 ?? PATH_Z0;
    this.z1 = route.z1 ?? PATH_Z1;
    this.t = 0;
    this.look = { cloud: 0.3, rain: 0, snow: false, wind: 6, hot: 0, cold: 0 };
    this.mood = {};

    const r = new T3.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'low-power' });
    r.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    r.shadowMap.enabled = true;
    r.shadowMap.type = T3.PCFShadowMap;
    r.toneMapping = T3.ACESFilmicToneMapping;
    r.toneMappingExposure = 1.05;
    this.renderer = r;

    const s = new T3.Scene();
    this.scene = s;
    this.camera = new T3.PerspectiveCamera(30, 2, 5, 9000);
    s.add(this.camera);
    s.fog = new T3.Fog('#9CC6EA', 900, 5200);

    // Light: soft sky light plus the sun with shadows.
    this.hemi = new T3.HemisphereLight('#CFE6FF', '#4A5A3A', 1.15);
    s.add(this.hemi);
    const sun = new T3.DirectionalLight('#FFF4E0', 2.4);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    const sc = sun.shadow.camera;
    sc.left = -300; sc.right = 300; sc.top = 260; sc.bottom = -200; sc.near = 10; sc.far = 2400;
    sun.shadow.bias = -0.0004;
    sun.shadow.normalBias = 0.6;
    s.add(sun);
    s.add(sun.target);
    this.sun = sun;


    this._ground();
    this._sea();
    this._trees();
    this._details();
    this._mountains();
    this._clouds();
    this._sunSprite();
    this._precip();
    this._puffs();
    this._leaves();
    this.camPos = null;
    // A new round of the route moves x back by one length. xOff keeps the
    // far things (clouds, mountains, waves) running on without a jump, and
    // onWrap tells the scene to move what it keeps in world positions.
    this.xOff = 0;
    this.onWrap = [];
    this.setLook(this.look, {});
  }

  /* ------------------------------ landscape ------------------------------ */

  /** Ground height at (x, z). */
  heightAt(x, z) {
    const R = this.route;
    const xw = wrap(x, 0, this.L);
    const p = R.height(xw);
    const L = this.L;
    const tau = Math.PI * 2;
    const z0 = this.z0;
    const z1 = this.z1;
    if (z >= z0 && z <= z1) return p;
    if (z > z1) {
      const zf = z - z1;
      return p - zf * 0.08 - Math.max(0, zf - 140) * 0.35 + Math.sin((tau * 9 * xw) / L + zf * 0.02) * Math.min(1, zf / 60) * 2.5;
    }
    const zz = z0 - z;
    const b = R.beach(xw);
    // Meadow: rises into soft hills behind the path, falls to the sea far away.
    let y = p * Math.exp(-zz / 420)
      + 80 * (1 - Math.exp(-Math.max(0, zz - 60) / 320))
      + 34 * Math.sin((tau * 3 * xw) / L + zz * 0.004) * clamp(zz / 220, 0, 1)
      + 16 * Math.sin((tau * 8 * xw) / L + 1.3 + zz * 0.007) * clamp(zz / 300, 0, 1)
      - Math.max(0, zz - 760) * 0.55;
    // Ridge right behind the path edge.
    y += Math.sin(zz * 0.08) * 1.4 * clamp(zz / 30, 0, 1) * clamp((120 - zz) / 60, 0, 1);
    if (b > 0) {
      // Beach: sand slopes down into the sea.
      const sand = p - zz * 0.06 - Math.max(0, zz - 72) * 0.9;
      y = lerp(y, Math.max(sand, SEA_Y - 40), b);
    }
    return y;
  }

  _ground() {
    const L = this.L;
    // The land is built for one round of the route (0..L) and shown again
    // one, two... rounds to each side, so even a very wide card never sees
    // where it stops, and a new round starts without any jump. The grid
    // spacing fits L exactly, so all copies match down to every vertex.
    const cols = Math.round(L / 8);
    const step = L / cols;
    const x0 = 0;
    const z0 = this.z0;
    const z1 = this.z1;
    const back = [-1500, -1200, -1000, -860, -760, -660, -560, -470, -390, -320, -260, -210, -170, -135, -110, -90, -74, -62, -52, -46]
      .map((z) => z + (z0 - PATH_Z0)).filter((z) => z < z0 - 3);
    const front = [z1 + 6, 40, 60, 85, 115, 150, 200, 260, 330].map((z) => z + (z1 - PATH_Z1)).filter((z) => z > z1 + 3);
    const zs = [...back, z0 - 2, z0, (z0 + z1) / 2, z1 - 4, z1, ...front];
    const rows = zs.length;
    const pos = new Float32Array((cols + 1) * rows * 3);
    const col = new Float32Array((cols + 1) * rows * 3);
    const idx = [];
    let k = 0;
    for (let i = 0; i <= cols; i += 1) {
      const x = i === cols ? L : x0 + i * step;
      for (let j = 0; j < rows; j += 1) {
        const z = zs[j];
        pos[k] = x; pos[k + 1] = this.heightAt(x, z); pos[k + 2] = z;
        k += 3;
      }
    }
    for (let i = 0; i < cols; i += 1) {
      for (let j = 0; j < rows - 1; j += 1) {
        const a = i * rows + j;
        const b = (i + 1) * rows + j;
        idx.push(a, a + 1, b, b, a + 1, b + 1);
      }
    }
    const g = new T3.BufferGeometry();
    g.setAttribute('position', new T3.BufferAttribute(pos, 3));
    g.setAttribute('color', new T3.BufferAttribute(col, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    // First and last column are the same place one round apart: same normal.
    const nr = g.attributes.normal;
    for (let j = 0; j < rows; j += 1) {
      const a = j;
      const b = cols * rows + j;
      const n = V3(nr.getX(a) + nr.getX(b), nr.getY(a) + nr.getY(b), nr.getZ(a) + nr.getZ(b)).normalize();
      nr.setXYZ(a, n.x, n.y, n.z);
      nr.setXYZ(b, n.x, n.y, n.z);
    }
    this.groundGeo = g;
    this.groundZ = zs;
    this.gStep = step;
    this.gCols = cols;
    // Drawn in pieces of about 900 units (each a view on the same data, so
    // painting the land once paints all): pieces out of view are skipped.
    const gm = new T3.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, metalness: 0 });
    const np = Math.max(1, Math.round(cols / 110));
    const K = Math.ceil(4300 / L);
    const nor = g.attributes.normal.array;
    this.groundPieces = [];
    for (let q = 0; q < np; q += 1) {
      const c0 = Math.round((q * cols) / np);
      const c1 = Math.round(((q + 1) * cols) / np);
      const v0 = c0 * rows * 3;
      const v1 = (c1 + 1) * rows * 3;
      const pg = new T3.BufferGeometry();
      pg.setAttribute('position', new T3.BufferAttribute(pos.subarray(v0, v1), 3));
      pg.setAttribute('normal', new T3.BufferAttribute(nor.subarray(v0, v1), 3));
      pg.setAttribute('color', new T3.BufferAttribute(col.subarray(v0, v1), 3));
      const pi = [];
      for (let i = 0; i < c1 - c0; i += 1) {
        for (let j = 0; j < rows - 1; j += 1) {
          const a = i * rows + j;
          const b = (i + 1) * rows + j;
          pi.push(a, a + 1, b, b, a + 1, b + 1);
        }
      }
      pg.setIndex(pi);
      pg.computeBoundingSphere();
      this.groundPieces.push(pg);
      for (let r = -K; r <= K; r += 1) {
        const piece = new T3.Mesh(pg, gm);
        piece.position.x = r * L;
        piece.receiveShadow = true;
        this.scene.add(piece);
      }
    }

    // The path: its own strip on top, so its edges stay crisp.
    const x1 = L + 1800;
    const step6 = L / Math.round(L / 6);
    this.pStep = step6;
    this.pCols = Math.round(L / 6);
    const px0 = Math.floor(-2500 / step6) * step6;
    const pc = Math.ceil((x1 - px0) / step6);
    const pz = this.style === 'road'
      ? [z0 + 1, z0 + 4, (z0 + z1) / 2, z1 - 4, z1 - 1]
      : [z0 + 2, z0 + 6, (z0 + z1) / 2, z1 - 6, z1 - 2];
    const pp = new Float32Array((pc + 1) * pz.length * 3);
    const pcol = new Float32Array((pc + 1) * pz.length * 3);
    const pidx = [];
    k = 0;
    for (let i = 0; i <= pc; i += 1) {
      const x = px0 + i * step6;
      for (let j = 0; j < pz.length; j += 1) {
        const edge = j === 0 || j === pz.length - 1;
        pp[k] = x; pp[k + 1] = this.route.height(wrap(x, 0, L)) + (edge ? 0.25 : 0.45); pp[k + 2] = pz[j];
        k += 3;
      }
    }
    for (let i = 0; i < pc; i += 1) {
      for (let j = 0; j < pz.length - 1; j += 1) {
        const a = i * pz.length + j;
        const b = (i + 1) * pz.length + j;
        pidx.push(a, a + 1, b, b, a + 1, b + 1);
      }
    }
    const pg = new T3.BufferGeometry();
    pg.setAttribute('position', new T3.BufferAttribute(pp, 3));
    pg.setAttribute('color', new T3.BufferAttribute(pcol, 3));
    pg.setIndex(pidx);
    pg.computeVertexNormals();
    this.pathGeo = pg;
    this.path = new T3.Mesh(pg, new T3.MeshStandardMaterial({ vertexColors: true, roughness: 0.9, metalness: 0 }));
    this.path.receiveShadow = true;
    this.scene.add(this.path);

    if (this.style === 'road') this._roadMarks(px0, x1, step6);
    // Pebbles in the path, fixed in the world.
    const n = this.style === 'road' ? 0 : Math.floor(L / 7);
    const peb = new T3.InstancedMesh(geo('pebble', () => new T3.IcosahedronGeometry(1, 0)), new T3.MeshStandardMaterial({ color: '#FFFFFF', roughness: 0.9, flatShading: true }), n * 3);
    const m4 = new T3.Matrix4();
    const q = new T3.Quaternion();
    let c = 0;
    for (let rep = -1; rep <= 1; rep += 1) {
      for (let i = 0; i < n; i += 1) {
        const x = i * 7 + (hash1(i) - 0.5) * 6 + rep * L;
        if (x < px0 || x > x1) continue;
        if (this.route.beach(wrap(x, 0, L)) > 0.4) continue;
        const z = lerp(z0 + 5, z1 - 5, hash1(i * 7 + 3));
        const r = 0.7 + hash1(i * 3 + 1) * 1.1;
        q.setFromAxisAngle(UP, hash1(i * 5) * 6.28);
        m4.compose(V3(x, this.route.height(wrap(x, 0, L)) + 0.3, z), q, V3(r * 1.3, r * 0.45, r));
        peb.setMatrixAt(c, m4);
        peb.setColorAt(c, new T3.Color().setHSL(0.08, 0.12, 0.42 + hash1(i * 11) * 0.22));
        c += 1;
      }
    }
    peb.count = c;
    peb.receiveShadow = true;
    this.pebbles = peb;
    this.scene.add(peb);
    this._paintGround();
  }

  /** Road: dashed centre line, edge lines and roadside posts. */
  _roadMarks(x0, x1, step6) {
    const L = this.L;
    const H = (x) => this.route.height(wrap(x, 0, L));
    const lineGeo = (z, w) => {
      const n = Math.ceil((x1 - x0) / step6);
      const pos = [];
      const idx = [];
      for (let i = 0; i <= n; i += 1) {
        const x = x0 + i * step6;
        const y = H(x) + 0.55;
        pos.push(x, y, z - w / 2, x, y, z + w / 2);
        if (i < n) idx.push(i * 2, i * 2 + 1, i * 2 + 2, i * 2 + 2, i * 2 + 1, i * 2 + 3);
      }
      const g = new T3.BufferGeometry();
      g.setAttribute('position', new T3.Float32BufferAttribute(pos, 3));
      g.setIndex(idx);
      g.computeVertexNormals();
      return g;
    };
    const lm = new T3.MeshStandardMaterial({ color: '#F2F4F6', roughness: 0.6 });
    const edges = [this.z0 + 4, this.z1 - 4].map((z) => {
      const m = new T3.Mesh(lineGeo(z, 2.2), lm);
      m.receiveShadow = true;
      this.scene.add(m);
      return m;
    });
    // Dashes: 3 m paint, 6 m gap (in figure units 150 and 300), fixed in the world.
    // Spacing fits the route length exactly, so a new round starts seamlessly.
    const cz = (this.z0 + this.z1) / 2;
    const dashSp = L / Math.max(1, Math.round(L / 120));
    const dash = new T3.InstancedMesh(geo('dash', () => new T3.BoxGeometry(1, 0.3, 2.4)), new T3.MeshStandardMaterial({ color: '#F2F4F6', roughness: 0.6 }), Math.ceil((x1 - x0) / dashSp) + 3);
    const m4 = new T3.Matrix4();
    const q = new T3.Quaternion();
    let c = 0;
    for (let i = Math.floor(x0 / dashSp); i * dashSp < x1; i += 1) {
      const x = i * dashSp;
      const xa = x;
      const xb = x + 70;
      const ya = H(xa);
      const yb = H(xb);
      q.setFromAxisAngle(V3(0, 0, 1), Math.atan2(yb - ya, xb - xa));
      m4.compose(V3((xa + xb) / 2, (ya + yb) / 2 + 0.6, cz), q, V3(70, 1, 1));
      dash.setMatrixAt(c, m4);
      c += 1;
    }
    dash.count = c;
    dash.receiveShadow = true;
    this.scene.add(dash);
    // Roadside posts (white with a black band and a reflector).
    const posts = new T3.Group();
    const pw = mat('#EEF1F4', { rough: 0.5 });
    const pb = mat('#1B2230', { rough: 0.5 });
    const pr = mat('#FF7A1A', { rough: 0.3, emissive: '#FF7A1A', emissiveIntensity: 0.25 });
    const postSp = L / Math.max(1, Math.round(L / 400));
    for (let i = Math.floor(x0 / postSp); i * postSp < x1; i += 1) {
      const x = i * postSp - 200;
      [this.z0 - 10].forEach((z) => {
        const k = 1;
        const p = new T3.Group();
        const body = mesh(geo('post', () => new T3.BoxGeometry(3.4, 46, 4)), pw);
        body.position.y = 23;
        const band = mesh(geo('post-b', () => new T3.BoxGeometry(3.6, 10, 4.2)), pb);
        band.position.y = 38;
        const refl = mesh(geo('post-r', () => new T3.BoxGeometry(3.7, 4, 1)), pr, false);
        refl.position.set(0, 38, k ? 2.2 : -2.2);
        p.add(body);
        p.add(band);
        p.add(refl);
        p.position.set(x + (k ? 200 : 0), this.heightAt(x + (k ? 200 : 0), z), z);
        posts.add(p);
      });
    }
    this.scene.add(posts);
    this.marks = [edges[0], dash];
    this.marksAll = { edges, dash, posts };
  }

  /** Colours for grass, path, sand and snow. */
  _paintGround() {
    const L = this.L;
    const snowy = this.snowy || 0;
    const wet = this.wet || 0;
    // In the cold the meadow loses its fresh green: olive, straw coloured.
    const dry = (this.fall || 0) * 0.7;
    const grass = new T3.Color('#4E8A3E').lerp(new T3.Color('#968E5A'), dry);
    const grassDark = new T3.Color('#356B32').lerp(new T3.Color('#6E6844'), dry);
    const sand = new T3.Color('#E2C48E');
    const wetSand = new T3.Color('#B39466');
    const snow = new T3.Color('#EEF3F8');
    const c = new T3.Color();
    const p = this.groundGeo.attributes.position;
    const col = this.groundGeo.attributes.color;
    for (let i = 0; i < p.count; i += 1) {
      const x = p.getX(i);
      const y = p.getY(i);
      const z = p.getZ(i);
      const b = this.route.beach(wrap(x, 0, L));
      // Noise per grid column, repeating with the route.
      const n = hash1((Math.round(x / this.gStep) % this.gCols) * 31 + Math.floor(z));
      c.copy(grass).lerp(grassDark, 0.25 + n * 0.35 + clamp(-z / 1400, 0, 0.3));
      if (z > this.z0 - 4 && z < this.z1 + 4) c.lerp(grassDark, 0.35);
      const sandK = b * clamp((-z - 30) / 20, 0, 1) + clamp((SEA_Y + 6 - y) / 8, 0, 1) * 0.9;
      if (sandK > 0) c.lerp(y < SEA_Y + 2 ? wetSand : sand, clamp(sandK, 0, 1));
      if (wet > 0) c.multiplyScalar(1 - wet * 0.25);
      if (snowy > 0) c.lerp(snow, snowy * (0.85 + n * 0.15));
      col.setXYZ(i, c.r, c.g, c.b);
    }
    col.needsUpdate = true;
    this.groundPieces.forEach((pg) => { pg.attributes.color.needsUpdate = true; });
    const road = this.style === 'road';
    const pathC = new T3.Color(road ? '#5A606A' : '#A88E6E');
    const pathEdge = new T3.Color(road ? '#4E545D' : '#7F6A52');
    const pp = this.pathGeo.attributes.position;
    const pcol = this.pathGeo.attributes.color;
    for (let i = 0; i < pp.count; i += 1) {
      const x = pp.getX(i);
      const z = pp.getZ(i);
      const edge = z < this.z0 + 3 || z > this.z1 - 3;
      const b = this.route.beach(wrap(x, 0, L));
      c.copy(edge ? pathEdge : pathC).lerp(sand, b);
      const pc6 = this.pCols;
      c.offsetHSL(0, 0, (hash1((((Math.round(x / this.pStep) % pc6) + pc6) % pc6) * 7 + Math.floor(z)) - 0.5) * 0.04);
      if (wet > 0) c.multiplyScalar(1 - wet * 0.35);
      if (snowy > 0) c.lerp(snow, snowy * 0.9);
      pcol.setXYZ(i, c.r, c.g, c.b);
    }
    pcol.needsUpdate = true;
    this.path.material.roughness = (road ? 0.75 : 0.9) - wet * 0.5;
    if (this.marks) this.marks.forEach((m) => { m.material.color.set(snowy ? '#C9D3DD' : '#F2F4F6'); });
  }

  _sea() {
    const g = new T3.PlaneGeometry(7000, 3440, 70, 34);
    g.rotateX(-Math.PI / 2);
    this.seaBase = g.attributes.position.array.slice();
    this.seaGeo = g;
    this.seaMat = new T3.MeshStandardMaterial({ color: '#2F6EA6', roughness: 0.28, metalness: 0.15, flatShading: false });
    this.seaMesh = new T3.Mesh(g, this.seaMat);
    this.seaMesh.receiveShadow = true;
    this.scene.add(this.seaMesh);
    // Foam along the beach.
    this.foamMat = new T3.MeshBasicMaterial({ color: '#F4FAFF', transparent: true, opacity: 0.7, depthWrite: false });
    const fg = new T3.PlaneGeometry(1, 1, 60, 1);
    fg.rotateX(-Math.PI / 2);
    this.foam = new T3.Mesh(fg, this.foamMat);
    this.foam.visible = false;
    this.scene.add(this.foam);
  }

  /**
   * Instanced meshes cut into pieces about `width` long in x: pieces out of
   * view are not drawn. items: [{ x, m, c }] with matrix and optional colour;
   * each item gets .mesh and .k (its instance) for later changes. copies:
   * every piece is also shown that many rounds of the route to each side,
   * sharing its data. Returns the pieces (the originals; copies are in
   * piece.userData.copies).
   */
  _pieces(g, material, items, width, copies = 0, o = {}) {
    const groups = new Map();
    items.forEach((it) => {
      const key = Math.floor(it.x / width);
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(it);
    });
    const out = [];
    groups.forEach((list) => {
      const im = new T3.InstancedMesh(g, material, list.length);
      list.forEach((it, k) => {
        im.setMatrixAt(k, it.m);
        if (it.c) im.setColorAt(k, it.c);
        it.mesh = im;
        it.k = k;
      });
      im.castShadow = !!o.cast;
      im.receiveShadow = !!o.receive;
      im.computeBoundingSphere();
      im.boundingSphere.radius += o.pad || 0;
      this.scene.add(im);
      im.userData.copies = [];
      for (let r = -copies; r <= copies; r += 1) {
        if (!r) continue;
        const c = new T3.InstancedMesh(g, material, list.length);
        c.instanceMatrix = im.instanceMatrix;
        c.instanceColor = im.instanceColor;
        c.castShadow = im.castShadow;
        c.receiveShadow = im.receiveShadow;
        c.boundingSphere = im.boundingSphere.clone();
        c.position.x = r * this.L;
        this.scene.add(c);
        im.userData.copies.push(c);
      }
      out.push(im);
    });
    return out;
  }

  /**
   * Trees behind the path; their crowns sway with the wind. Built for one
   * round of the route and shown again one round to each side, like the
   * land, in pieces that are only drawn when in view.
   */
  _trees() {
    const L = this.L;
    const list = [];
    const n = Math.round(L / 58);
    for (let i = 0; i < n; i += 1) {
      const x = (i + hash1(i * 13) * 0.8) * (L / n);
      const z = -150 - Math.pow(hash1(i * 17 + 2), 1.3) * 650;
      const s = 0.6 + hash1(i * 5 + 1) * 0.45;
      if (this.route.beach(x) > 0.05) continue;
      if (this.route.clear && this.route.clear(x, z)) continue;
      list.push({ id: i, x, z, s, y: this.heightAt(x, z) - 2, ph: hash1(i * 3) * 6.28, kind: hash1(i * 29) < 0.3 ? 1 : 0 });
    }
    this.treeList = list;
    const K = Math.ceil(2600 / L);
    const W = 700;
    const q0 = new T3.Quaternion();
    const trunks = list.map((t) => ({ x: t.x, m: new T3.Matrix4().compose(V3(t.x, t.y, t.z), q0, V3(t.s, t.s * (t.kind ? 1.3 : 1), t.s)) }));
    this._pieces(geo('trunk', () => {
      const g = new T3.CylinderGeometry(3.2, 4.8, 70, 8);
      g.translate(0, 35, 0);
      return g;
    }), mat('#5A4232', { rough: 0.95 }), trunks, W, K, { cast: true });
    // Crowns: four soft balls per tree. Colour by the tree itself, so its
    // copy one round away looks the same.
    this.crownParts = [];
    list.forEach((t) => {
      const parts = t.kind
        ? [[0, 108, 0, 30, 46, 30], [0, 140, 0, 22, 34, 22], [0, 82, 0, 33, 26, 33], [0, 166, 0, 12, 20, 12]]
        : [[0, 92, 0, 42, 36, 40], [-24, 76, 8, 28, 24, 26], [24, 80, -6, 30, 26, 28], [4, 118, 2, 28, 24, 26]];
      parts.forEach((p, j) => {
        const c = new T3.Color(t.kind ? '#2E6B3A' : '#3F7F3A').offsetHSL((hash1(t.id * 7 + j) - 0.5) * 0.04, 0, (hash1(t.id * 3 + j) - 0.5) * 0.12 + (j === 3 ? 0.06 : 0));
        const m = new T3.Matrix4().compose(V3(t.x + p[0] * t.s, t.y + p[1] * t.s, t.z + p[2] * t.s), q0, V3(p[3] * t.s, p[4] * t.s, p[5] * t.s));
        this.crownParts.push({ x: t.x, tree: t, p, y: t.y, j, base: c, m, c });
      });
    });
    this.crownMeshes = this._pieces(geo('crown', () => new T3.SphereGeometry(1, 13, 9)), new T3.MeshStandardMaterial({ roughness: 0.9, metalness: 0 }), this.crownParts, W, K, { cast: true, receive: true, pad: 30 });
    // Bare branches of the leaf trees, seen when the leaves fall in the cold.
    this.bareTrees = list.filter((t) => !t.kind).map((t) => {
      const ry = hash1(t.id * 41) * 6.28;
      const m = new T3.Matrix4().compose(V3(t.x, t.y, t.z), new T3.Quaternion().setFromAxisAngle(UP, ry), V3(t.s, t.s, t.s));
      return { x: t.x, tree: t, y: t.y, ry, m };
    });
    this.branchMeshes = this._pieces(bareCrownGeo(), new T3.MeshStandardMaterial({ color: '#5B4636', roughness: 0.95, metalness: 0 }), this.bareTrees, W, K, { cast: true, receive: true, pad: 30 });
    this.branchesOn = false;
    this.branchMeshes.forEach((m) => [m, ...m.userData.copies].forEach((c) => { c.visible = false; }));
    this._crowns(0, 0);
    this._tintCrowns();
  }

  _crowns(t, wind) {
    const m4 = new T3.Matrix4();
    const q = new T3.Quaternion();
    const e = new T3.Euler();
    const lean = -wind * 0.0035;
    this.crownParts.forEach((c) => {
      const tr = c.tree;
      const sway = Math.sin(t * (1.3 + wind * 0.03) + tr.ph) * (0.012 + wind * 0.0016);
      const a = lean + sway;
      const s = tr.s;
      const px = c.p[0] * s;
      const py = c.p[1] * s;
      // Rotate the crown part around the trunk base (bending tree).
      const x = tr.x + px * Math.cos(a) - py * Math.sin(a);
      const y = c.y + px * Math.sin(a) + py * Math.cos(a);
      e.set(0, 0, a);
      q.setFromEuler(e);
      // Leaf trees lose their leaves in the cold (leaf 1 = full, 0 = bare).
      const lk = tr.kind ? 1 : this.leaf ?? 1;
      m4.compose(V3(x, y, tr.z + c.p[2] * s), q, V3(c.p[3] * s * lk, c.p[4] * s * lk, c.p[5] * s * lk));
      c.mesh.setMatrixAt(c.k, m4);
    });
    this.crownMeshes.forEach((m) => { m.instanceMatrix.needsUpdate = true; });
    if (this.branchesOn) {
      const qy = new T3.Quaternion();
      this.bareTrees.forEach((b) => {
        const tr = b.tree;
        const a = lean + Math.sin(t * (1.3 + wind * 0.03) + tr.ph) * (0.012 + wind * 0.0016);
        e.set(0, 0, a);
        q.setFromEuler(e);
        qy.setFromAxisAngle(UP, b.ry);
        m4.compose(V3(tr.x, b.y, tr.z), q.multiply(qy), V3(tr.s, tr.s, tr.s));
        b.mesh.setMatrixAt(b.k, m4);
      });
      this.branchMeshes.forEach((m) => { m.instanceMatrix.needsUpdate = true; });
    }
  }

  _tintCrowns() {
    const snowy = this.snowy || 0;
    const fall = this.fall || 0;
    const white = new T3.Color('#F2F6FA');
    const autumn = ['#D9B23C', '#E0902F', '#C9642B', '#B8862F'].map((v) => new T3.Color(v));
    const brown = new T3.Color('#7D5A3A');
    const c = new T3.Color();
    this.crownParts.forEach((p) => {
      c.copy(p.base);
      // Leaf trees turn yellow, orange and rust in the cold, then brown.
      if (!p.tree.kind && fall > 0) {
        c.lerp(autumn[Math.floor(hash1(p.tree.id * 11 + p.j) * autumn.length)], clamp(fall * 1.6, 0, 1));
        if (fall > 0.6) c.lerp(brown, ((fall - 0.6) / 0.4) * 0.55);
      }
      if (snowy > 0) c.lerp(white, snowy * (p.j === 3 ? 0.85 : 0.45));
      p.mesh.setColorAt(p.k, c);
    });
    this.crownMeshes.forEach((m) => { if (m.instanceColor) m.instanceColor.needsUpdate = true; });
  }

  /** Grass, bushes, flowers and blowing leaves for the season and snow. */
  _tintDetails() {
    const snowy = this.snowy || 0;
    const fall = this.fall || 0;
    const straw = new T3.Color('#B3A464');
    const brown = new T3.Color('#77593F');
    const frost = new T3.Color('#E9EEF2');
    const c = new T3.Color();
    this.tuftItems.forEach((it) => {
      c.copy(it.base).lerp(straw, fall * 0.8);
      if (snowy) c.lerp(frost, 0.3);
      it.mesh.setColorAt(it.k, c);
    });
    this.bushItems.forEach((it) => {
      c.copy(it.base).lerp(brown, fall * 0.85);
      if (snowy) c.lerp(frost, 0.5);
      it.mesh.setColorAt(it.k, c);
    });
    [...this.tufts, ...this.bushes].forEach((m) => { if (m.instanceColor) m.instanceColor.needsUpdate = true; });
    const bloom = !snowy && fall < 0.35;
    this.flowers.forEach((m) => { m.visible = bloom; });
    const dead = ['#B07A35', '#8A6440'];
    this.leaves.forEach((l, i) => {
      if (l.m.userData.green) l.m.material.color.set(fall > 0.4 ? dead[i % 2] : ['#9BB34A', '#6F9A3A'][(i >> 1) % 2]);
    });
  }

  /** Grass tufts, flowers and bushes near the path (in pieces, see _pieces). */
  _details() {
    const L = this.L;
    const n = Math.round(L / 5);
    const tuftGeo = geo('tuft', () => {
      // A small clump of three soft blades.
      const parts = [];
      [[-0.9, 0.25], [0.8, -0.2], [0, 0.4]].forEach(([dx, tilt], i) => {
        const b = new T3.ConeGeometry(0.75, 4.6 + i * 0.8, 4);
        b.translate(0, 2.3 + i * 0.4, 0);
        b.rotateZ(tilt);
        b.translate(dx, 0, (i - 1) * 0.6);
        parts.push(b);
      });
      const g = new T3.BufferGeometry();
      const pos = [];
      const nor = [];
      parts.forEach((b) => {
        const nb = b.toNonIndexed();
        pos.push(...nb.attributes.position.array);
        nb.computeVertexNormals();
        nor.push(...nb.attributes.normal.array);
      });
      g.setAttribute('position', new T3.Float32BufferAttribute(pos, 3));
      g.setAttribute('normal', new T3.Float32BufferAttribute(nor, 3));
      return g;
    });
    const q = new T3.Quaternion();
    const colors = ['#F6F1E4', '#FFD84A', '#FF8FB1', '#B79CFF'];
    const tufts = [];
    const flowers = [];
    const bushes = [];
    for (let rep = -1; rep <= 1; rep += 1) {
      for (let i = 0; i < n; i += 1) {
        const x = i * 5 + (hash1(i * 3) - 0.5) * 5 + rep * L;
        if (x < -1200 || x > L + 800) continue;
        const front = hash1(i * 7 + 1) < 0.5;
        const z = front ? this.z1 + 2 + Math.pow(hash1(i * 11), 2) * 120 : this.z0 - 2 - Math.pow(hash1(i * 13), 2) * 140;
        const b = this.route.beach(wrap(x, 0, L));
        if (b > 0.3 && !front) continue;
        if (this.route.clear && this.route.clear(wrap(x, 0, L), z)) continue;
        const y = this.heightAt(x, z);
        if (y < SEA_Y + 3) continue;
        q.setFromAxisAngle(UP, hash1(i) * 6);
        const s = 0.7 + hash1(i * 5) * 0.8;
        const tc = new T3.Color('#6AA84F').offsetHSL((hash1(i * 17) - 0.5) * 0.05, 0, (hash1(i * 19) - 0.5) * 0.12);
        tufts.push({ x, m: new T3.Matrix4().compose(V3(x, y - 0.5, z), q, V3(s, s * (0.8 + hash1(i * 9) * 0.6), s)), c: tc, base: tc });
        if (i % 3 === 0 && b < 0.3) {
          const fz = z + (hash1(i * 23) - 0.5) * 8;
          flowers.push({ x, m: new T3.Matrix4().compose(V3(x + 2, this.heightAt(x + 2, fz) + 2.5, fz), q, V3(1.2, 1.2, 1.2)), c: new T3.Color(colors[Math.floor(hash1(i * 29) * colors.length)]) });
        }
        if (i % 12 === 0 && front && b < 0.2) {
          const bz = this.z1 + 60 + hash1(i * 31) * 80;
          const bs = 9 + hash1(i * 37) * 9;
          const bc = new T3.Color('#3D7536').offsetHSL(0, 0, (hash1(i * 41) - 0.5) * 0.1);
          bushes.push({ x, m: new T3.Matrix4().compose(V3(x, this.heightAt(x, bz) + bs * 0.4, bz), q, V3(bs * 1.3, bs, bs)), c: bc, base: bc });
        }
      }
    }
    this.tuftItems = tufts;
    this.bushItems = bushes;
    this.tufts = this._pieces(tuftGeo, new T3.MeshStandardMaterial({ color: '#FFFFFF', roughness: 0.9 }), tufts, 400, 0, { receive: true, pad: 8 });
    this.flowers = this._pieces(geo('flower', () => new T3.IcosahedronGeometry(1, 0)), new T3.MeshStandardMaterial({ roughness: 0.7 }), flowers, 400, 0, { receive: true, pad: 4 });
    this.bushes = this._pieces(geo('crown', () => new T3.SphereGeometry(1, 13, 9)), new T3.MeshStandardMaterial({ roughness: 0.9 }), bushes, 600, 0, { cast: true, receive: true, pad: 20 });
  }

  _mountains() {
    const g = new T3.Group();
    const m = mat('#6F8FAE', { rough: 1 });
    this.mountainMat = m;
    // A ring of 20 that repeats every MOUNT_P around the camera (see step).
    for (let i = 0; i < 20; i += 1) {
      const blobM = mesh(new T3.SphereGeometry(1, 20, 12), m, false);
      blobM.scale.set(500 + hash1(i * 3) * 600, 260 + hash1(i * 5) * 420, 300);
      blobM.position.set((i - 7) * 620 + hash1(i) * 200, SEA_Y - 60, -3600 - hash1(i * 7) * 600);
      blobM.userData.mx = blobM.position.x;
      g.add(blobM);
    }
    this.mountains = g;
    this.scene.add(g);
  }

  _clouds() {
    this.clouds = [];
    this.cloudMat = new T3.MeshStandardMaterial({ color: '#FFFFFF', roughness: 1, metalness: 0, emissive: '#FFFFFF', emissiveIntensity: 0.25, transparent: true, opacity: 1, depthWrite: false, fog: false });
    for (let i = 0; i < 12; i += 1) {
      const c = new T3.Group();
      const parts = 4 + Math.floor(hash1(i * 3) * 3);
      for (let j = 0; j < parts; j += 1) {
        const b = new T3.Mesh(lowSphereGeo(), this.cloudMat);
        const r = 60 + hash1(i * 7 + j) * 70;
        b.scale.set(r * 1.25, r * 0.8, r);
        b.position.set((j - parts / 2) * 75 + hash1(j + i) * 30, (hash1(i + j * 5) - 0.3) * 40, hash1(j * 3 + i) * 50);
        c.add(b);
      }
      c.userData = { x: (i - 6) * 520 + hash1(i * 9) * 200, y: 520 + hash1(i * 11) * 420, z: -2400 - hash1(i * 13) * 900, s: 0.8 + hash1(i * 17) * 0.6 };
      this.clouds.push(c);
      this.scene.add(c);
    }
  }

  _sunSprite() {
    const glow = canvasTex(256, 256, (g, w, h) => {
      const r = g.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
      r.addColorStop(0, 'rgba(255,248,220,1)');
      r.addColorStop(0.16, 'rgba(255,236,170,1)');
      r.addColorStop(0.22, 'rgba(255,214,120,0.55)');
      r.addColorStop(0.55, 'rgba(255,200,110,0.15)');
      r.addColorStop(1, 'rgba(255,200,110,0)');
      g.fillStyle = r;
      g.fillRect(0, 0, w, h);
    });
    const rays = canvasTex(256, 256, (g, w, h) => {
      g.translate(w / 2, h / 2);
      for (let i = 0; i < 12; i += 1) {
        g.rotate(Math.PI / 6);
        const lg = g.createLinearGradient(0, 30, 0, 120);
        lg.addColorStop(0, 'rgba(255,220,140,0.55)');
        lg.addColorStop(1, 'rgba(255,220,140,0)');
        g.fillStyle = lg;
        g.beginPath();
        g.moveTo(-7, 34);
        g.lineTo(7, 34);
        g.lineTo(2, 120);
        g.lineTo(-2, 120);
        g.closePath();
        g.fill();
      }
    });
    this.sunGlow = new T3.Sprite(new T3.SpriteMaterial({ map: glow, transparent: true, depthWrite: false, fog: false }));
    this.sunRays = new T3.Sprite(new T3.SpriteMaterial({ map: rays, transparent: true, depthWrite: false, fog: false, blending: T3.AdditiveBlending }));
    this.scene.add(this.sunGlow);
    this.scene.add(this.sunRays);
  }

  _precip() {
    const N = 900;
    this.rainN = N;
    const rp = new Float32Array(N * 6);
    const rg = new T3.BufferGeometry();
    rg.setAttribute('position', new T3.BufferAttribute(rp, 3));
    this.rain = new T3.LineSegments(rg, new T3.LineBasicMaterial({ color: '#A9CCF2', transparent: true, opacity: 0.55, depthWrite: false }));
    this.rain.frustumCulled = false;
    this.scene.add(this.rain);
    const sp = new Float32Array(N * 3);
    const sg = new T3.BufferGeometry();
    sg.setAttribute('position', new T3.BufferAttribute(sp, 3));
    this.snow = new T3.Points(sg, new T3.PointsMaterial({ color: '#FFFFFF', size: 3.4, map: dotTex(), transparent: true, depthWrite: false, opacity: 0.95 }));
    this.snow.frustumCulled = false;
    this.scene.add(this.snow);
    this.drops = Array.from({ length: N }, (_, i) => ({ x: rnd(-400, 400), y: rnd(-20, 460), z: rnd(-320, 230), ph: rnd(0, 6), s: rnd(0.7, 1.3), i }));
  }

  _puffs() {
    // Breath clouds and other small soft puffs.
    this.puffs = Array.from({ length: 24 }, () => {
      const s = new T3.Sprite(new T3.SpriteMaterial({ map: dotTex(), color: '#EAF4FF', transparent: true, opacity: 0, depthWrite: false }));
      s.visible = false;
      this.scene.add(s);
      return { s, age: 1, v: V3(), p: V3(), size: 1 };
    });
  }

  /** A breath cloud (or similar puff) from a world position. */
  puff(at, vel, size = 1, life = 1.8, opacity = 0.55, color = '#EAF4FF') {
    const p = this.puffs.find((q) => q.age >= 1);
    if (!p) return;
    p.age = 0;
    p.p.copy(at);
    p.v.copy(vel);
    p.size = size;
    p.life = life;
    p.op = opacity;
    p.s.material.color.set(color);
    p.s.visible = true;
  }

  _leaves() {
    const g = geo('leaf', () => {
      const s = new T3.Shape();
      s.moveTo(0, -2.4);
      s.quadraticCurveTo(2.2, 0, 0, 2.4);
      s.quadraticCurveTo(-2.2, 0, 0, -2.4);
      return new T3.ShapeGeometry(s);
    });
    this.leaves = Array.from({ length: 26 }, (_, i) => {
      const m = new T3.Mesh(g, mat(['#C98A2E', '#9BB34A', '#D9692E', '#6F9A3A'][i % 4], { side: T3.DoubleSide, unique: true }));
      m.userData.green = i % 2 === 1;
      m.visible = false;
      this.scene.add(m);
      return { m, x: rnd(-400, 400), y: rnd(10, 160), z: rnd(-200, 160), r: V3(rnd(0, 6), rnd(0, 6), rnd(0, 6)), s: rnd(0.8, 1.4) };
    });
  }

  /* ------------------------------ weather ------------------------------ */

  setLook(look, mood) {
    this.look = look;
    this.mood = mood || {};
    const L = {
      ...look,
      cold: Math.max(look.cold, (this.mood.cold || 0) * 0.75),
      hot: Math.max(look.hot, this.mood.hot || 0),
    };
    this.L2 = L;
    const cl = clamp(L.cloud, 0, 1);
    const C = (a) => new T3.Color(a);
    // Sky: deep blue, grey with clouds, warm when hot, pale when cold.
    const top = C('#2C6FB8').lerp(C('#4A5462'), cl).lerp(C('#4F82B8'), L.hot * 0.25 * (1 - cl)).lerp(C('#6E95BF'), L.cold * 0.3 * (1 - cl));
    const bot = C('#A9D3F2').lerp(C('#8994A2'), cl).lerp(C('#F4C88E'), L.hot * 0.55 * (1 - cl)).lerp(C('#DCEBF7'), L.cold * 0.45);
    this.skyTop = top;
    this.skyBot = bot;
    if (!this.skyTex) {
      this.skyCanvas = document.createElement('canvas');
      this.skyCanvas.width = 4;
      this.skyCanvas.height = 256;
      this.skyTex = new T3.CanvasTexture(this.skyCanvas);
      this.skyTex.colorSpace = T3.SRGBColorSpace;
      this.scene.background = this.skyTex;
    }
    const g = this.skyCanvas.getContext('2d');
    const lg = g.createLinearGradient(0, 0, 0, 256);
    lg.addColorStop(0, `#${top.getHexString()}`);
    lg.addColorStop(0.62, `#${bot.getHexString()}`);
    lg.addColorStop(1, `#${bot.clone().lerp(C('#FFFFFF'), 0.15).getHexString()}`);
    g.fillStyle = lg;
    g.fillRect(0, 0, 4, 256);
    this.skyTex.needsUpdate = true;
    this.scene.fog.color.copy(bot);
    this.scene.fog.near = lerp(900, 420, clamp(L.rain + cl * 0.4, 0, 1));
    this.scene.fog.far = lerp(5200, 2600, clamp(L.rain + cl * 0.3, 0, 1));
    this.mountainMat.color.copy(bot).lerp(C('#3B5878'), 0.45);

    // Light: bright sun on a clear day, soft and grey under clouds.
    const sunK = clamp(1 - cl * 1.05, 0, 1);
    this.sun.intensity = lerp(0.55, 2.5, sunK) * (1 + L.hot * 0.15);
    this.sun.color.set('#FFF4E0').lerp(C('#FFD9A0'), L.hot * 0.6).lerp(C('#E2EEFF'), L.cold * 0.5);
    this.hemi.intensity = lerp(1.35, 1.0, sunK);
    this.hemi.color.copy(top).lerp(C('#FFFFFF'), 0.45);
    this.sunGlow.material.opacity = sunK;
    this.sunRays.material.opacity = sunK * (0.55 + L.hot * 0.45);
    this.sunGlow.visible = sunK > 0.02;
    this.sunRays.visible = sunK > 0.02;

    // Clouds: more and darker with rain.
    const visible = 3 + Math.round(cl * 9);
    this.cloudMat.color.set('#FFFFFF').lerp(C('#6F7988'), clamp(cl * 0.8 + L.rain * 0.6, 0, 1));
    this.cloudMat.emissive.copy(this.cloudMat.color);
    this.cloudMat.opacity = 0.75 + cl * 0.25;
    this.clouds.forEach((c, i) => { c.visible = i < visible; });

    // Sea: blue, greyer under clouds and rain.
    this.seaMat.color.set('#2C78B8').lerp(C('#56718C'), cl * 0.45).lerp(C('#46596C'), L.rain * 0.45).lerp(C('#6A9CC4'), L.cold * 0.25);

    const snowy = L.snow && (L.rain > 0 || L.cold > 0.6) ? 1 : 0;
    const wet = !L.snow ? clamp(L.rain * 1.4, 0, 1) : 0;
    // Season from the temperature of the day (not from the activity):
    // below about 6 degrees the leaves turn, from about 3 degrees they fall,
    // around freezing the leaf trees are bare. Firs stay green.
    const wc = clamp(look.cold || 0, 0, 1);
    const fall = Math.round(clamp(wc / 0.45, 0, 1) * 20) / 20;
    const leaf = Math.round((1 - clamp((wc - 0.3) / 0.35, 0, 1)) * 20) / 20;
    if (snowy !== this.snowy || wet !== this.wet || fall !== this.fall || leaf !== this.leaf) {
      this.snowy = snowy;
      this.wet = wet;
      this.fall = fall;
      this.leaf = leaf;
      this._paintGround();
      this._tintCrowns();
      this._tintDetails();
      this.branchesOn = leaf < 0.97;
      this.branchMeshes.forEach((m) => [m, ...m.userData.copies].forEach((c) => { c.visible = this.branchesOn; }));
      this._crowns(this.t, clamp(L.wind || 0, 0, 80));
    }
    this.activeDrops = Math.round(L.rain * this.rainN);
    this.rain.visible = !L.snow && this.activeDrops > 0;
    this.snow.visible = !!L.snow && this.activeDrops > 0;
    this.renderer.toneMappingExposure = lerp(1.08, 0.92, clamp(L.rain + cl * 0.3, 0, 1));
  }

  /* ------------------------------ frame ------------------------------ */

  /**
   * Camera for this frame. f describes what has to be in the picture:
   *   x, z    the figures: they stay in the middle of the picture,
   *   y       the height to look at,
   *   lz      the depth to look at (default z),
   *   lo, hi  world x range that must be visible (default just x).
   * camOff is the camera position seen from the point it looks at.
   * Sideways the camera follows the figures exactly, so they never drift
   * off centre at speed, whatever the width of the card. Only the framing
   * eases: a pan when lo..hi does not fit around the figures, and a zoom
   * out when it does not fit at all (narrow cards).
   */
  _camera(dt, f, camOff) {
    const len = this.L;
    const init = !this.camPos;
    if (!init && this.lastX !== undefined) {
      const jump = Math.round((f.x - this.lastX) / len) * len;
      if (jump) this._shift(jump);
    }
    this.lastX = f.x;
    // Picture right on the ground (the camera's x axis).
    const back = camOff.clone().normalize();
    const rn = Math.hypot(back.x, back.z) || 1;
    const rx = back.z / rn;
    const rz = -back.x / rn;
    // Half the visible width at the distance of the point looked at.
    const hw = camOff.length() * Math.tan((this.camera.fov * Math.PI) / 360) * this.camera.aspect;
    const m = Math.min(14, hw * 0.12);
    const a = Math.min(0, ((f.lo ?? f.x) - f.x) * rx);
    const b = Math.max(0, ((f.hi ?? f.x) - f.x) * rx);
    // Zoom out as little as possible: enough for lo..hi, and so that the
    // figures never move further than 40 % of half the width off centre.
    const cap = 1.4;
    const zoomT = Math.max(1, ((b - a) / 2 + m) / hw, (m - a) / (cap * hw), (b + m) / (cap * hw));
    const hz = hw * zoomT;
    const p0 = b - hz + m;
    const p1 = a + hz - m;
    const panT = p0 > p1 ? (a + b) / 2 : clamp(0, p0, p1);
    const lzT = f.lz ?? f.z;
    if (init) {
      this.pan = panT;
      this.zoom = zoomT;
      this.lookY = f.y;
      this.lookZ = lzT;
    } else {
      const k = (rate) => 1 - Math.exp(-dt * rate);
      this.pan += (panT - this.pan) * k(6);
      this.zoom += (zoomT - this.zoom) * k(zoomT > this.zoom ? 6 : 1.5);
      this.lookY += (f.y - this.lookY) * k(3.2);
      this.lookZ += (lzT - this.lookZ) * k(3.2);
    }
    // The figures (at their own depth) sit at -pan from the middle.
    const lookX = f.x + ((f.z - this.lookZ) * rz + this.pan) / rx;
    this.camLook = V3(lookX, this.lookY, this.lookZ);
    this.camPos = this.camLook.clone().addScaledVector(camOff, this.zoom);
    this.camera.position.copy(this.camPos);
    this.camera.lookAt(this.camLook);
  }

  /** The route started a new round: move what is kept in world positions. */
  _shift(dx) {
    this.xOff -= dx;
    this.puffs.forEach((p) => { p.p.x += dx; });
    this.onWrap.forEach((fn) => fn(dx));
  }

  /** One frame. f: what the camera has to show (see _camera). dt in seconds. */
  step(dt, f, camOff) {
    this.t += dt;
    const t = this.t;
    const L = this.L2 || this.look;
    const wind = clamp(L.wind || 0, 0, 80);

    this._camera(dt, f, camOff);
    const cx = this.camLook.x;
    // The same without the jumps of a new round, for things far away.
    const cxc = cx + this.xOff;
    this.mountains.children.forEach((mt) => { mt.position.x = cx + wrap(mt.userData.mx - cxc, -MOUNT_P / 2, MOUNT_P / 2); });

    // Sun and its shadow box follow the action.
    this.sun.target.position.copy(this.camLook);
    this.sun.position.copy(this.camLook).add(V3(320, 620, 420));
    const sunDir = V3(0.42, 0.36, -0.83).normalize();
    const sunAt = this.camera.position.clone().addScaledVector(sunDir, 3200);
    this.sunGlow.position.copy(sunAt);
    this.sunRays.position.copy(sunAt);
    const pulse = 1 + (L.hot || 0) * 0.12 * Math.sin(t * 2.2);
    this.sunGlow.scale.setScalar((760 + (L.hot || 0) * 380) * pulse);
    this.sunRays.scale.setScalar((1500 + (L.hot || 0) * 500) * pulse);
    this.sunRays.material.rotation = t * 0.12;

    // Sea follows the camera in steps of its grid, waves in world space.
    const stepX = 100;
    const sx = Math.round(cxc / stepX) * stepX;
    this.seaMesh.position.set(sx - this.xOff, SEA_Y, -1780);
    const sp = this.seaGeo.attributes.position;
    const base = this.seaBase;
    const amp = 1.6 + wind * 0.08;
    for (let i = 0; i < sp.count; i += 1) {
      const x = base[i * 3] + sx;
      const z = base[i * 3 + 2] - 1780;
      sp.setY(i, Math.sin(x * 0.012 + t * 1.3) * amp * 0.6 + Math.sin(z * 0.02 - t * 1.7 + x * 0.004) * amp * 0.5);
    }
    sp.needsUpdate = true;
    this.seaGeo.computeVertexNormals();

    // Beach foam along the waterline.
    if (this.route.beachCenter !== undefined) {
      const bc = this.route.beachCenter;
      let near = null;
      [bc - this.L, bc, bc + this.L].forEach((b) => { if (Math.abs(b - cx) < 1500) near = b; });
      this.foam.visible = near !== null;
      if (near !== null) {
        const half = this.route.beachHalf - 80;
        const zLine = this.route.shoreZ;
        this.foam.position.set(near, SEA_Y + 1.1, zLine + Math.sin(t * 0.9) * 3);
        this.foam.scale.set(half * 2, 1, 7 + Math.sin(t * 1.3) * 2);
        this.foamMat.opacity = 0.55 + Math.sin(t * 1.6) * 0.15;
      }
    }

    // Trees.
    this._crowns(t, wind);

    // Clouds drift with the wind (from +x).
    this.clouds.forEach((c) => {
      const u = c.userData;
      u.x -= (4 + wind * 1.4) * dt;
      const rel = wrap(u.x - cxc, -3200, 3200);
      c.position.set(cx + rel, u.y + this.camLook.y, u.z + this.camLook.z);
      c.scale.setScalar(u.s);
    });

    // Rain or snow in a box around the camera target.
    const n = this.activeDrops || 0;
    if (n > 0) {
      const vx = -(wind * 4.5);
      const snow = !!L.snow;
      const vy = snow ? -48 : -620;
      const arr = snow ? this.snow.geometry.attributes.position : this.rain.geometry.attributes.position;
      const base0 = this.camLook;
      for (let i = 0; i < this.rainN; i += 1) {
        const d = this.drops[i];
        if (i >= n) {
          if (snow) arr.setXYZ(i, 0, -9999, 0);
          else { arr.setXYZ(i * 2, 0, -9999, 0); arr.setXYZ(i * 2 + 1, 0, -9999, 0); }
          continue;
        }
        d.y += vy * dt * d.s;
        d.x += (snow ? vx * 0.45 + Math.sin(t * 1.7 + d.ph) * 16 : vx) * dt;
        if (d.y < -30) { d.y = rnd(380, 470); d.x = rnd(-420, 420); d.z = rnd(-320, 230); }
        const x = base0.x + wrap(d.x, -420, 420);
        const y = base0.y - 60 + d.y;
        const z = d.z;
        if (snow) arr.setXYZ(i, x, y, z);
        else {
          const k = 0.022;
          arr.setXYZ(i * 2, x, y, z);
          arr.setXYZ(i * 2 + 1, x - vx * k, y - vy * k, z);
        }
      }
      arr.needsUpdate = true;
    }

    // Puffs.
    this.puffs.forEach((p) => {
      if (p.age >= 1) { p.s.visible = false; return; }
      p.age += dt / (p.life || 1.8);
      p.v.multiplyScalar(Math.exp(-dt * 2.2));
      p.p.addScaledVector(p.v, dt);
      p.p.x -= wind * 0.25 * dt;
      p.p.y += 5 * dt;
      p.s.position.copy(p.p);
      p.s.scale.setScalar((2 + p.age * 9) * p.size);
      const fade = p.age < 0.12 ? p.age / 0.12 : (1 - p.age) / 0.88;
      p.s.material.opacity = (p.op ?? 0.55) * fade;
    });

    // Leaves in strong wind.
    const windy = Math.max(this.mood.wind || 0, clamp((wind - 35) / 20, 0, 1));
    this.leaves.forEach((l) => {
      l.m.visible = windy > 0.05;
      if (!l.m.visible) return;
      l.x -= (140 + wind * 5) * l.s * dt;
      if (l.x < -420) { l.x = rnd(420, 700); l.y = rnd(10, 170); l.z = rnd(-220, 170); }
      l.r.x += 6 * dt * l.s;
      l.r.y += 4 * dt;
      l.m.position.set(cx + l.x, this.camLook.y - 60 + l.y + Math.sin(t * 3 + l.x * 0.02) * 12, l.z);
      l.m.rotation.set(l.r.x, l.r.y, l.r.z);
      l.m.scale.setScalar(l.s * 1.4);
    });
  }

  render() {
    this.renderer.render(this.scene, this.camera);
  }

  resize(w, h) {
    if (!w || !h) return;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }

  dispose() {
    this.scene.traverse((o) => {
      if (o.isMesh || o.isPoints || o.isLineSegments || o.isSprite) {
        if (o.geometry && !GEO_CACHE_HAS(o.geometry)) o.geometry.dispose();
      }
    });
    this.renderer.dispose();
    if (this.renderer.forceContextLoss) this.renderer.forceContextLoss();
  }
}

function GEO_CACHE_HAS(g) {
  for (const v of GEO_CACHE.values()) if (v === g) return true;
  return false;
}

/* ------------------------------------------------------------------ *
 *  Walking in 3D: a couple out for a walk, hand in hand, over gentle
 *  hills. About a minute and a half per round at full pace: he trips over
 *  a root, a dinosaur chases them (he runs off, she stops and tells it
 *  off until it shrinks and slinks away), they rest on a bench where he
 *  nods off, they take a selfie, and at a beach they sit down in the sand
 *  and watch the boats go by.
 *  When the weather says no, a little comedy plays instead:
 *    storm  his toupee flies away; the wind brings it back, slightly askew
 *    rain   he holds the umbrella over her and gets soaked, then steps
 *           back into a puddle
 *    cold   they huddle and shiver; his nose starts to glow red
 *    heat   he fans her so hard that her ice cream lands in his face
 * ------------------------------------------------------------------ */
const WK = {
  K: 1.32,          // route units per figure unit
  HK: 1.5,          // hills a little higher in 3D
  ZM: -8,           // path centre (where the couple walks)
  FX: 6,            // woman relative to the man: a little ahead ...
  FZ: -26,          // ... and beside him, on his left
  FS: 0.92,         // she is a bit smaller
  DS: 1.15,         // dinosaur size
  BENCH_Z: -62,     // bench seat centre
  BENCH_T0: 2.9,    // time to get to the bench
  BEACH_T0: 2.2,    // time to walk down to the water
  SELFIE_T0: 0.7,
};

class WalkScene3D {
  constructor(canvas) {
    this.speed = 64;
    this.PLAN = [
      { len: 320, v: 1 },
      { ev: 'trip', dur: 3.6 },
      { len: 400, v: 0.85, rise: 30 },
      { ev: 'dino', dur: 13.6 },
      { len: 400, v: 1.05, rise: -30 },
      { ev: 'bench', dur: WK.BENCH_T0 + 11.4 },
      { len: 320, v: 1 },
      { ev: 'selfie', dur: WK.SELFIE_T0 + 5.7 },
      { len: 640, v: 1 },
      { ev: 'beach', dur: WK.BEACH_T0 + 15.9 },
      { len: 640, v: 1 },
    ];
    this.GAG = { wind: 12.5, rain: 12, cold: 11, hot: 11 };
    this.DINO = {
      x: [[0, -330], [1.6, -150, 1], [2.6, -115, 1], [6.9, -82], [7.5, -68, 1], [8.3, -68], [9.6, -46, 1], [10.55, -46], [12.8, -380, 1]],
      size: [[0, 1], [8.4, 1], [9.6, 0.4, 1], [10.55, 0.4], [12.8, 0.45, 1]],
      man: [[0, 0], [3.1, 0], [6.9, 60], [7.95, 112, 1], [10.55, 112], [12.6, 0, 1], [14, 0]],
    };
    // Where the couple stands during an event: z of their midpoint and the
    // direction they face (degrees, 0 = along the path, 90 = towards the
    // back, -90 = towards the camera).
    const B = WK.BENCH_T0;
    const S = WK.BEACH_T0;
    this.STAGE = {
      bench: {
        z: [[0, WK.ZM], [0.9, WK.ZM], [2.1, -44, 1], [B, -59, 1], [B + 8.7, -59], [B + 10.3, WK.ZM, 1]],
        yaw: [[0, 0], [0.9, 90, 1], [2.1, 90], [B, -90, 1], [B + 10.3, -90], [B + 11.4, 0, 1]],
      },
      beach: {
        z: [[0, WK.ZM], [0.8, WK.ZM], [S, -88, 1], [S + 12.7, -88], [S + 13.5, -88], [S + 15.1, WK.ZM, 1]],
        yaw: [[0, 0], [0.8, 90, 1], [S + 12.7, 90], [S + 13.5, -90, 1], [S + 15.1, -90], [S + 15.9, 0, 1]],
      },
      selfie: {
        z: [[0, WK.ZM]],
        yaw: [[0, 0], [WK.SELFIE_T0, -70, 1], [WK.SELFIE_T0 + 5, -70], [WK.SELFIE_T0 + 5.7, 0, 1]],
      },
    };
    this._initPlan();

    // Route for the landscape (figure units).
    const K = WK.K;
    const L3 = this.L / K;
    const beachEv = this.events.find((e) => e.ev === 'beach');
    const bc = beachEv.at / K;
    const benchX = this.events.find((e) => e.ev === 'bench').at / K;
    this.route = {
      length: L3,
      height: (x) => (this.terrain(x * K) * WK.HK) / K,
      beach: (x) => clamp((430 - Math.abs(wrap(x - bc, -L3 / 2, L3 / 2))) / 90, 0, 1),
      beachCenter: bc,
      beachHalf: 430,
      shoreZ: -125,
      clear: (x, z) => Math.abs(wrap(x - benchX, -L3 / 2, L3 / 2)) < 70 && z > -110 && z < PATH_Z0 + 1,
    };
    this.world = new World3D(canvas, this.route);
    const W = this.world;

    // The couple. The frame turns around their midpoint.
    this.couple = new T3.Group();
    W.scene.add(this.couple);
    this.man = new Person3D({ kind: 'man', shirt: '#2A62B8', pants: '#3A4A66', shoes: '#5A3A22', hair: '#5E4E40', toupee: '#4A3426', brow: '#4A3426', sleeves: 'long' });
    this.woman = new Person3D({ kind: 'woman', shirt: '#FF7A1A', pants: SKIN3, legs: 'skin', skirt: '#1F8A5B', shoes: '#C0392B', hair: '#6B3A1E', brow: '#4A2A16', sleeves: 'short', scale: WK.FS });
    this.couple.add(this.man.root);
    this.couple.add(this.woman.root);
    this.manBase = V3(-WK.FX / 2, 0, -WK.FZ / 2);
    this.womanBase = V3(WK.FX / 2, 0, WK.FZ / 2);

    // Props in the world.
    const rootEv = this.events.find((e) => e.ev === 'trip');
    this.periodic(PROPS.root(), rootEv.at / K - WK.FX / 2 + 9, WK.ZM);
    this.periodic(PROPS.bench(), benchX, WK.BENCH_Z);

    // Props that move with the couple.
    this.umbrella = PROPS.umbrella();
    this.umbrella.visible = false;
    this.couple.add(this.umbrella);
    this.puddle = PROPS.puddle();
    this.puddle.visible = false;
    W.scene.add(this.puddle);
    this.ice = PROPS.iceCream();
    this.ice.visible = false;
    W.scene.add(this.ice);
    this.flyScoop = blob('#FF9BB3', 3.1, 2.8, 3.1, { rough: 0.55 });
    this.flyScoop.visible = false;
    W.scene.add(this.flyScoop);
    this.phone = PROPS.phone();
    this.phone.scale.setScalar(1.5);
    this.phone.visible = false;
    W.scene.add(this.phone);
    this.flyToupee = this.man.toupee.clone();
    this.flyToupee.visible = false;
    this.couple.add(this.flyToupee);
    // Cream on his face and the tongue that licks it off.
    this.cream = blob('#FF9BB3', 3.4, 3.0, 4.2, { rough: 0.55, shadow: false });
    this.cream.position.set(8.2, -1.2, 0);
    this.cream.visible = false;
    this.man.head.add(this.cream);
    this.tongue = mesh(capGeo(0.9, 2.2), mat('#E2577A'), false);
    this.tongue.position.set(8.6, -4.6, 0);
    this.tongue.visible = false;
    this.man.head.add(this.tongue);
    this.noseGlow = new T3.Sprite(new T3.SpriteMaterial({ map: dotTex(), color: '#FF3B30', transparent: true, opacity: 0, depthWrite: false, blending: T3.AdditiveBlending }));
    this.noseGlow.position.set(8.6, -0.6, 0);
    this.noseGlow.scale.setScalar(9);
    this.man.head.add(this.noseGlow);
    this.zzz = [0, 1, 2].map(() => {
      const s = textSprite('Z');
      s.visible = false;
      W.scene.add(s);
      return s;
    });
    // Flash of the selfie: a white sheet in front of the camera.
    this.flash = new T3.Mesh(new T3.PlaneGeometry(400, 400), new T3.MeshBasicMaterial({ color: '#FFFFFF', transparent: true, opacity: 0, depthTest: false, depthWrite: false }));
    this.flash.position.set(0, 0, -8);
    this.flash.renderOrder = 999;
    this.flash.visible = false;
    W.camera.add(this.flash);

    this.dino = new Dino3D();
    this.dino.root.visible = false;
    W.scene.add(this.dino.root);
    this.sail = PROPS.sailboat();
    this.motor = PROPS.motorboat();
    this.sail.visible = false;
    this.motor.visible = false;
    W.scene.add(this.sail);
    W.scene.add(this.motor);
    this.drops = new Drops3D(W.scene, 48);
    W.onWrap.push((dx) => this.drops.shift(dx));

    this.look = { cloud: 0.3, rain: 0, snow: false, wind: 6, hot: 0, cold: 0 };
    this.mood = {};
    this.pace = 0;
    this.paceTarget = 0;
    this.t = 0;
    this.cz = WK.ZM;
    this.cyaw = 0;
    this.localSpeed = 0;
  }

  /** Adds an object to the world at x (and its copies one round away). */
  periodic(obj, x, z) {
    const L3 = this.route.length;
    [-L3, 0, L3].forEach((o, i) => {
      const xx = x + o;
      if (xx < -900 || xx > L3 + 900) return;
      const m = i === 1 ? obj : obj.clone();
      m.position.set(xx, this.world.heightAt(xx, z), z);
      m.traverse((c) => { if (c.isMesh) { c.castShadow = true; c.receiveShadow = true; } });
      this.world.scene.add(m);
    });
  }

  /* ------------------------------ plan ------------------------------ */

  _initPlan() {
    let s = 0;
    let e = 0;
    this.segs = [];
    this.events = [];
    this.PLAN.forEach((g) => {
      if (g.ev) {
        const ev = { ...g, at: s };
        this.events.push(ev);
        if (g.ev === 'dino') {
          // The chase covers ground: it gets a flat stretch of its own.
          let len = 0;
          for (let x = 0; x < g.dur; x += 1 / 240) len += this._dinoSpeed(x) / 240;
          ev.travel = len;
          this.segs.push({ len, v: 1, s0: s, e0: e, s1: s + len });
          s += len;
        }
        return;
      }
      this.segs.push({ ...g, s0: s, e0: e, s1: s + g.len });
      s += g.len;
      e += g.rise || 0;
    });
    this.L = s;
    this.s = 0;
    this.vel = 0;
    this.ev = null;
    this.evT = 0;
    this.done = new Set();
    this.phM = 0;
    this.phF = 0.3;
    this.dPh = 0;
    this.gag = null;
    this.gagT = 0;
    this.wet = 0;
  }

  _seg(s) {
    const q = wrap(s, 0, this.L);
    return this.segs.find((g) => q >= g.s0 && q < g.s1) || this.segs[this.segs.length - 1];
  }

  terrain(s) {
    const q = wrap(s, 0, this.L);
    const g = this._seg(q);
    if (!g.rise) return g.e0;
    return g.e0 + g.rise * ease(clamp((q - g.s0) / g.len, 0, 1));
  }

  /** World speed during the chase: walk, stop, run, stop, walk on. */
  _dinoSpeed(et) {
    const V = this.speed * 0.85;
    const R = this.speed * 2.7;
    const k = (a, b) => ease(clamp((et - a) / (b - a), 0, 1));
    if (et < 0.9) return V;
    if (et < 1.6) return V * (1 - k(0.9, 1.6));
    if (et < 2.6) return 0;
    if (et < 3.1) return R * k(2.6, 3.1);
    if (et < 6.9) return R;
    if (et < 7.5) return R * (1 - k(6.9, 7.5));
    if (et < 12.9) return 0;
    return V * k(12.9, 13.6);
  }

  /** Speed for this frame; slows down into each stop. */
  plan(dt, pace) {
    if (this.ev) {
      const ev = this.ev;
      this.evT += dt;
      if (ev.ev === 'dino') {
        this.vel = this._dinoSpeed(this.evT);
        // Blend from the speed they came with, so nothing jerks.
        if (this.evT < 0.6 && ev.v0 !== undefined) this.vel = lerp(ev.v0, this.vel, ease(this.evT / 0.6));
        this.s = Math.min(ev.at + ev.travel, this.s + this.vel * dt);
      } else this.vel = 0;
      if (this.evT >= ev.dur || pace < 0.02) {
        this.done.add(ev.ev);
        this.ev = null;
      }
      return this.vel;
    }
    const g = this._seg(this.s);
    let vt = g.v * this.speed * pace;
    const next = this.events.find((x) => !this.done.has(x.ev) && x.at >= this.s - 0.5);
    if (next && pace > 0.02) {
      const dp = next.at - this.s;
      // Tripping and the dinosaur happen at full walking speed, the others brake gently.
      if (next.ev !== 'trip' && next.ev !== 'dino' && dp < 120) vt = Math.min(vt, Math.sqrt(2 * 40 * Math.max(0, dp)));
      if (next.ev === 'dino') {
        if (dp <= this.vel * dt) {
          const v = dp / Math.max(dt, 1e-3);
          this.s = next.at; this.ev = next; this.evT = 0; this.ev.v0 = this.vel;
          return v;
        }
      } else if (dp <= Math.max(this.vel * dt, next.ev === 'trip' ? 1.2 : 0.05)) {
        const v = dp / Math.max(dt, 1e-3);
        this.s = next.at; this.vel = 0; this.ev = next; this.evT = 0;
        return v;
      }
    }
    const acc = vt > this.vel ? 40 : 90;
    this.vel += clamp(vt - this.vel, -acc * dt, acc * dt);
    this.s += this.vel * dt;
    if (this.s >= this.L) { this.s -= this.L; this.done.clear(); }
    return this.vel;
  }

  /* ------------------------------ helpers ------------------------------ */

  _arm(P, near, hand, side) {
    if (near) { P.hand = hand; P.elbow = ik(P.shoulder, hand, 14, 13, side); } else { P.hand2 = hand; P.elbow2 = ik(P.shoulder, hand, 14, 13, side); }
  }

  /** Knee that always bends forward. */
  _knee(hip, ankle) {
    const a = ik(hip, ankle, LEG.thigh, LEG.shin, 1);
    const b = ik(hip, ankle, LEG.thigh, LEG.shin, -1);
    const mx = (hip[0] + ankle[0]) / 2;
    return a[0] - mx >= b[0] - mx ? a : b;
  }

  // Between the man's and the woman's side view frames.
  _toF(p) { return [(p[0] - WK.FX) / WK.FS, p[1] / WK.FS]; }
  _fromF(p) { return [WK.FX + p[0] * WK.FS, p[1] * WK.FS]; }
  _zToF(z) { return (z - WK.FZ) / WK.FS; }

  /** Shaking with laughter: shoulders and head bounce, hand to the mouth. */
  _laugh(P, X, t, k, near = true) {
    const b = Math.abs(Math.sin(t * 16)) * 1.4 * k;
    P.shoulder = [P.shoulder[0], P.shoulder[1] + b];
    P.head = [P.head[0] - 0.6 * k, P.head[1] + b * 1.2];
    P.headTilt = lerp(P.headTilt || 0, -10, k);
    if (near) {
      this._arm(P, true, lerpPt(P.hand, [P.head[0] + 6, P.head[1] + 6], k), -1);
      X.handZ = lerp(X.handZ ?? SHO_W + 0.6, 2.5, k);
    }
    this._arm(P, false, lerpPt(P.hand2, [P.shoulder[0] + 7, P.shoulder[1] + 18], k), -1);
    X.hand2Z = lerp(X.hand2Z ?? -(SHO_W + 0.6), -4, k);
    X.eyes = lerp(1, 0.35, k);
  }

  _sit(P, k, lean = -4) {
    const hip = [-2, -24.6];
    const H = lerpPt(P.hip, hip, k);
    const dx = H[0] - P.hip[0];
    const dy = H[1] - P.hip[1];
    P.hip = H;
    P.shoulder = rotAround([P.shoulder[0] + dx, P.shoulder[1] + dy], H, lean * k);
    P.head = rotAround([P.head[0] + dx, P.head[1] + dy], H, lean * k);
    P.ankle = lerpPt(P.ankle, [18, -3], k);
    P.ankle2 = lerpPt(P.ankle2, [14, -3], k);
    P.footAng = lerp(P.footAng || 0, 0, k);
    P.footAng2 = lerp(P.footAng2 || 0, 0, k);
    P.foot = [P.ankle[0], 0];
    P.foot2 = [P.ankle2[0], 0];
    P.knee = this._knee(P.hip, P.ankle);
    P.knee2 = this._knee(P.hip, P.ankle2);
    this._arm(P, true, lerpPt(P.hand, [H[0] + 15, H[1] - 3], k), -1);
    this._arm(P, false, lerpPt(P.hand2, [H[0] + 13, H[1] - 2], k), -1);
  }

  /** Sitting in the sand: knees up, one hand behind on the ground. */
  _sitSand(P, X, k, lean = -8) {
    const kneeUp = (hip, ankle) => {
      const a = ik(hip, ankle, LEG.thigh, LEG.shin, 1);
      const b = ik(hip, ankle, LEG.thigh, LEG.shin, -1);
      return a[1] <= b[1] ? a : b;
    };
    const H = lerpPt(P.hip, [-1, -9.5], k);
    const dx = H[0] - P.hip[0];
    const dy = H[1] - P.hip[1];
    P.hip = H;
    P.shoulder = rotAround([P.shoulder[0] + dx, P.shoulder[1] + dy], H, lean * k);
    P.head = rotAround([P.head[0] + dx, P.head[1] + dy], H, lean * k);
    P.ankle = lerpPt(P.ankle, [25, -3], k);
    P.ankle2 = lerpPt(P.ankle2, [21, -3], k);
    P.footAng = lerp(P.footAng || 0, -14, k);
    P.footAng2 = lerp(P.footAng2 || 0, -14, k);
    P.foot = [P.ankle[0], 0];
    P.foot2 = [P.ankle2[0], 0];
    P.knee = k > 0.5 ? kneeUp(P.hip, P.ankle) : this._knee(P.hip, P.ankle);
    P.knee2 = k > 0.5 ? kneeUp(P.hip, P.ankle2) : this._knee(P.hip, P.ankle2);
    this._arm(P, true, lerpPt(P.hand, [P.knee[0] - 1, P.knee[1] - 1], k), -1);
    this._arm(P, false, lerpPt(P.hand2, [H[0] - 12, -1.5], k), 1);
    X.footZ = lerp(X.footZ ?? HIP_W, HIP_W + 1.5, k);
    X.foot2Z = lerp(X.foot2Z ?? -HIP_W, -HIP_W - 1.5, k);
    X.hand2Z = lerp(X.hand2Z ?? -(SHO_W + 0.6), -SHO_W - 3, k);
  }

  /** Pose from a gait at a given ground speed, with its own phase. */
  _gait(key, run, ground, dt, lean = 0) {
    const g = run ? GAITS.run : GAITS.walk;
    const amp = run ? clamp(0.55 + ground / 160, 0.6, 1.05) : clamp(0.62 + ground / 110, 0.62, 1.0);
    this[key] = (this[key] || 0) + (ground * dt) / strideOf(g, amp);
    return gaitPose(g, this[key], amp, clamp(ground / (run ? 25 : 12), 0, 1), lean);
  }

  /** Head turn (degrees) of a person towards a world point, limited. */
  _lookAt(rig, p, limit = 100) {
    const local = rig.body.worldToLocal(p.clone());
    const hd = rig.head.position;
    return clamp(Math.atan2(-(local.z - hd.z), local.x - hd.x) / RAD, -limit, limit);
  }

  /* ------------------------------ frame ------------------------------ */

  setLook(look, pace, mood) {
    this.look = look;
    this.paceTarget = pace;
    this.mood = mood || {};
    this.world.setLook(look, this.mood);
  }

  /** Single still frame at the final pace, for reduced motion. */
  still() {
    this.pace = this.paceTarget;
    this.step(0.016);
  }

  step(dt) {
    this.t += dt;
    this.pace += (this.paceTarget - this.pace) * Math.min(1, dt * 1.5);
    this.plan(dt, this.pace);
    this.update(dt);
    const W = this.world;
    W.step(dt, this._frame(), V3(70, 32, 325));
    this.drops.step(dt);
    W.render();
  }

  /**
   * What the camera keeps in the picture: the couple in the middle (the
   * point between the two, also when he runs off), both of them in view,
   * and while the dinosaur matters its head as well.
   */
  _frame() {
    const c = this.couple.position;
    const pm = this.man.root.getWorldPosition(V3());
    const pf = this.woman.root.getWorldPosition(V3());
    const mid = pm.clone().add(pf).multiplyScalar(0.5);
    // Arms and legs reach about 22 units from the body while running.
    let lo = Math.min(pm.x, pf.x) - 22;
    let hi = Math.max(pm.x, pf.x) + 22;
    const d = this.dino.root;
    if (this.ev && this.ev.ev === 'dino') {
      const et = this.evT;
      const D = this.DINO;
      // He runs off fast: also frame where he is a moment later.
      const ahead = keyAt(D.man, et + 0.3) - keyAt(D.man, et);
      hi = Math.max(hi, pm.x + ahead + 22);
      lo = Math.min(lo, pm.x + ahead - 22);
      // The dinosaur's head, from its roar until she has told it off (it
      // turns round at 10.55), also a moment ahead.
      const w = ease(clamp((et - 1.3) / 0.6, 0, 1)) * (1 - ease(clamp((et - 10.0) / 0.55, 0, 1)));
      if (w > 0 && d.visible) {
        const s = d.scale.x * (Math.cos(d.rotation.y) < 0 ? -1 : 1);
        const dx = keyAt(D.x, et + 0.3) - keyAt(D.x, et);
        const hs = [5, 55].flatMap((u) => [d.position.x + u * s, d.position.x + dx + u * s]);
        lo = lerp(lo, Math.min(lo, ...hs), w);
        hi = lerp(hi, Math.max(hi, ...hs), w);
      }
    }
    return { x: mid.x, z: mid.z, y: c.y + 50, lz: lerp(WK.ZM, this.cz, 0.45), lo, hi };
  }

  resize(w, h) { this.world.resize(w, h); }

  /** Draws the current frame again (after a resize while paused). */
  redraw() { this.world.render(); }

  dispose() { this.world.dispose(); }

  update(dt) {
    const t = this.t;
    const W = this.world;
    const look = W.L2 || this.look;
    const ev = this.ev ? this.ev.ev : null;
    const et = this.evT;
    const K = WK.K;
    const XM = {};
    const XF = {};
    let hold = true;
    let mouthM = 'calm';
    let mouthF = 'smile';

    // Stand-still comedy for bad weather.
    const standing = this.vel < 5 && !ev;
    let reason = standing ? moodReason(this.mood) : null;
    // In snow they huddle together instead of fighting over the umbrella.
    if (reason && look.snow) reason = 'cold';
    if (reason && this.GAG[reason]) {
      if (this.gag !== reason) { this.gag = reason; this.gagT = 0; }
      this.gagT += dt;
      if (this.gagT >= this.GAG[reason]) this.gagT -= this.GAG[reason];
    } else { this.gag = null; this.gagT = 0; }
    const gag = this.gag;
    const gt = this.gagT;

    // Where the couple stands and which way they face.
    const st = ev && this.STAGE[ev];
    const pz = this.cz;
    const pyaw = this.cyaw;
    if (st) {
      this.cz = keyAt(st.z, et);
      this.cyaw = keyAt(st.yaw, et);
    } else {
      const k = 1 - Math.exp(-dt * 2.5);
      this.cz += (WK.ZM - this.cz) * k;
      this.cyaw += ((gag ? -35 : 0) - this.cyaw) * k;
    }
    // Stepping speed while they move or turn on the spot.
    const moveSp = dt > 0 ? (Math.abs(this.cz - pz) + Math.abs(this.cyaw - pyaw) * RAD * 13) / dt : 0;
    this.localSpeed += (moveSp - this.localSpeed) * Math.min(1, dt * 10);

    // Base poses: walking at the speed of the path (plus stepping).
    const g = GAITS.walk;
    const ground = this.vel / K + this.localSpeed;
    const ampM = clamp(0.62 + ground / 110, 0.62, 1.0);
    const ampF = clamp(0.62 + ground / 100, 0.62, 1.0);
    this.phM += (ground * dt) / strideOf(g, ampM);
    this.phF += ((ground / WK.FS) * dt) / strideOf(g, ampF);
    const wW = clamp(ground / 12, 0, 1);
    // Uphill they lean forward a little, downhill back.
    const slope = (this.terrain(this.s + 8) - this.terrain(this.s - 8)) * WK.HK;
    const lean = clamp(slope * 0.35, -3, 5);
    const M = gaitPose(g, this.phM, ampM, wW, lean);
    const F = gaitPose(g, this.phF, ampF, wW, lean);

    // ---------- holding hands ----------
    const HZ = (-SHO_W + (WK.FZ + SHO_W * WK.FS)) / 2;
    const handsMeet = (k = 1) => {
      const fsh = this._fromF(F.shoulder);
      const H = [(M.shoulder[0] + fsh[0]) / 2, M.hip[1] - 3 + Math.sin(this.phM * Math.PI * 2) * 1.2 * wW];
      this._arm(M, false, lerpPt(M.hand2, H, k), -1);
      XM.hand2Z = lerp(XM.hand2Z ?? -(SHO_W + 0.6), HZ, k);
      this._arm(F, true, lerpPt(F.hand, this._toF(H), k), -1);
      XF.handZ = lerp(XF.handZ ?? SHO_W + 0.6, this._zToF(HZ), k);
    };
    let holdK = 1;

    // ---------- trip over the root ----------
    if (ev === 'trip') {
      hold = false;
      const k = (x0, x1) => ease(clamp((et - x0) / (x1 - x0), 0, 1));
      const pitch = et < 0.3 ? 30 * k(0, 0.3) : et < 1.1 ? 30 - 8 * Math.sin((et - 0.3) * 9) : 30 * (1 - k(1.1, 1.6));
      // Stumbling steps forward, then feet together again.
      const stepA = et > 0.3 && et < 1.1 ? Math.max(0, Math.sin((et - 0.3) * 11)) * 5 : 0;
      const stepB = et > 0.3 && et < 1.1 ? Math.max(0, -Math.sin((et - 0.3) * 11)) * 5 : 0;
      const fwd = Math.sin(clamp(et / 1.2, 0, 1) * Math.PI) * 7;
      const tk = k(0, 0.25);
      M.hip = [M.hip[0] + fwd, M.hip[1] + 1.5 * k(0, 0.3) * (1 - k(1.1, 1.6))];
      M.ankle = lerpPt(M.ankle, [9 + fwd * 1.4, -3 - stepA], tk);
      M.ankle2 = lerpPt(M.ankle2, [-4 + fwd * 0.8, -3 - stepB], tk);
      M.footAng = lerp(M.footAng, 0, tk); M.footAng2 = lerp(M.footAng2, 0, tk);
      M.foot = [M.ankle[0], 0]; M.foot2 = [M.ankle2[0], 0];
      M.knee = this._knee(M.hip, M.ankle);
      M.knee2 = this._knee(M.hip, M.ankle2);
      M.shoulder = rotAround([M.hip[0] + 1, M.hip[1] - LEG.torso], M.hip, pitch);
      M.head = rotAround([M.hip[0] + 2.2, M.hip[1] - LEG.torso - 10.5], M.hip, pitch);
      // Arms windmill, blended in and out.
      const wm = k(0.2, 0.4) * (1 - k(1.25, 1.5));
      if (wm > 0) {
        const a = -et * 15;
        this._arm(M, true, lerpPt(M.hand, [M.shoulder[0] + Math.cos(a) * 20, M.shoulder[1] + Math.sin(a) * 20], wm), -1);
        this._arm(M, false, lerpPt(M.hand2, [M.shoulder[0] + Math.cos(a + 2.4) * 20, M.shoulder[1] + Math.sin(a + 2.4) * 20], wm), -1);
        XM.handZ = SHO_W + 6 * wm;
        XM.hand2Z = -SHO_W - 6 * wm;
        mouthM = 'open';
      }
      const sc = k(1.55, 1.8) * (1 - k(2.9, 3.2));
      if (sc > 0) {
        // Scratches the back of his head, embarrassed.
        M.headTilt = 10 * sc;
        this._arm(M, true, lerpPt(M.hand, [M.head[0] - 3 + Math.sin(t * 14) * 1.2, M.head[1] - 6], sc), 1);
        XM.handZ = lerp(SHO_W + 0.6, 6, sc);
        mouthM = 'frown';
      }
      if (et < 0.5) mouthF = 'open';
      else if (et < 3.2) { this._laugh(F, XF, t, k(0.5, 0.8) * (1 - k(2.9, 3.3))); mouthF = 'laugh'; }
    }

    // ---------- a dinosaur chases them ----------
    const dWorld = this.vel / K;
    let manOff = 0;
    let manFlip = false;
    let femFlip = false;
    let lookM = false;
    let lookF = false;
    let jump = 0;
    if (ev === 'dino') {
      const D = this.DINO;
      manOff = keyAt(D.man, et);
      const dMan = (keyAt(D.man, et + 0.02) - keyAt(D.man, et - 0.02)) / 0.04;
      manFlip = et > 10.55 && et < 12.6;
      // They keep holding hands until the roar, and take hands again at the end.
      const kk = (a, b) => ease(clamp((et - a) / (b - a), 0, 1));
      holdK = et < 7 ? 1 - kk(1.9, 2.35) : kk(13.1, 13.55);
      hold = holdK > 0.001;
      // They hear it, look back, jump with fright and run.
      jump = Math.sin(clamp((et - 2.25) / 0.35, 0, 1) * Math.PI) * 6;
      const into = ease(clamp((et - 2.6) / 0.3, 0, 1));
      if (et > 2.6 && et < 7.95) Object.assign(M, mixPose(clonePose(M), this._gait('phMr', true, dWorld + dMan, dt), into));
      else if (manFlip) Object.assign(M, this._gait('phMb', false, Math.abs(dMan), dt));
      if (et > 2.6 && et < 7.55) Object.assign(F, mixPose(clonePose(F), this._gait('phFr', true, dWorld / WK.FS, dt), into));
      if (et > 1.9 && et < 2.45) { lookM = true; lookF = true; }
      if (et > 3.6 && et < 4.3) lookM = true;
      if (et > 1.9 && et < 7.95) mouthM = 'open';
      if (et > 1.9 && et < 7.6) mouthF = 'open';
      if (et >= 7.95 && et < 10.55) {
        // He has run on far ahead and peeks back, trembling.
        lookM = true;
        const tr = tremor(t) * 0.5;
        M.shoulder = [M.shoulder[0] + tr, M.shoulder[1] + 1];
        M.head = [M.head[0] + tr, M.head[1] + 1.2];
        M.headTilt = 6;
        this._arm(M, true, [M.head[0] + 6, M.head[1] + 9], -1);
        this._arm(M, false, [M.head[0] + 4, M.head[1] + 10], -1);
        XM.handZ = 3;
        XM.hand2Z = -3;
        mouthM = et < 10 ? 'open' : 'calm';
      }
      if (manFlip) mouthM = 'smile';
      if (et >= 12.6 && et < 13.3) {
        // Back with her, a little embarrassed.
        M.headTilt = 10;
        this._arm(M, true, [M.head[0] - 3 + Math.sin(t * 14) * 1.2, M.head[1] - 6], 1);
        XM.handZ = 6;
        mouthM = 'smile';
      }
      femFlip = et >= 7.6 && et < 10.5;
      if ((et >= 7.7 && et < 8.3) || (et >= 10.5 && et < 13.1)) {
        this._arm(F, true, [F.hip[0] + 6, F.hip[1] - 2], 1);
        this._arm(F, false, [F.hip[0] - 5, F.hip[1] - 2], -1);
        XF.handZ = SHO_W + 1;
        XF.hand2Z = -SHO_W - 1;
        F.headTilt = -6;
        mouthF = 'frown';
      }
      if (et >= 8.3 && et < 10.5) {
        // She tells the dinosaur off, wagging her finger; as it shrinks she
        // looks and points down at it.
        leanPose(F, 6);
        const down = ease(clamp((et - 8.6) / 1.0, 0, 1));
        this._arm(F, true, [F.shoulder[0] + 21 - down * 3, F.shoulder[1] - 5 + down * 13 + Math.sin(t * 14) * 3], -1);
        this._arm(F, false, [F.hip[0] - 5, F.hip[1] - 2], -1);
        XF.handZ = 6;
        XF.hand2Z = -SHO_W - 1;
        F.headTilt = lerp(-10, 14, down);
        mouthF = Math.sin(t * 11) > 0 ? 'open' : 'frown';
      }
      if (et >= 13.3) mouthF = 'smile';
    }
    this._dino(ev === 'dino' ? et : -1, dWorld, dt, t);

    // ---------- bench: sit, he nods off, she pokes him ----------
    let zzz = 0;
    let eyesM = 1;
    if (ev === 'bench') {
      hold = false;
      const e = et - WK.BENCH_T0;
      const k = (x0, x1) => ease(clamp((e - x0) / (x1 - x0), 0, 1));
      const sit = k(0.2, 1.3) * (1 - k(7.6, 8.7));
      this._sit(M, sit);
      this._sit(F, sit);
      const lean2 = k(1.5, 2.4) * (1 - k(5.6, 6.0));
      XF.roll = 13 * lean2 * sit;
      F.headTilt = 6 * lean2;
      if (sit > 0.4) {
        // His arm around her shoulders, blended in as they sit.
        const sh = this._fromF(F.shoulder);
        const a = ease(clamp((sit - 0.4) / 0.5, 0, 1));
        this._arm(M, false, lerpPt(M.hand2, [sh[0] - 1, sh[1] + 2], a), -1);
        XM.hand2Z = lerp(-(SHO_W + 0.6), WK.FZ + SHO_W * WK.FS * 0.4, a);
        mouthF = 'smile';
      }
      if (e > 2.6 && e < 5.6) {
        // Nods off.
        const nod = k(2.6, 3.4);
        M.headTilt = 24 * nod + Math.sin(t * 2) * 3 * nod;
        M.head = [M.head[0] + 1.5 * nod, M.head[1] + 2.5 * nod];
        zzz = nod;
        eyesM = lerp(1, 0.08, nod);
        mouthM = 'open';
      }
      if (e >= 5.2 && e < 5.8) {
        // She pokes him.
        this._arm(F, true, this._toF([M.shoulder[0] + 4, M.shoulder[1] + 6]), -1);
        XF.handZ = this._zToF(-SHO_W + 2);
        mouthF = 'frown';
      }
      if (e >= 5.6 && e < 6.2) {
        // He startles.
        const j = Math.sin(clamp((e - 5.6) / 0.5, 0, 1) * Math.PI);
        M.hip = [M.hip[0], M.hip[1] - 4 * j];
        M.shoulder = [M.shoulder[0], M.shoulder[1] - 5 * j];
        M.head = [M.head[0], M.head[1] - 5 * j];
        M.headTilt = -6;
        mouthM = 'open';
        M.knee = this._knee(M.hip, M.ankle);
        M.knee2 = this._knee(M.hip, M.ankle2);
      }
      if (e >= 6.2 && e < 7.6) mouthF = 'laugh';
    }
    this.zzz.forEach((s, i) => {
      s.visible = zzz > 0.02;
      if (!s.visible) return;
      const hp = this.man.head.localToWorld(V3(2, 10, 0));
      const rise = ((t * 0.6 + i / 3) % 1);
      s.position.set(hp.x + 4 + i * 2 + rise * 6, hp.y + 4 + rise * 16, hp.z + 6);
      s.scale.setScalar(4 + rise * 4);
      s.material.opacity = zzz * Math.sin(rise * Math.PI);
    });

    // ---------- beach: sit in the sand and watch the boats ----------
    const be = ev === 'beach' ? et - WK.BEACH_T0 : -1;
    const bc = this.route.beachCenter;
    const sailX = be >= 0 ? lerp(300, -260, be / 13) : 400;
    const motX = be >= 4 ? lerp(330, -330, clamp((be - 4) / 4.2, 0, 1)) : 450;
    this.sail.visible = ev === 'beach';
    this.motor.visible = ev === 'beach' && be >= 4 && be < 8.4;
    const near = (x) => {
      const cx = this.couple.position.x;
      return cx + wrap(x - cx, -this.route.length / 2, this.route.length / 2);
    };
    this.sail.position.set(near(bc + sailX), SEA_Y + Math.sin(t * 1.4) * 0.8, -440);
    this.sail.rotation.set(Math.sin(t * 1.1) * 0.03, 0, Math.sin(t * 0.9) * 0.04);
    this.motor.position.set(near(bc + motX), SEA_Y + Math.sin(t * 5) * 0.5, -230);
    this.motor.scale.setScalar(1.25);
    this.motor.rotation.set(0, 0, Math.sin(t * 5) * 0.02);
    if (ev === 'beach') {
      hold = false;
      const e = be;
      const k = (a, b) => ease(clamp((e - a) / (b - a), 0, 1));
      const sit = k(0.3, 1.5) * (1 - k(11.4, 12.7));
      this._sitSand(M, XM, sit, -8);
      this._sitSand(F, XF, sit, -8);
      mouthM = 'smile';
      mouthF = 'smile';
      if (e > 1.5 && e < 11.2) {
        // Heads follow the boats.
        const target = this.motor.visible ? this.motor.position : this.sail.position;
        this.couple.updateMatrixWorld(true);
        XM.headYaw = this._lookAt(this.man, target, 70) * k(1.5, 2.2);
        XF.headYaw = this._lookAt(this.woman, target, 70) * k(1.5, 2.2);
      }
      if (e > 3.6 && e < 5.2) {
        // He points at the sailboat.
        const pk = k(3.6, 3.9) * (1 - k(4.9, 5.2));
        this._arm(M, true, lerpPt(M.hand, [M.shoulder[0] + 20, M.shoulder[1] - 13], pk), -1);
        XM.handZ = lerp(XM.handZ ?? SHO_W, SHO_W + 8, pk);
        mouthM = 'laugh';
      }
      const lean2 = k(5.0, 5.9) * (1 - k(10.2, 10.8));
      if (lean2 > 0) {
        // She leans her head on his shoulder, his arm around her.
        XF.roll = 14 * lean2;
        XF.headLean = 0;
        F.headTilt = 8 * lean2;
        const sh = this._fromF(F.shoulder);
        this._arm(M, false, lerpPt(M.hand2, [sh[0] - 1, sh[1] + 2], lean2), -1);
        XM.hand2Z = lerp(XM.hand2Z ?? -SHO_W, WK.FZ + SHO_W * WK.FS * 0.4, lean2);
      }
      if (e > 5.9 && e < 7.1) {
        // He waves at the motorboat.
        const wk = k(5.9, 6.1) * (1 - k(6.9, 7.1));
        this._arm(M, true, lerpPt(M.hand, [M.shoulder[0] + 8 + Math.sin(t * 12) * 4, M.shoulder[1] - 20], wk), -1);
        XM.handZ = SHO_W + 4;
        mouthM = 'laugh';
      }
    }

    // ---------- selfie ----------
    let flash = 0;
    let phoneOn = false;
    if (ev === 'selfie') {
      const e = et - WK.SELFIE_T0;
      const k = (x0, x1) => ease(clamp((e - x0) / (x1 - x0), 0, 1));
      const up = k(0.2, 0.9) * (1 - k(4.2, 4.9));
      hold = true;
      // Heads together.
      XM.roll = -9 * up;
      XF.roll = 11 * up;
      M.headTilt = 4 * up;
      F.headTilt = -6 * up;
      const ph = e < 3.1 ? [M.shoulder[0] + 16, M.shoulder[1] - 16] : [M.head[0] + 12, M.head[1] + 8];
      this._arm(M, true, lerpPt(M.hand, ph, up), -1);
      XM.handZ = lerp(SHO_W + 0.6, 2, up);
      phoneOn = up > 0.3;
      if (e > 2.4 && e < 2.7) flash = 1 - (e - 2.4) / 0.3;
      mouthM = e > 1 && e < 3 ? 'smile' : 'calm';
      mouthF = e > 1 && e < 3 ? 'laugh' : 'smile';
    }

    // ---------- weather comedy ----------
    // Storm: the toupee.
    let toupeeOn = true;
    let tpFly = null;
    let toupeeRot = 0;
    if (gag === 'wind') {
      hold = false;
      const k = (x0, x1) => ease(clamp((gt - x0) / (x1 - x0), 0, 1));
      const gst = 0.5 + 0.5 * wobble(t * 1.1, 1);
      M.shoulder = rotAround(M.shoulder, M.hip, 6 + 5 * gst);
      M.head = rotAround(M.head, M.hip, 6 + 5 * gst);
      F.shoulder = rotAround(F.shoulder, F.hip, 6 + 5 * gst);
      F.head = rotAround(F.head, F.hip, 6 + 5 * gst);
      if (gt < 2.4) toupeeRot = -Math.abs(Math.sin(t * 9)) * 30 * (gt / 2.4);
      if (gt >= 2.4) toupeeOn = false;
      if (gt >= 2.4 && gt < 4.4) {
        const f = (gt - 2.4) / 2;
        tpFly = [M.head[0] - f * f * 300, M.head[1] - 10 - f * 70 + Math.sin(f * 12) * 6, -f * 900];
      }
      if (gt >= 2.5 && gt < 8.6) {
        // Both hands on the bald head.
        const hk = k(2.5, 2.8) * (1 - k(8.4, 8.6));
        const h = [M.head[0] + 1, M.head[1] - 9];
        this._arm(M, true, lerpPt(M.hand, [h[0] + 3, h[1]], hk), -1);
        this._arm(M, false, lerpPt(M.hand2, [h[0] - 3, h[1]], hk), 1);
        XM.handZ = lerp(SHO_W, 4, hk);
        XM.hand2Z = lerp(-SHO_W, -4, hk);
        M.headTilt = 12;
        mouthM = gt < 3.2 ? 'open' : 'frown';
      }
      if (gt > 2.7 && gt < 6.5) { this._laugh(F, XF, t, k(2.7, 3.0) * (1 - k(6.2, 6.5))); mouthF = 'laugh'; }
      if (gt >= 6.8 && gt < 8.6) {
        // The wind turns and blows it back.
        const f = (gt - 6.8) / 1.8;
        tpFly = [lerp(-240, M.head[0] + 0.5, ease(f)), lerp(-120, M.head[1] - 1, f) - Math.sin(f * Math.PI) * 40, (1 - f) * 720 + 24];
      }
      if (gt >= 8.6) { toupeeOn = true; toupeeRot = gt < 9.6 ? 24 : 24 * (1 - k(9.6, 10.4)); }
      if (gt >= 8.6 && gt < 9.4) { M.headTilt = -8; mouthM = 'open'; }
      if (gt >= 9.5 && gt < 10.4) { this._arm(M, true, [M.head[0] + 2, M.head[1] - 9], -1); XM.handZ = 4; mouthM = 'smile'; }
      if (gt >= 8.6 && gt < 9.8) mouthF = 'laugh';
    }
    this.man.toupee.visible = toupeeOn;
    this.man.toupee.rotation.z = -0.12 - toupeeRot * RAD;
    this.flyToupee.visible = !!tpFly;
    if (tpFly) {
      const mb = this.manBase;
      this.flyToupee.position.set(mb.x + tpFly[0], -tpFly[1], mb.z + Math.sin(tpFly[2] * 0.01) * 6);
      this.flyToupee.rotation.set(tpFly[2] * RAD * 0.3, 0, -tpFly[2] * RAD);
    }

    // Rain: the gentleman and the puddle.
    let umb = null;
    let soaked = 0;
    this.puddle.visible = gag === 'rain';
    if (gag === 'rain') {
      hold = false;
      const k = (x0, x1) => ease(clamp((gt - x0) / (x1 - x0), 0, 1));
      // Umbrella over her; tilted to himself for a moment.
      const self = k(4.4, 5.2) * (1 - k(6.2, 6.6));
      const hand = [M.shoulder[0] + 9 - 3 * self, M.shoulder[1] - 3 - 5 * self];
      this._arm(M, false, hand, -1);
      XM.hand2Z = lerp(-17, -6, self);
      umb = { hand, z: XM.hand2Z, tilt: lerp(18, -12, self), far: true };
      soaked = 1 - self;
      F.headTilt = 4;
      mouthM = self > 0.5 ? 'smile' : 'frown';
      mouthF = self > 0.5 ? 'frown' : 'smile';
      if (self > 0.3) {
        // Arms crossed, cross look.
        this._arm(F, true, [F.shoulder[0] + 5, F.shoulder[1] + 9], -1);
        this._arm(F, false, [F.shoulder[0] + 5, F.shoulder[1] + 10], -1);
        XF.handZ = -3;
        XF.hand2Z = 3;
        F.headTilt = -8;
      }
      if (gt >= 7 && gt < 9.8) {
        // Steps back into the puddle, then shakes his foot.
        const back = k(7, 7.5);
        M.ankle = [M.ankle[0] - 11 * back, M.ankle[1]];
        M.foot = [M.ankle[0], 0];
        if (gt > 7.5 && !this.splashed) {
          this.splashed = true;
          const at = this.man.toWorld([M.ankle[0], 0], HIP_W);
          for (let i = 0; i < 16; i += 1) this.drops.emit(at, V3(rnd(-60, 60), rnd(60, 130), rnd(-60, 60)), rnd(0.5, 0.8), rnd(0.8, 1.3), at.y);
        }
        if (gt > 8.0) {
          const sh = Math.sin(t * 22) * 2;
          M.ankle = [M.ankle[0] + sh, -3 - 5 * Math.sin(clamp((gt - 8) / 1.8, 0, 1) * Math.PI)];
          M.footAng = 10 + sh * 4;
        }
        M.knee = this._knee(M.hip, M.ankle);
        mouthM = 'open';
        if (gt > 8.0) mouthF = 'laugh';
      }
      if (gt < 7) this.splashed = false;
      const pa = this.man.toWorld([-12, 0], HIP_W + 2);
      this.puddle.position.set(pa.x, this.world.heightAt(pa.x, pa.z) + 0.5, pa.z);
    } else if (look.rain > 0 && !look.snow && ev !== 'bench' && ev !== 'trip' && ev !== 'dino' && ev !== 'beach') {
      // Light rain on the way: he holds the umbrella over both of them,
      // she holds on to his arm.
      const hand = [M.shoulder[0] + 7, M.shoulder[1] + 3];
      this._arm(M, false, hand, -1);
      XM.hand2Z = -12;
      umb = { hand, z: -12, tilt: 4 + Math.sin(t * 3) * 2 + clamp(look.wind, 0, 40) * 0.15, far: true };
      hold = false;
      this._arm(F, true, this._toF([M.elbow2[0] + 1, M.elbow2[1] + 2]), -1);
      XF.handZ = this._zToF(-SHO_W - 2);
    }

    // Cold: huddled together, his nose starts to glow.
    let nose = 0;
    if (gag === 'cold') {
      hold = false;
      const k = (x0, x1) => ease(clamp((gt - x0) / (x1 - x0), 0, 1));
      const tr = tremor(t) * 0.5;
      const tr2 = tremor(t, 3) * 0.5;
      M.shoulder = [M.shoulder[0] + tr, M.shoulder[1] - 1 + tr2];
      M.head = [M.head[0] + tr * 0.6, M.head[1] + 1.6];
      F.shoulder = [F.shoulder[0] + tr2, F.shoulder[1] - 1];
      F.head = [F.head[0] + tr2 * 0.6, F.head[1] + 1.2];
      XF.roll = 12;
      XM.roll = -5;
      F.headTilt = 6;
      M.headTilt = 8;
      // His arm around her, she hugs herself.
      const sh = this._fromF(F.shoulder);
      this._arm(M, false, [sh[0] - 1, sh[1] + 2], -1);
      XM.hand2Z = WK.FZ + SHO_W * WK.FS * 0.4;
      if (look.rain > 0) {
        // Snow: he keeps the umbrella over both of them.
        const hand = [M.shoulder[0] + 10, M.shoulder[1] - 4];
        this._arm(M, true, hand, -1);
        XM.handZ = SHO_W - 4;
        umb = { hand, z: SHO_W - 4, tilt: 16 + tremor(t) * 1.5, far: false };
      } else {
        this._arm(M, true, [M.shoulder[0] + 4, M.shoulder[1] + 9 + Math.sin(t * 5.6) * 2], 1);
        XM.handZ = 0;
      }
      this._arm(F, false, [F.shoulder[0] + 5, F.shoulder[1] + 9], -1);
      this._arm(F, true, [F.shoulder[0] + 5, F.shoulder[1] + 8 + Math.sin(t * 5.6 + 1) * 2], -1);
      XF.handZ = -3;
      XF.hand2Z = 3;
      nose = k(2.5, 4.5);
      if (gt > 5.2 && gt < 7.6) {
        // She notices and points at his nose.
        const pk = k(5.2, 5.5) * (1 - k(7.3, 7.6));
        this.couple.updateMatrixWorld(true);
        const np = this.man.head.localToWorld(V3(10, -0.6, 0));
        const nl = this.woman.body.worldToLocal(np.clone());
        this._arm(F, true, lerpPt(F.hand, [nl.x - 3, -nl.y + 1], pk), -1);
        XF.handZ = lerp(XF.handZ, nl.z - 2, pk);
        F.headTilt = -6;
        mouthF = 'laugh';
      }
      if (gt > 7.6 && gt < 9.2) { this._laugh(F, XF, t, 1, false); mouthF = 'laugh'; }
      mouthM = gt > 6 ? 'frown' : 'calm';
    }
    this.man.redNose.visible = nose > 0.02;
    this.man.redNose.scale.setScalar(1.9 * (0.6 + 0.4 * nose));
    this.man.redNose.material.emissiveIntensity = 0.4 + nose * 0.6 + Math.sin(t * 4) * 0.2 * nose;
    this.noseGlow.material.opacity = nose * (0.35 + 0.2 * Math.sin(t * 4));

    // Umbrella placement.
    this.umbrella.visible = !!umb;
    if (umb) {
      const mb = this.manBase;
      this.umbrella.position.set(mb.x + manOff + umb.hand[0], -umb.hand[1], mb.z + umb.z);
      // Tilt towards her (-z) or himself.
      this.umbrella.rotation.set(-umb.tilt * RAD, 0, -6 * RAD);
    }
    this.wet = lerp(this.wet, soaked, Math.min(1, dt * (soaked ? 3 : 0.3)));
    this.man.setWet(this.wet);
    if (this.wet > 0.3 && Math.random() < dt * 10 * this.wet) {
      const p = this.man.toWorld([M.shoulder[0] + rnd(-4, 6), M.shoulder[1] + rnd(0, 20)], rnd(-6, 6));
      this.drops.emit(p, V3(rnd(-3, 3), 0, rnd(-3, 3)), 0.7, 0.8, this.world.heightAt(p.x, p.z));
    }

    // Heat: ice cream, fanning, splat.
    let ice = false;
    let scoopOn = false;
    let cream = 0;
    let tongue = false;
    this.flyScoop.visible = false;
    if (gag === 'hot') {
      hold = false;
      const k = (x0, x1) => ease(clamp((gt - x0) / (x1 - x0), 0, 1));
      ice = true;
      // She holds the cone near her mouth and licks.
      const lick = gt < 4.4 ? Math.max(0, Math.sin(t * 3)) : 0;
      this._arm(F, true, [F.head[0] + 9 - lick * 1.5, F.head[1] + 11 - lick * 2], -1);
      XF.handZ = 2;
      F.headTilt = 4 + lick * 6;
      scoopOn = gt < 4.6;
      // He fans her, faster and faster.
      const speed = gt < 3 ? 9 : 9 + (gt - 3) * 14;
      const fan = gt < 4.8 ? Math.sin(t * Math.min(speed, 30)) * 6 : 0;
      this._arm(M, false, [M.shoulder[0] + 12, M.shoulder[1] - 6 + fan], -1);
      XM.hand2Z = -18;
      mouthM = 'smile';
      if (gt >= 4.6 && gt < 5.1) {
        // The scoop flies off the cone into his face.
        const f = (gt - 4.6) / 0.5;
        this.couple.updateMatrixWorld(true);
        const from = this.ice.userData.scoop.getWorldPosition(V3());
        const to = this.man.head.localToWorld(V3(9, -1, 0));
        this.flyScoop.visible = true;
        this.flyScoop.position.lerpVectors(from, to, f);
        this.flyScoop.position.y += Math.sin(f * Math.PI) * 12;
      }
      if (gt >= 5.1) cream = 1 - k(8.4, 9.4);
      if (gt >= 5.1 && gt < 6.0) mouthM = 'open';
      if (gt >= 6.0 && gt < 8.0) { tongue = true; mouthM = 'calm'; }
      if (gt >= 8.0 && gt < 9.4) { this._arm(M, true, [M.head[0] + 8 + Math.sin(t * 12) * 3, M.head[1] + 2], -1); XM.handZ = 3; }
      if (gt >= 5.2 && gt < 8.4) mouthF = 'laugh';
      if (gt >= 9.4) mouthF = 'frown';
    }
    this.cream.visible = cream > 0.02;
    this.cream.scale.set(3.4 * cream, 3.0 * cream, 4.2 * cream);
    this.tongue.visible = tongue;
    if (tongue) this.tongue.rotation.set(Math.sin(t * 9) * 0.5, 0, -0.6);

    // ---------- holding hands, smoothly ----------
    const holdTarget = hold ? holdK : 0;
    this.holdW = this.holdW === undefined ? holdTarget : this.holdW + clamp(holdTarget - this.holdW, -dt / 0.35, dt / 0.35);
    if (this.holdW > 0.001) handsMeet(this.holdW);

    // ---------- placing everything ----------
    // Couple frame: their midpoint on the path (or off it during a scene).
    const x3 = this.s / K;
    // On the path the ground is the path; off it (bench, beach) the terrain.
    const cy = W.heightAt(x3, this.cz);
    this.couple.position.set(x3, cy, this.cz);
    this.couple.rotation.y = this.cyaw * RAD;
    const yAt = (lx) => W.heightAt(x3 + lx, this.cz) - cy;
    const mb = this.manBase;
    const wb = this.womanBase;
    this.man.root.position.set(mb.x + manOff, yAt(mb.x + manOff) + jump, mb.z);
    this.man.root.rotation.y = manFlip ? Math.PI : 0;
    this.woman.root.position.set(wb.x, yAt(wb.x) + jump, wb.z);
    this.woman.root.rotation.y = femFlip ? Math.PI : 0;

    // Looking back over the shoulder.
    if (lookM) XM.headYaw = -115;
    if (lookF) XF.headYaw = -115;
    // Ponytail swings with the steps and blows in the wind.
    if (this.woman.pony) {
      this.woman.pony.rotation.z = -(Math.sin(this.phF * Math.PI * 4) * 6 * wW - (gag === 'wind' ? 25 + Math.sin(t * 9) * 8 : 0)) * RAD;
      this.woman.pony.rotation.x = Math.sin(this.phF * Math.PI * 2) * 0.12 * wW;
    }
    const face = (rig, m) => {
      rig.setMouth(m);
      if (m === 'frown') rig.setBrows(-0.3, 0.35);
      else if (m === 'open') rig.setBrows(0.9, 0);
      else if (m === 'laugh') rig.setBrows(0.5, -0.1);
      else rig.setBrows(0, 0);
    };
    face(this.man, mouthM);
    face(this.woman, mouthF);
    this.man.setEyes(XM.eyes ?? (mouthM === 'laugh' ? 0.4 : eyesM));
    this.woman.setEyes(XF.eyes ?? (mouthF === 'laugh' ? 0.4 : 1));
    this.man.apply(M, XM);
    this.woman.apply(F, XF);
    if (XM.roll) this._rollTorso(this.man, XM.roll);
    if (XF.roll) this._rollTorso(this.woman, XF.roll);
    this.couple.updateMatrixWorld(true);

    // Things held in hands.
    this.phone.visible = phoneOn;
    if (phoneOn) {
      this.phone.position.copy(this.man.arm.n.hand.getWorldPosition(V3()));
      this.phone.quaternion.copy(this.couple.quaternion);
      this.phone.rotateZ(ev === 'selfie' && et - WK.SELFIE_T0 < 3.1 ? 0.35 : -0.2);
    }
    const fl = flash > 0;
    this.flash.visible = fl;
    this.flash.material.opacity = flash * 0.55;
    this.ice.visible = ice;
    if (ice) {
      this.ice.position.copy(this.woman.arm.n.hand.getWorldPosition(V3()));
      this.ice.position.y += 1;
      this.ice.quaternion.copy(this.couple.quaternion);
      this.ice.rotateZ(-0.15);
      this.ice.scale.setScalar(WK.FS);
      this.ice.userData.scoop.visible = scoopOn;
    }

    // Cheeks: rosy in the cold, flushed in the heat.
    const blush = Math.max(look.cold || 0, (this.mood.hot || 0) * 0.8, (this.mood.cold || 0) * 0.8);
    this.man.setBlush(blush);
    this.woman.setBlush(blush);

    // Breath clouds in the cold, sweat in the heat.
    const coldness = Math.max(look.cold || 0, this.mood.cold || 0);
    const breath = (t % 3.2) / 3.2;
    this.breathT = (this.breathT || 0) - dt;
    if (coldness > 0.05 && breath < 0.3 && this.breathT <= 0) {
      [this.man, this.woman].forEach((rig, i) => {
        const b2 = ((t + i * 1.3) % 3.2) / 3.2;
        if (b2 > 0.3) return;
        const at = rig.head.localToWorld(V3(10.5, -3.4, 0));
        const dir = rig.head.localToWorld(V3(30, -4, 0)).sub(at).normalize();
        this.world.puff(at, dir.multiplyScalar(22), 0.9, 1.9, coldness * 0.55);
      });
      this.breathT = 0.12;
    }
    const hot = this.mood.hot || 0;
    this.sweatT = (this.sweatT ?? 0.6) - dt;
    if (hot > 0 && this.sweatT <= 0) {
      const rig = Math.random() < 0.5 ? this.man : this.woman;
      const at = rig.head.localToWorld(V3(6.5, 3, rnd(-5, 5)));
      this.drops.emit(at, V3(0, -4, 0), 1.2, 0.7, at.y - 30);
      this.sweatT = (hot >= 1 ? 1.1 : 2.8) * rnd(0.7, 1.3);
    }
  }

  _rollTorso(rig, deg) {
    // Tilt the whole upper body around the hip, towards +z for positive.
    const r = deg * RAD;
    const hip = rig.torso.position.clone();
    const rotP = (o) => {
      const p = o.position.clone().sub(hip);
      const y = p.y * Math.cos(r) - p.z * Math.sin(r);
      const z = p.y * Math.sin(r) + p.z * Math.cos(r);
      o.position.set(p.x, y, z).add(hip);
    };
    const q = new T3.Quaternion().setFromAxisAngle(V3(1, 0, 0), r);
    rig.torso.quaternion.premultiply(q);
    [rig.neck, rig.head, rig.arm.n.upper, rig.arm.n.fore, rig.arm.n.hand, rig.arm.f.upper, rig.arm.f.fore, rig.arm.f.hand].forEach((o) => {
      rotP(o);
      if (o !== rig.head) o.quaternion.premultiply(q);
    });
    ['n', 'f'].forEach((s) => { if (rig.arm[s].sleeve) { rotP(rig.arm[s].sleeve); rig.arm[s].sleeve.quaternion.premultiply(q); } });
    rig.head.rotation.x += r * 0.6;
  }

  /** The dinosaur: stomping legs, roaring jaw, and later a very guilty look. */
  _dino(et, dWorld, dt, t) {
    const d = this.dino;
    if (et < 0 || et > 12.9) { d.root.visible = false; return; }
    const D = this.DINO;
    const k = (a, b) => ease(clamp((et - a) / (b - a), 0, 1));
    const x = keyAt(D.x, et);
    const vx = (keyAt(D.x, et + 0.02) - keyAt(D.x, et - 0.02)) / 0.04;
    const flip = et > 10.55;
    const sc = keyAt(D.size, et) * WK.DS;
    const ground = Math.max(0, ((vx + dWorld) * (flip ? -1 : 1)) / sc);
    const moving = ground > 2;
    const A = moving ? clamp(6 + ground * 0.08, 6, 18) : 0;
    this.dPh += (ground * dt) / (4 * Math.max(A, 6));

    const o = { t, lean: 0, head: 0, jaw: 0, tail: Math.sin(t * 5) * 4, arm: 0, brow: 'angry', pupil: 2, roar: 0, tear: -1 };
    if (et < 1.6) { o.lean = 6; o.head = -4; o.jaw = 4; } else if (et < 2.6) {
      o.lean = -8 * k(1.6, 1.9);
      o.head = -18 * k(1.6, 1.9) + Math.sin(t * 40) * 2;
      o.jaw = 28 * k(1.6, 1.85) * (1 - k(2.4, 2.6));
      o.roar = o.jaw > 8 ? 0.6 + 0.4 * Math.sin(t * 30) : 0;
      o.tail = 10;
    } else if (et < 6.9) {
      o.lean = 8;
      o.head = -4 + Math.sin(t * 6) * 3;
      o.jaw = 6 + Math.max(0, Math.sin(t * 7)) * 18;
      o.tail = Math.sin(t * 6) * 6;
      o.arm = Math.sin(t * 14) * 25;
    } else if (et < 8.3) {
      // Skids to a stop right in front of her, surprised.
      o.lean = et < 7.6 ? -14 : -6;
      o.head = -7;
      o.jaw = et < 7.6 ? 4 : 0;
      o.tail = 6;
      o.brow = 'surprised';
      o.pupil = et < 7.6 ? 2 : 1.3;
    } else {
      const f = k(8.3, 8.9);
      o.lean = flip ? 10 : 6 * f;
      o.head = flip ? 6 : 16 * f;
      o.tail = flip ? -10 + Math.sin(t * 10) * 4 : -16 * f;
      o.arm = 30 * f;
      o.brow = 'sad';
      if (et > 9.2 && !flip) o.tear = ((et - 9.2) / 0.7) % 1;
    }
    const bob = moving ? Math.abs(Math.sin(this.dPh * Math.PI * 2)) * 2.5 * (A / 18) : 0;
    o.bob = bob;
    const footAt = (q) => {
      const p = wrap(q, 0, 1);
      if (p < 0.5) return [A - 4 * A * p, 0];
      const f = (p - 0.5) / 0.5;
      return [-A + 2 * A * ease(f), -A * 0.7 * Math.sin(f * Math.PI)];
    };
    const leg = (hip, q) => {
      const f = footAt(q);
      const ankle = [hip[0] + f[0], f[1] - 3];
      const ka = ik(hip, ankle, 19, 20, 1);
      const kb = ik(hip, ankle, 19, 20, -1);
      const knee = ka[0] >= kb[0] ? ka : kb;
      return [hip, knee, ankle, f[1] < 0 ? clamp(-f[1] * 2, 0, 25) : 0];
    };
    o.legs = { far: leg([4, -38 - bob], this.dPh + 0.5), near: leg([-2, -38 - bob], this.dPh) };
    d.pose(o);
    d.root.visible = true;
    // Place it in the world, on the path behind the couple.
    const L3 = this.route.length;
    const cx = this.s / WK.K + this.manBase.x;
    const wx = cx + x;
    d.root.position.set(wx, this.route.height(wrap(wx, 0, L3)), WK.ZM + 2);
    d.root.rotation.y = flip ? Math.PI : 0;
    d.root.scale.setScalar(sc);
    // Dust when it skids to a stop.
    if (et > 6.95 && et < 7.6 && Math.random() < dt * 30) {
      const fp = d.root.localToWorld(V3(rnd(-6, 10), 2, rnd(-10, 10)));
      this.world.puff(fp, V3(rnd(-30, -5), rnd(4, 14), rnd(-8, 8)), 1.6, 1.1, 0.7, '#B7A487');
    }
  }
}

/* ------------------------------------------------------------------ *
 *  Cycling in 3D: a ride with changing scenes, about 45 seconds at full
 *  pace: cruising (a bird lands on the helmet), a sprint out of the
 *  saddle (the bird flies off), a climb, a fast tucked descent, a stop
 *  for a drink, a wheelie and an easy ride on.
 *  When the weather says no, a little comedy plays instead:
 *    storm  the helmet blows away, then rider and bike fly off; he
 *           pushes the bike back in against the wind
 *    rain   a car drives through the puddle and soaks him; he shakes
 *           himself dry like a dog
 *    cold   an icicle grows on his nose until he sneezes it off
 *    heat   a puddle of sweat grows; he pours his bottle over his head
 *
 *  Bike and rider are posed in "bike units" in the side view (as in the
 *  2D scene): rear axle at (-30, 0), front axle at (38, 0), ground at
 *  y = 21. One bike unit is 0.8 figure units.
 * ------------------------------------------------------------------ */
const BK = {
  PS: 1.25,          // rider size in bike units
  BU: 0.8,           // figure units per bike unit
  KX: 1.54,          // world units per plan unit along the road
  KH: 2.2,           // hills
  LANE: 0,           // the bike rides here (z)
  ROAD_Z0: -150,
  ROAD_Z1: 40,
};

/** The bicycle, in bike units with y up (2D y flipped), ground at y = -21. */
class Bicycle3D {
  constructor() {
    this.root = new T3.Group();
    const P = (x, y, z = 0) => V3(x, -y, z);
    this.frameM = mat('#FF7A1A', { unique: true, rough: 0.35, metal: 0.25 });
    this.frameColor = new T3.Color('#FF7A1A');
    const R = P(-30, 0);
    const BB = P(0, 4);
    const S = P(-8, -34);
    const HT = P(30, -31);
    const HB = P(33, -22);
    const F = P(38, 0);
    const tubes = [
      tubeGeo(BB, S, 1.7), tubeGeo(S, HT, 1.6), tubeGeo(BB, HB, 1.9), tubeGeo(HT, HB, 2.0),
      tubeGeo(V3(R.x, R.y, 3), V3(BB.x, BB.y, 2), 1.1), tubeGeo(V3(R.x, R.y, -3), V3(BB.x, BB.y, -2), 1.1),
      tubeGeo(V3(R.x, R.y, 3), V3(S.x, S.y, 1), 1.0), tubeGeo(V3(R.x, R.y, -3), V3(S.x, S.y, -1), 1.0),
      tubeGeo(V3(HB.x, HB.y, 2.6), V3(F.x, F.y, 3.2), 1.2), tubeGeo(V3(HB.x, HB.y, -2.6), V3(F.x, F.y, -3.2), 1.2),
    ];
    const frame = mesh(mergeGeos(tubes), this.frameM);
    this.root.add(frame);
    const metal = mat('#A9B8C9', { rough: 0.3, metal: 0.6 });
    const dark = mat('#11161D', { rough: 0.6 });
    // Seat post and saddle.
    this.root.add(mesh(tubeGeo(S, P(-9, -39.5), 1.1), metal));
    const saddle = mesh(geo('saddle', () => {
      const g = new T3.SphereGeometry(1, 16, 8);
      g.scale(8, 1.6, 3.4);
      const p = g.attributes.position;
      for (let i = 0; i < p.count; i += 1) if (p.getX(i) > 2) p.setZ(i, p.getZ(i) * (1 - (p.getX(i) - 2) / 9));
      g.computeVertexNormals();
      return g;
    }), dark);
    saddle.position.copy(P(-10, -41));
    this.root.add(saddle);
    // Stem and handlebar with drops.
    this.root.add(mesh(mergeGeos([tubeGeo(HT, P(32, -38), 1.1), tubeGeo(P(32, -38), P(37, -38), 1.1),
      tubeGeo(P(37, -38, -10), P(37, -38, 10), 1.1)]), metal));
    [10, -10].forEach((z) => {
      const d = mesh(geo('drop', () => {
        const t = new T3.TorusGeometry(3.4, 1.1, 6, 10, Math.PI);
        t.rotateZ(-Math.PI / 2);
        return t;
      }), dark);
      d.position.copy(P(37, -34.6, z));
      this.root.add(d);
    });
    // Wheels.
    this.wheels = [R, F].map((c) => {
      const w = new T3.Group();
      w.position.copy(c);
      const tire = mesh(geo('tire', () => new T3.TorusGeometry(19.6, 1.9, 8, 40)), mat('#15191F', { rough: 0.85 }));
      const rim = mesh(geo('rim', () => new T3.TorusGeometry(18.1, 0.7, 6, 40)), metal);
      const spokes = mesh(geo('spokes', () => {
        const list = [];
        for (let i = 0; i < 16; i += 1) {
          const a = (i / 16) * Math.PI * 2;
          const z = i % 2 ? 1.6 : -1.6;
          list.push(tubeGeo(V3(0, 0, z), V3(Math.cos(a) * 18, Math.sin(a) * 18, 0), 0.22, 4));
        }
        return mergeGeos(list);
      }), mat('#C3D0E0', { rough: 0.4, metal: 0.5 }), false);
      const hub = mesh(geo('hub', () => {
        const h = new T3.CylinderGeometry(2.2, 2.2, 5, 10);
        h.rotateX(Math.PI / 2);
        return h;
      }), metal);
      w.add(tire);
      w.add(rim);
      w.add(spokes);
      w.add(hub);
      this.root.add(w);
      return w;
    });
    // Chainring, chain, cranks and pedals.
    const ring = mesh(geo('chainring', () => new T3.TorusGeometry(6, 0.8, 6, 24)), metal);
    ring.position.copy(P(0, 4, 3.6));
    this.root.add(ring);
    this.root.add(mesh(mergeGeos([tubeGeo(P(0, -2, 3.4), P(-30, -3, 3.4), 0.5, 4), tubeGeo(P(0, 10, 3.4), P(-30, 3, 3.4), 0.5, 4)]), dark, false));
    this.cranks = [5.6, -5.6].map((z) => {
      const c = mesh(geo('crank', () => {
        const g = new T3.BoxGeometry(1, 2, 1.4);
        g.translate(0.5, 0, 0);
        return g;
      }), metal);
      c.position.copy(P(0, 4, z));
      this.root.add(c);
      const pedal = mesh(geo('pedal', () => new T3.BoxGeometry(5, 1.4, 4.6)), dark);
      this.root.add(pedal);
      return { c, pedal, z };
    });
    // Bottle cage and the bottle in it.
    this.bottle = Bicycle3D.bottle();
    this.bottle.position.copy(P(16, -8, 0));
    this.bottle.rotation.z = -52 * RAD;
    this.root.add(this.bottle);
    this.root.traverse((m) => { if (m.isMesh) m.castShadow = true; });
  }

  /** Green bottle with a white band and black cap; origin at its middle. */
  static bottle() {
    const g = new T3.Group();
    const body = mesh(geo('bottle', () => {
      const c = new T3.CylinderGeometry(3.2, 3.2, 15, 14);
      c.translate(0, -0.5, 0);
      return c;
    }), mat('#22E07A', { rough: 0.35 }));
    const band = mesh(geo('bottle-b', () => new T3.CylinderGeometry(3.3, 3.3, 4, 14)), mat('#E8EDF4', { rough: 0.5 }));
    band.position.y = 1;
    const cap = mesh(geo('bottle-c', () => new T3.CylinderGeometry(2, 2.2, 3.4, 10)), mat('#0B1017', { rough: 0.5 }));
    cap.position.y = 8.6;
    g.add(body);
    g.add(band);
    g.add(cap);
    return g;
  }

  /** wheel: rotation in radians; pedals: positions from the side view. */
  pose(wheel, near, far, frost) {
    this.wheels.forEach((w) => { w.rotation.z = -wheel; });
    [near, far].forEach((pd, i) => {
      const cr = this.cranks[i];
      const dx = pd[0];
      const dy = pd[1] - 4;
      cr.c.rotation.z = -Math.atan2(dy, dx);
      cr.c.scale.x = Math.hypot(dx, dy);
      cr.pedal.position.set(pd[0], -pd[1], cr.z * 1.45);
    });
    this.frameM.color.copy(this.frameColor).lerp(new T3.Color('#DDEFFF'), frost * 0.65);
  }
}

/** Helmet: yellow shell with vents and a little visor. Child of a head. */
function helmet3D(R) {
  const g = new T3.Group();
  const shell = mesh(geo('helmet', () => {
    const s = new T3.SphereGeometry(R * 1.16, 28, 12, 0, Math.PI * 2, 0, Math.PI * 0.52);
    s.scale(1.12, 0.86, 1.0);
    return s;
  }), mat('#FFC107', { rough: 0.35, side: T3.DoubleSide }));
  shell.position.set(-0.6, 0.6, 0);
  g.add(shell);
  const vm = mat('#B88A00', { rough: 0.5 });
  [-0.5, 0, 0.5].forEach((z) => {
    const v = mesh(geo('vent', () => new T3.BoxGeometry(9, 1.1, 1.3)), vm, false);
    v.position.set(-0.4, R * 1.02, z * 6);
    v.rotation.z = 0.12;
    g.add(v);
  });
  const visor = mesh(geo('visor', () => new T3.BoxGeometry(3.4, 0.8, 12)), mat('#FFC107', { rough: 0.35 }));
  visor.position.set(R * 1.02, 2.4, 0);
  visor.rotation.z = -0.25;
  g.add(visor);
  return g;
}

/** Sunglasses for the cyclist. Child of a head. */
function glasses3D(R) {
  const g = new T3.Group();
  const m = mat('#0B1017', { rough: 0.15, metal: 0.4 });
  [1, -1].forEach((sd) => {
    const lens = mesh(geo('lens', () => {
      const s = new T3.SphereGeometry(1, 12, 8);
      s.scale(0.6, 1.5, 2.1);
      return s;
    }), m, false);
    lens.position.set(R * 0.9, 1.7, sd * 2.9);
    g.add(lens);
    const arm = mesh(geo('temple', () => new T3.BoxGeometry(8, 0.5, 0.5)), m, false);
    arm.position.set(R * 0.5, 2.0, sd * R * 0.9);
    g.add(arm);
  });
  const bridge = mesh(geo('bridge', () => new T3.BoxGeometry(0.6, 0.5, 2)), m, false);
  bridge.position.set(R * 0.95, 2.1, 0);
  g.add(bridge);
  return g;
}

/** A small bird that can fly, land and hop. Faces +x. */
class Bird3D {
  constructor() {
    this.root = new T3.Group();
    const brown = mat('#4A3426', { rough: 0.8 });
    const body = blob('#4A3426', 5, 3.4, 3.4, { material: brown });
    const belly = blob('#D9774A', 3.2, 2.2, 2.6, { rough: 0.8 });
    belly.position.set(1, -1.2, 0);
    const head = blob('#4A3426', 2.5, 2.5, 2.4, { material: brown });
    head.position.set(4.4, 2.4, 0);
    const beak = mesh(geo('beak', () => {
      const c = new T3.ConeGeometry(0.8, 2.6, 6);
      c.rotateZ(-Math.PI / 2);
      return c;
    }), mat('#FFB020', { rough: 0.5 }), false);
    beak.position.set(7.4, 2.2, 0);
    const tail = blob('#3A2A20', 3.2, 0.6, 1.6, { rough: 0.8 });
    tail.position.set(-6, 1, 0);
    tail.rotation.z = 0.3;
    [body, belly, head, beak, tail].forEach((m) => this.root.add(m));
    [1, -1].forEach((sd) => {
      const eye = blob('#F2F6FB', 0.5, 0.5, 0.5, { shadow: false });
      eye.position.set(5.6, 3.0, sd * 1.7);
      this.root.add(eye);
    });
    this.wings = [1, -1].map((sd) => {
      const w = new T3.Group();
      w.position.set(0, 1.4, sd * 2.6);
      const m = blob('#6B4A36', 3.6, 0.5, 4.4, { rough: 0.8 });
      m.position.set(-0.6, 0, sd * 3.6);
      w.add(m);
      this.root.add(w);
      return { w, sd };
    });
    this.legs = new T3.Group();
    [1, -1].forEach((sd) => {
      const l = mesh(geo('bleg', () => new T3.CylinderGeometry(0.25, 0.25, 3, 4)), mat('#FFB020'), false);
      l.position.set(0, -4, sd * 1);
      this.legs.add(l);
    });
    this.root.add(this.legs);
  }

  pose(t, flap) {
    this.wings.forEach(({ w, sd }) => {
      w.rotation.x = flap ? sd * Math.sin(t * 28) * 0.9 : sd * -0.15;
    });
    this.legs.visible = !flap;
  }
}

/** A small blue car. Faces -x (it drives to the left), in figure units. */
class Car3D {
  constructor() {
    this.root = new T3.Group();
    const blue = mat('#3D7BD8', { rough: 0.3, metal: 0.25 });
    const body = mesh(geo('car-body', () => {
      const g = new T3.CapsuleGeometry(24, 150, 6, 16);
      g.rotateZ(Math.PI / 2);
      g.scale(1, 0.62, 1.7);
      return g;
    }), blue);
    body.position.y = 30;
    this.root.add(body);
    const cabin = mesh(geo('car-cabin', () => {
      const g = new T3.CapsuleGeometry(20, 70, 6, 16);
      g.rotateZ(Math.PI / 2);
      g.scale(1, 0.9, 1.75);
      return g;
    }), blue);
    cabin.position.set(6, 50, 0);
    this.root.add(cabin);
    const glass = mesh(geo('car-glass', () => {
      const g = new T3.CapsuleGeometry(19.2, 70, 6, 16);
      g.rotateZ(Math.PI / 2);
      g.scale(1.02, 0.55, 1.9);
      return g;
    }), mat('#9CC3F0', { rough: 0.1, metal: 0.3 }));
    glass.position.set(6, 53, 0);
    this.root.add(glass);
    const tireM = mat('#11161D', { rough: 0.8 });
    const hubM = mat('#C3D0E0', { rough: 0.3, metal: 0.6 });
    this.wheels = [];
    [[-62, 34], [-62, -34], [60, 34], [60, -34]].forEach(([x, z]) => {
      const w = new T3.Group();
      w.position.set(x, 17, z);
      const tire = mesh(geo('car-tire', () => {
        const g = new T3.CylinderGeometry(17, 17, 12, 18);
        g.rotateX(Math.PI / 2);
        return g;
      }), tireM);
      const hub = mesh(geo('car-hub', () => {
        const g = new T3.CylinderGeometry(8, 8, 12.4, 12);
        g.rotateX(Math.PI / 2);
        return g;
      }), hubM);
      w.add(tire);
      w.add(hub);
      this.root.add(w);
      this.wheels.push(w);
    });
    const lightM = mat('#FFE08A', { emissive: '#FFE08A', emissiveIntensity: 0.8 });
    [16, -16].forEach((z) => {
      const l = mesh(geo('car-light', () => new T3.BoxGeometry(2, 6, 9)), lightM, false);
      l.position.set(-110, 32, z * 1.6);
      this.root.add(l);
    });
    this.root.traverse((m) => { if (m.isMesh) m.castShadow = true; });
  }
}

/** Speech bubble sprite, e.g. a sneeze. */
function bubbleSprite(text) {
  const tex = canvasTex(256, 128, (g, w, h) => {
    g.fillStyle = '#F2F6FB';
    g.beginPath();
    g.ellipse(w / 2, h / 2 - 8, w / 2 - 8, h / 2 - 20, 0, 0, Math.PI * 2);
    g.fill();
    g.beginPath();
    g.moveTo(w * 0.28, h - 34);
    g.lineTo(w * 0.16, h - 4);
    g.lineTo(w * 0.42, h - 30);
    g.fill();
    g.fillStyle = '#0B1017';
    g.font = '800 46px Roboto, Arial, sans-serif';
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    g.fillText(text, w / 2, h / 2 - 8);
  });
  return new T3.Sprite(new T3.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
}

class BikeScene3D {
  constructor(canvas) {
    this.speed = 150;
    this.PS = BK.PS;
    this.PLAN = [
      { len: 650, mode: 'seat', v: 1.0, bird: true },
      { len: 520, mode: 'stand', v: 1.6 },
      { len: 320, mode: 'seat', v: 1.05 },
      { len: 820, mode: 'climb', v: 0.5, rise: 62 },
      { len: 200, mode: 'seat', v: 0.75 },
      { len: 820, mode: 'coast', v: 1.85, rise: -62 },
      { len: 380, mode: 'seat', v: 0.95 },
      { len: 0, mode: 'pause', v: 0 },
      { len: 260, mode: 'seat', v: 0.8 },
      { len: 330, mode: 'seat', v: 0.9, wheelie: true },
      { len: 300, mode: 'seat', v: 0.85 },
    ];
    this.PAUSE = 8.4;
    this.GAG = { wind: 17, rain: 11, cold: 10, hot: 11 };
    this._init();

    const L3 = this.L * BK.KX;
    this.route = {
      length: L3,
      style: 'road',
      z0: BK.ROAD_Z0,
      z1: BK.ROAD_Z1,
      height: (x) => this.terrain(x / BK.KX) * BK.KH,
      beach: () => 0,
    };
    this.world = new World3D(canvas, this.route);
    const W = this.world;

    // Bike and rider. bikeRoot sits on the road and follows its slope;
    // fig carries the side view coordinates (bike units, y flipped).
    this.bikeRoot = new T3.Group();
    W.scene.add(this.bikeRoot);
    this.fig = new T3.Group();
    this.fig.scale.setScalar(BK.BU);
    this.fig.position.y = 21 * BK.BU;
    this.bikeRoot.add(this.fig);
    this.flyG = new T3.Group();
    this.fig.add(this.flyG);
    this.content = new T3.Group();
    this.content.position.set(30, 21, 0);
    this.flyG.add(this.content);
    this.bike = new Bicycle3D();
    this.content.add(this.bike.root);
    this.rider = new Person3D({ kind: 'man', hairStyle: 'short', shirt: '#3D8BFF', sleeves: 'short', pants: '#1B2230', legs: 'skin', shoes: '#E8EDF4', hair: '#3A2A20', brow: '#3A2A20', scale: this.PS });
    this.content.add(this.rider.root);
    this.helmet = helmet3D(this.rider.headR);
    this.rider.head.add(this.helmet);
    this.rider.head.add(glasses3D(this.rider.headR));
    this.flyHelmet = helmet3D(this.rider.headR);
    this.flyHelmet.scale.setScalar(this.PS);
    this.flyHelmet.visible = false;
    this.content.add(this.flyHelmet);
    this.handBottle = Bicycle3D.bottle();
    this.handBottle.visible = false;
    this.content.add(this.handBottle);
    // Icicle on the nose, the flying one and its shards.
    this.icicle = mesh(geo('icicle', () => {
      const c = new T3.ConeGeometry(1.25, 1, 8);
      c.rotateX(Math.PI);
      c.translate(0, -0.5, 0);
      return c;
    }), mat('#BFE6FF', { rough: 0.1, metal: 0.1, opacity: 0.92 }), false);
    this.icicle.position.set(this.rider.headR * 1.0, -1.2, 0);
    this.icicle.visible = false;
    this.rider.head.add(this.icicle);
    this.flyIce = mesh(geo('icicle', () => null), mat('#DFF3FF', { rough: 0.1, metal: 0.1, opacity: 0.9 }), false);
    this.flyIce.visible = false;
    this.content.add(this.flyIce);
    this.shards = Array.from({ length: 6 }, () => {
      const m = mesh(geo('shard', () => new T3.TetrahedronGeometry(1.4)), mat('#DFF3FF', { rough: 0.1, opacity: 0.9 }), false);
      m.visible = false;
      this.content.add(m);
      return m;
    });
    this.sneeze = { de: bubbleSprite('Hatschi!'), en: bubbleSprite('Achoo!') };
    Object.values(this.sneeze).forEach((s) => { s.visible = false; s.scale.set(40, 20, 1); this.content.add(s); });
    this.bird = new Bird3D();
    this.bird.root.visible = false;
    this.bird.root.scale.setScalar(1.2);
    this.content.add(this.bird.root);
    this.car = new Car3D();
    this.car.root.visible = false;
    W.scene.add(this.car.root);
    this.puddle = PROPS.puddle();
    this.puddle.visible = false;
    W.scene.add(this.puddle);
    this.sweat = PROPS.puddle();
    this.sweat.visible = false;
    W.scene.add(this.sweat);
    this.drops = new Drops3D(W.scene, 110);
    W.onWrap.push((dx) => this.drops.shift(dx));

    this.look = { cloud: 0.3, rain: 0, snow: false, wind: 6, hot: 0, cold: 0 };
    this.mood = {};
    this.pace = 0;
    this.paceTarget = 0;
    this.t = 0;
    this.lang = 'en';
  }

  _init() {
    let s = 0;
    let e = 0;
    this.segs = this.PLAN.map((g) => {
      const o = { ...g, s0: s, e0: e };
      s += g.len;
      e += g.rise || 0;
      o.s1 = s;
      return o;
    });
    this.L = s;
    this.pausePos = this.segs.find((g) => g.mode === 'pause').s0;
    this.s = 0;
    this.vel = 0;
    this.pauseT = -1;
    this.pauseDone = false;
    this.crank = 0;
    this.wheel = 0;
    this.stopW = 1;
    this.W = { seat: 1, stand: 0, climb: 0, coast: 0 };
    this.gag = null;
    this.gagT = 0;
    this.wheelie = 0;
    this.puddleR = 0;
    this.wet = 0;
  }

  _seg(s) {
    const q = wrap(s, 0, this.L);
    return this.segs.find((g) => q >= g.s0 && q < g.s1) || this.segs[this.segs.length - 1];
  }

  /** Height of the road at a plan position, smooth over each slope. */
  terrain(s) {
    const q = wrap(s, 0, this.L);
    const g = this._seg(q);
    if (!g.rise) return g.e0;
    return g.e0 + g.rise * ease(clamp((q - g.s0) / g.len, 0, 1));
  }

  /** Speed for this frame, with braking into the stop. */
  plan(dt, pace) {
    if (this.pauseT >= 0) {
      this.pauseT += dt;
      if (this.pauseT >= this.PAUSE || pace < 0.02) { this.pauseT = -1; this.pauseDone = true; }
      this.vel = 0;
      return 0;
    }
    const g = this._seg(this.s);
    let vt = g.v * this.speed * pace;
    if (g.mode === 'climb' && (this.s - g.s0) / g.len > 0.62) vt *= 0.9;
    if (!this.pauseDone && pace > 0.02) {
      const dp = this.pausePos - this.s;
      if (dp >= 0 && dp < 450) {
        vt = Math.min(vt, Math.sqrt(2 * 75 * dp));
        if (dp <= Math.max(this.vel * dt, 0.05)) { this.s = this.pausePos; this.vel = 0; this.pauseT = 0; return 0; }
      }
    }
    const acc = vt > this.vel ? 55 : 120;
    this.vel += clamp(vt - this.vel, -acc * dt, acc * dt);
    this.s += this.vel * dt;
    if (this.s >= this.L) { this.s -= this.L; this.pauseDone = false; }
    return this.vel;
  }

  setLook(look, pace, mood) {
    this.look = look;
    this.paceTarget = pace;
    this.mood = mood || {};
    this.world.setLook(look, this.mood);
  }

  still() {
    this.pace = this.paceTarget;
    this.step(0.016);
  }

  step(dt) {
    this.t += dt;
    this.pace += (this.paceTarget - this.pace) * Math.min(1, dt * 1.5);
    this.plan(dt, this.pace);
    this.update(dt);
    // Camera: bike and rider in the middle (wheel to wheel 88 units wide).
    // When the storm blows him away the camera stays where he was.
    const b = this.bikeRoot.position;
    const x = b.x + 4 * BK.BU;
    this.world.step(dt, { x, y: b.y + 44, z: BK.LANE, lz: BK.LANE - 10, lo: x - 44, hi: x + 44 }, V3(70, 30, 335));
    this.drops.step(dt);
    this.world.render();
  }

  resize(w, h) { this.world.resize(w, h); }

  redraw() { this.world.render(); }

  dispose() { this.world.dispose(); }

  update(dt) {
    const PS = this.PS;
    const t = this.t;
    const W = this.world;
    const look = W.L2 || this.look;
    // Ground speed in bike units.
    const vB = (this.vel * BK.KX) / BK.BU;
    const pausing = this.pauseT >= 0;
    const g = this._seg(this.s);
    const f = g.len ? (wrap(this.s, 0, this.L) - g.s0) / g.len : 0;
    let mode = g.mode === 'pause' ? 'seat' : g.mode;
    if (mode === 'climb' && f > 0.62) mode = 'stand';
    if (mode === 'coast' && f > 0.88) mode = 'seat';

    // Comedy runs while he stands still because the weather says no.
    const standing = this.vel < 10 && !pausing;
    const reasonNow = standing ? moodReason(this.mood) : null;
    if (reasonNow && this.GAG[reasonNow]) {
      if (this.gag !== reasonNow) { this.gag = reasonNow; this.gagT = 0; }
      this.gagT += dt;
      if (this.gagT >= this.GAG[reasonNow]) this.gagT -= this.GAG[reasonNow];
    } else {
      this.gag = null;
      this.gagT = 0;
    }
    const gag = this.gag;
    const gt = this.gagT;

    // Wheels and cranks. Coasting holds the pedals level.
    this.wheel += (vB * dt) / 21;
    const cad = { seat: 0.55, climb: 0.9, stand: 0.62, coast: 0 }[mode];
    if (mode === 'coast' || pausing || vB < 3) {
      const target = Math.round(this.crank / Math.PI) * Math.PI;
      this.crank += (target - this.crank) * Math.min(1, dt * 2.5);
    } else {
      this.crank += ((vB * dt) / 21) * cad;
    }
    Object.keys(this.W).forEach((k) => {
      this.W[k] = lerp(this.W[k], k === mode ? 1 : 0, Math.min(1, dt * 2.2));
    });
    let stopT = standing ? 1 : 0;
    const pt8 = this.pauseT;
    if (pausing) stopT = pt8 < 1 ? ease(pt8) : pt8 > this.PAUSE - 1.3 ? 1 - ease((pt8 - (this.PAUSE - 1.3)) / 1.3) : 1;
    this.stopW = pausing ? stopT : lerp(this.stopW, stopT, Math.min(1, dt * 3));
    let sw = this.stopW;
    // Storm: feet leave the road when the gust lifts him.
    if (gag === 'wind' && gt > 4.6 && gt < 9.5) sw = Math.max(0, 1 - (gt - 4.6) / 0.5);

    const POSE = {
      seat: { hip: [-9, -43], ang: 52, hand: [39, -37], tilt: -16 },
      climb: { hip: [-8, -43.5], ang: 36, hand: [30, -36], tilt: -6 },
      stand: { hip: [3, -52], ang: 48, hand: [40, -38], tilt: -12 },
      coast: { hip: [-12, -42], ang: 70, hand: [41, -30.5], tilt: -36 },
      stop: { hip: [3, -37], ang: 12, hand: [39, -37], tilt: 0 },
    };
    const sum = Object.values(this.W).reduce((a, b) => a + b, 0) || 1;
    const mixP = (key) => {
      let x = 0;
      let y = 0;
      Object.keys(this.W).forEach((k) => {
        const v = POSE[k][key];
        const wgt = this.W[k] / sum;
        if (Array.isArray(v)) { x += v[0] * wgt; y += v[1] * wgt; } else x += v * wgt;
      });
      return Array.isArray(POSE.seat[key]) ? [x, y] : x;
    };
    let hip = mixP('hip');
    let ang = mixP('ang');
    const hand = mixP('hand');
    let tilt = mixP('tilt');
    const st = this.W.stand;
    hip = [hip[0] + Math.sin(this.crank * 2) * 1.4 * st, hip[1] - Math.abs(Math.sin(this.crank)) * 2.4 * st + Math.sin(this.crank * 2) * 0.5 * (1 - st) * Math.min(1, vB / 20)];

    // Wheelie: leans back, front wheel up, a little wobble.
    const wheelieOn = g.wheelie && !standing ? 1 : 0;
    this.wheelie = lerp(this.wheelie, wheelieOn * (1 - Math.max(0, (f - 0.8) / 0.2)), Math.min(1, dt * 2.2));
    hip = [hip[0] - 5 * this.wheelie, hip[1] - 1 * this.wheelie];
    ang -= 22 * this.wheelie;
    tilt -= 4 * this.wheelie;

    hip = lerpPt(hip, POSE.stop.hip, sw);
    ang = lerp(ang, POSE.stop.ang, sw);
    tilt = lerp(tilt, POSE.stop.tilt, sw);
    const a = (ang * Math.PI) / 180;
    let shoulder = [hip[0] + Math.sin(a) * 30, hip[1] - Math.cos(a) * 30];
    const na = a * 0.55;
    let head = [shoulder[0] + Math.sin(na) * 12.5 + 1.5, shoulder[1] - Math.cos(na) * 12.5];

    // Pedals and feet.
    const bb = [0, 4];
    const footOn = (cr) => {
      const pedal = polar(bb, 9, cr);
      const fa = 14 + 12 * Math.sin(cr);
      const off = rot([6.9, 3.75], fa);
      return { pedal, ankle: [pedal[0] - off[0], pedal[1] - off[1]], fa };
    };
    const near = footOn(this.crank);
    const far = footOn(this.crank + Math.PI);
    const groundP = [16, 21 - 3.75];
    const lift = Math.sin(sw * Math.PI) * 6;
    let ankleN = [lerp(near.ankle[0], groundP[0], sw), lerp(near.ankle[1], groundP[1], sw) - lift];
    let faN = lerp(near.fa, 0, sw);
    let ankleF = far.ankle;
    let faF = far.fa;
    // Foot down beside the bike: a little further out.
    const footOut = 14 * sw;

    let handN = hand;
    let handF = [hand[0] - 3, hand[1] - 1];
    let headTilt = tilt;
    let bottleIn = false;
    let bottleRot = 52;
    let mouthO = false;
    let fly = null;
    let walkBeside = null;
    let helmetOn = true;
    let helmetFly = null;
    let shakeX = 0;

    // ----- drink during the pause -----
    if (pausing) {
      const mo = rot([6.2 * PS, 4.6 * PS], -24);
      const mouth = [head[0] + mo[0], head[1] + mo[1]];
      const cap = rot([0, -10], -112);
      const atMouth = [mouth[0] - cap[0], mouth[1] - cap[1]];
      const CAGE = [16, -8];
      handN = keyed([
        [0, hand], [1.0, hand], [1.8, CAGE], [2.6, atMouth],
        [4.8, atMouth], [5.5, [atMouth[0] + 3, atMouth[1] + 14]], [6.3, CAGE], [7.0, hand], [this.PAUSE, hand],
      ], pt8, lerpPt);
      bottleIn = pt8 >= 1.8 && pt8 < 6.3;
      bottleRot = keyed([[1.8, 52], [2.4, 0], [2.8, -112], [4.8, -112], [5.3, 10], [6.3, 52]], pt8, lerp);
      if (pt8 > 2.6 && pt8 < 4.8) headTilt = -24 + Math.sin(pt8 * 7) * 1.5;
      else if (pt8 > 4.8 && pt8 < 5.6) headTilt = lerp(-24, 0, (pt8 - 4.8) / 0.8);
    }

    // ----- storm: helmet first, then the rider flies away -----
    if (gag === 'wind') {
      const gust = 0.5 + 0.5 * wobble(t * 1.1, 1);
      if (gt < 2.6) headTilt = 8;
      if (gt >= 2.6 && gt < 4.6) {
        const k = ease(clamp((gt - 2.6) / 0.5, 0, 1));
        headTilt = lerp(8, -18, k);
        handN = lerpPt(hand, [head[0] - 22, head[1] - 6], k * 0.9);
        mouthO = true;
      }
      if (gt >= 2.6 && gt < 4.8) {
        const k = (gt - 2.6) / 2.2;
        helmetFly = [head[0] - k * k * 330, head[1] - 12 - Math.sin(k * Math.PI) * 26 - k * 30, -k * 720];
      }
      if (gt >= 2.6) helmetOn = false;
      if (gt >= 4.0 && gt < 4.6) fly = [-(gt - 4.0) * 12, 0, 0];
      if (gt >= 4.6 && gt < 5.3) {
        const k = ease((gt - 4.6) / 0.7);
        fly = [-7.2 - k * 6, -k * 4, -k * 16];
        mouthO = true;
      }
      if (gt >= 5.3 && gt < 7.4) {
        const k = (gt - 5.3) / 2.1;
        fly = [-13 - k * k * 400, -4 - 270 * (1 - (1 - k) * (1 - k)) + Math.sin(k * 9) * 5, -16 - k * k * 460];
        mouthO = true;
        handN = [shoulder[0] + 4 + Math.sin(t * 14) * 6, shoulder[1] - 24 + Math.cos(t * 13) * 4];
        handF = [shoulder[0] - 10 + Math.cos(t * 15) * 6, shoulder[1] - 22 + Math.sin(t * 12) * 4];
      }
      if (gt >= 7.4 && gt < 9.4) fly = [-1400, 0, 0];
      if (gt >= 9.4 && gt < 15.2) {
        // Pushes the bike back in, bent into the wind, helmet on the bars.
        const k = clamp((gt - 9.4) / 5.2, 0, 1);
        fly = [lerp(-330, 0, k), 0, 0];
        walkBeside = { lean: 14 + 6 * gust, moving: k < 1 };
        helmetFly = [40, -27 + Math.sin(t * 4) * 1.5, 18 + Math.sin(t * 5) * 14];
      }
      if (gt >= 15.2) {
        const k = ease(clamp((gt - 15.2) / 1.2, 0, 1));
        helmetOn = k > 0.75;
        helmetFly = k < 0.75 ? lerpPt([40, -27], [head[0], head[1] - 10], k / 0.75).concat([lerp(18, 0, k)]) : null;
        handN = lerpPt([40, -27], [head[0] + 2, head[1] - 6], Math.sin(Math.min(1, k) * Math.PI));
      }
    }

    // ----- rain: a car drives through the puddle -----
    let soaked = 0;
    const bx = this.s * BK.KX;
    const by = this.route.height(wrap(bx, 0, this.route.length));
    this.car.root.visible = gag === 'rain';
    this.puddle.visible = gag === 'rain';
    if (gag === 'rain') {
      const carX = lerp(700, -700, clamp((gt - 2.6) / 1.4, 0, 1));
      const cx = bx + carX * BK.BU + 14 * BK.BU;
      this.car.root.position.set(cx, W.heightAt(cx, -100), -100);
      this.car.wheels.forEach((w) => { w.rotation.z = gt * 25; });
      this.puddle.position.set(bx + 14 * BK.BU, W.heightAt(bx, -42) + 0.6, -42);
      this.puddle.scale.set(30, 1, 16);
      if (gt >= 3.2 && !this.splashed) {
        this.splashed = true;
        // A sheet of water from the wheel towards him.
        for (let i = 0; i < 80; i += 1) {
          const p = V3(bx + rnd(-10, 30), by + 2, rnd(-55, -30));
          this.drops.emit(p, V3(rnd(-120, 30), rnd(110, 260), rnd(70, 190)), rnd(0.8, 1.3), rnd(1.4, 2.6), by);
        }
        for (let i = 0; i < 10; i += 1) this.world.puff(V3(bx + rnd(-10, 30), by + rnd(5, 40), rnd(-40, 0)), V3(rnd(-20, 10), rnd(20, 60), rnd(40, 90)), 3.2, 0.9, 0.5, '#BBD6F2');
      }
      if (gt < 3.0) this.splashed = false;
      soaked = gt > 3.3 ? 1 : 0;
      if (gt > 3.3 && gt < 5.0) {
        const k = ease(clamp((gt - 3.3) / 0.3, 0, 1));
        handN = lerpPt(hand, [shoulder[0] + 18, shoulder[1] + 6], k);
        handF = lerpPt(handF, [shoulder[0] - 14, shoulder[1] + 8], k);
        mouthO = true;
        headTilt = -6;
      }
      if (gt >= 5.0 && gt < 7.0) {
        // Shakes himself like a dog.
        const k = Math.sin(((gt - 5.0) / 2.0) * Math.PI);
        shakeX = Math.sin(t * 38) * 2.2 * k;
        headTilt = Math.sin(t * 38) * 14 * k;
        handN = [shoulder[0] + 16, shoulder[1] + 10 + Math.sin(t * 38) * 4];
        handF = [shoulder[0] - 12, shoulder[1] + 12 - Math.sin(t * 38) * 4];
        if (Math.random() < dt * 40) {
          const hp = this.rider.head.getWorldPosition(V3());
          this.drops.emit(hp.add(V3(rnd(-8, 8), rnd(-30, 4), rnd(-6, 6))), V3(rnd(-90, 90), rnd(-10, 60), rnd(-90, 90)), 0.8, 1.2, by);
        }
      }
    }

    // ----- cold: icicle on the nose, then a sneeze -----
    let icicle = 0;
    if (gag === 'cold') {
      icicle = clamp(gt / 6, 0, 1);
      if (gt >= 6.0 && gt < 7.6) {
        icicle = 0;
        const k = gt - 6.0;
        headTilt = k < 0.12 ? -14 : k < 0.35 ? lerp(22, 10, (k - 0.12) / 0.23) : lerp(10, 0, clamp((k - 0.35) / 1.2, 0, 1));
        if (k < 0.12) mouthO = true;
        if (!this.sneezed && k > 0.12) { this.sneezed = true; this.ice = { x: head[0] + 11, y: head[1] + 3, vx: 120, vy: -40, r: 0, broke: false }; }
      }
      if (gt < 6.0) this.sneezed = false;
    }
    this.icicle.visible = icicle > 0.02;
    this.icicle.scale.set(0.5 + 0.7 * icicle, 12 * icicle + 0.01, 0.5 + 0.7 * icicle);
    this._iceStep(dt, gag === 'cold');
    const sn = this.sneeze[this.lang === 'de' ? 'de' : 'en'];
    const other = this.sneeze[this.lang === 'de' ? 'en' : 'de'];
    other.visible = false;
    sn.visible = gag === 'cold' && gt > 6.1 && gt < 7.5;
    if (sn.visible) sn.position.set(head[0] + 24, -(head[1] - 16), 10);

    // ----- heat: sweat puddle, then water over the head -----
    if (gag === 'hot') {
      this.puddleR = Math.min(30, this.puddleR + dt * 3.2);
      const CAGE = [16, -8];
      const above = [head[0] + 4, head[1] - 20];
      if (gt >= 3.6 && gt < 8.6) {
        handN = keyed([[3.6, hand], [4.3, CAGE], [5.1, above], [7.1, above], [7.9, CAGE], [8.6, hand]], gt, lerpPt);
        bottleIn = gt >= 4.3 && gt < 7.9;
        bottleRot = keyed([[4.3, 52], [5.0, 0], [5.4, 165], [6.9, 165], [7.3, 10], [7.9, 52]], gt, lerp);
        if (gt > 5.4 && gt < 6.9) {
          headTilt = -10;
          if (Math.random() < dt * 60) {
            const bp = this.handBottle.localToWorld(V3(0, 9, 0));
            this.drops.emit(bp, V3(rnd(-10, 10), rnd(-20, 0), rnd(-10, 10)), 0.9, rnd(0.9, 1.5), by);
          }
        }
        if (gt > 6.9 && gt < 7.6) headTilt = Math.sin(t * 30) * 10;
      }
    } else {
      this.puddleR = Math.max(0, this.puddleR - dt * 10);
    }
    this.sweat.visible = this.puddleR > 0.3;
    if (this.sweat.visible) {
      this.sweat.position.set(bx + 14 * BK.BU, by + 0.6, BK.LANE + 4);
      this.sweat.scale.set(this.puddleR * BK.BU, 1, this.puddleR * BK.BU * 0.55);
    }

    // ----- good weather: a bird rides along on the helmet -----
    this._bird(t, g, f, head, standing || gag !== null);

    // ----- body -----
    shoulder = [shoulder[0] + shakeX, shoulder[1]];
    head = [head[0] + shakeX * 1.4, head[1]];
    let hipD = hip;
    let kneeN;
    let kneeF;
    const X = {};
    let riderZ = 0;
    if (walkBeside) {
      // Standing next to the bike on the near side, walking.
      const gw = GAITS.walk;
      const vP = walkBeside.moving ? 64 / 1.3 / PS : 0;
      this.walkPh = (this.walkPh || 0) + (vP * dt) / strideOf(gw, 0.75);
      const Wp = gaitPose(gw, this.walkPh, 0.75, walkBeside.moving ? 1 : 0, walkBeside.lean);
      const off = [13, 21 / PS];
      const m = (q) => [q[0] * PS + off[0] * PS, q[1] * PS + off[1] * PS];
      hipD = m(Wp.hip);
      shoulder = m(Wp.shoulder);
      head = m(Wp.head);
      ankleN = m(Wp.ankle); faN = Wp.footAng;
      ankleF = m(Wp.ankle2); faF = Wp.footAng2;
      kneeN = m(Wp.knee);
      kneeF = m(Wp.knee2);
      handN = [40, -36];
      handF = [36, -37];
      headTilt = 14;
      riderZ = 24;
      this.wheel += ((64 / 1.3) * dt) / 21 * (walkBeside.moving ? 1 : 0);
    } else {
      kneeN = ik(hipD, ankleN, LEG.thigh * PS, LEG.shin * PS, 1);
      kneeF = ik(hipD, ankleF, LEG.thigh * PS, LEG.shin * PS, 1);
    }
    this.bike.pose(this.wheel, near.pedal, far.pedal, gag === 'cold' ? 1 : 0);

    // Bottle in the cage or in his hand.
    this.bike.bottle.visible = !bottleIn;
    this.handBottle.visible = bottleIn;
    if (bottleIn) {
      this.handBottle.position.set(handN[0], -handN[1], riderZ + 10);
      this.handBottle.rotation.set(0, 0, -bottleRot * RAD);
    }

    const elbowN = ik(shoulder, handN, 14 * PS, 13 * PS, -1);
    const elbowF = ik(shoulder, handF, 14 * PS, 13 * PS, -1);
    const u = (q) => [q[0] / PS, q[1] / PS];
    const P = {
      hip: u(hipD), shoulder: u(shoulder), head: u(head), headTilt,
      knee: u(kneeN), ankle: u(ankleN), footAng: faN, foot: u([ankleN[0], ankleN[1] + 3.75]),
      knee2: u(kneeF), ankle2: u(ankleF), footAng2: faF, foot2: u([ankleF[0], ankleF[1] + 3.75]),
      elbow: u(elbowN), hand: u(handN), elbow2: u(elbowF), hand2: u(handF),
    };
    // Gentle reactions for borderline weather and before the comedy starts.
    const calm = !gag || (gag === 'wind' && gt < 2.6) || (gag === 'cold' && gt < 6) || (gag === 'hot' && gt < 3.6) || (gag === 'rain' && gt < 3.3) || (gag === 'rain' && gt >= 7);
    const { reason, w } = moodBlend(this, this.mood, dt, standing && calm && !walkBeside);
    let rz = null;
    if (reason && w > 0.001) {
      const hold = reason === 'wind';
      // While the icicle grows he keeps his hands on the bars and shivers,
      // so the nose stays in view.
      const ice = gag === 'cold';
      const R = reactionPose({ ...P }, reason, t, { arm: [14, 13], handsToMouth: true, keepNear: hold || ice, keepFar: hold || ice || reason === 'hot' });
      ['elbow', 'hand', 'elbow2', 'hand2', 'shoulder', 'head'].forEach((k) => {
        const q = R.lean ? rotAround(R[k], P.hip, -R.lean) : R[k];
        P[k] = lerpPt(P[k], q, w);
      });
      P.headTilt = lerp(P.headTilt, R.headTilt, w);
      rz = { R, w };
    }
    // Lateral positions: hands on the bars, feet on the pedals.
    const onBar = !walkBeside;
    X.handZ = onBar ? 10.5 / PS : (12 - riderZ) / PS;
    X.hand2Z = onBar ? -10.5 / PS : (8 - riderZ) / PS;
    if (rz) {
      // Reaction hands come in towards the face.
      X.handZ = lerp(X.handZ, 3, rz.w);
      if (!(rz.R.handFace)) X.hand2Z = lerp(X.hand2Z, -3, rz.w);
    }
    if (gag === 'rain' && gt > 3.3 && gt < 7) { X.handZ = 13; X.hand2Z = -13; }
    if (gag === 'wind' && gt >= 5.3 && gt < 7.4) { X.handZ = 12; X.hand2Z = -12; }
    if (pausing || (gag === 'hot' && bottleIn)) X.handZ = lerp(10.5 / PS, 4, bottleIn ? 1 : 0);
    if (!walkBeside) {
      X.footZ = (8 + footOut) / PS;
      X.foot2Z = -8 / PS;
    }
    this.rider.root.position.set(0, 0, riderZ);
    this.rider.apply(P, X);
    this.rider.setMouth(mouthO ? 'open' : (reason === 'hot' || reason === 'cold') && w > 0.5 ? 'frown' : 'calm');
    this.rider.setBrows(mouthO ? 0.9 : 0, 0);
    const m = this.mood || {};
    this.rider.setBlush(Math.max(m.hot || 0, (m.cold || 0) * 0.7, look.cold || 0));
    this.helmet.visible = helmetOn;
    this.flyHelmet.visible = !!helmetFly;
    if (helmetFly) {
      const hx = helmetFly[0] + (walkBeside && fly ? 0 : 0);
      this.flyHelmet.position.set(hx, -helmetFly[1], walkBeside ? 4 : 0);
      this.flyHelmet.rotation.set(0, 0, -(helmetFly[2] || 0) * RAD);
    }
    // Wet jersey after the soaking.
    this.wet = lerp(this.wet, soaked, Math.min(1, dt * (soaked ? 6 : 0.25)));
    this.rider.setWet(this.wet);
    if (this.wet > 0.2 && Math.random() < dt * 8 * this.wet) {
      const p = this.rider.torso.getWorldPosition(V3()).add(V3(rnd(-6, 8), rnd(4, 20), rnd(-8, 8)));
      this.drops.emit(p, V3(0, 0, 0), 0.8, 0.9, by);
    }

    // Whole bike: wheelie, being blown away, pushed back in.
    const wh = this.wheelie * (14 + Math.sin(t * 3.1) * 2.5);
    const fx = fly || [0, 0, 0];
    this.flyG.position.set(-30 + fx[0], -21 - fx[1], 0);
    this.flyG.rotation.z = -(fx[2] - wh) * RAD;

    // On the road, following its slope.
    const slope = Math.atan2(this.route.height(wrap(bx + 30, 0, this.route.length)) - this.route.height(wrap(bx - 30, 0, this.route.length)), 60);
    this.bikeRoot.position.set(bx, by, BK.LANE);
    this.bikeRoot.rotation.z = slope;

    // Breath clouds in the cold, sweat in the heat.
    this.bikeRoot.updateMatrixWorld(true);
    const coldness = Math.max(look.cold || 0, m.cold || 0);
    const breath = (t % 3.2) / 3.2;
    this.breathT = (this.breathT || 0) - dt;
    if (coldness > 0.05 && breath < 0.3 && this.breathT <= 0 && !fly) {
      const at = this.rider.head.localToWorld(V3(10.5, -3.4, 0));
      const dir = this.rider.head.localToWorld(V3(30, -4, 0)).sub(at).normalize();
      this.world.puff(at, dir.multiplyScalar(26), 0.9, 1.9, coldness * 0.55);
      this.breathT = 0.12;
    }
    const hot = m.hot || 0;
    this.sweatT = (this.sweatT ?? 0.6) - dt;
    if (hot > 0 && this.sweatT <= 0 && !fly) {
      const at = this.rider.head.localToWorld(V3(6.5, 3, rnd(-5, 5)));
      this.drops.emit(at, V3(0, -4, 0), 1.2, 0.7, by);
      this.sweatT = (hot >= 1 ? 1.1 : 2.8) * rnd(0.7, 1.3);
    }
  }

  /** Flying icicle after the sneeze; it breaks on the road. */
  _iceStep(dt, on) {
    if (!this.ice || !on) {
      this.flyIce.visible = false;
      if (!on) this.ice = null;
    } else if (!this.ice.broke) {
      const k = this.ice;
      k.vy += 420 * dt;
      k.x += k.vx * dt;
      k.y += k.vy * dt;
      k.r += 600 * dt;
      this.flyIce.visible = true;
      this.flyIce.position.set(k.x, -k.y, 0);
      this.flyIce.rotation.z = -k.r * RAD;
      this.flyIce.scale.set(1.2 * this.PS, 12 * this.PS, 1.2 * this.PS);
      if (k.y >= 20) {
        k.broke = true;
        k.shards = Array.from({ length: 6 }, () => ({ x: k.x, y: 20, z: rnd(-4, 4), vx: rnd(-50, 60), vy: rnd(-90, -30), vz: rnd(-30, 30), r: rnd(0, 6) }));
        k.t = 0;
      }
    } else {
      this.flyIce.visible = false;
    }
    this.shards.forEach((sh, i) => {
      const s = this.ice && this.ice.shards && this.ice.shards[i];
      if (!s || this.ice.t > 1.4) { sh.visible = false; return; }
      s.vy += 380 * dt;
      s.x += s.vx * dt;
      s.z += s.vz * dt;
      s.y = Math.min(20.4, s.y + s.vy * dt);
      if (s.y >= 20.4) { s.vx *= 0.85; s.vz *= 0.85; s.vy = 0; }
      s.r += s.vx * 0.05 * dt;
      sh.visible = true;
      sh.position.set(s.x, -s.y, s.z);
      sh.rotation.set(s.r, s.r * 1.3, s.r * 0.7);
    });
    if (this.ice && this.ice.broke) this.ice.t += dt;
  }

  /** Bird: flies in, rides on the helmet, flies off when he sprints. */
  _bird(t, g, f, head, off) {
    const top = [head[0] - 1, head[1] - 16];
    let p = null;
    let flap = true;
    let flip = false;
    if (!off && g.bird) {
      if (f < 0.3) {
        const k = ease(f / 0.3);
        p = [lerp(top[0] + 260, top[0], k), lerp(top[1] - 120, top[1], k) - Math.sin(k * Math.PI) * 20];
        flip = true;
      } else {
        p = top;
        flap = false;
      }
    } else if (!off && this._seg(this.s).mode === 'stand' && this.s - this.segs[1].s0 < 260) {
      const k = (this.s - this.segs[1].s0) / 260;
      p = [top[0] - k * 160, top[1] - k * 130];
      flip = true;
    }
    this.bird.root.visible = !!p;
    if (!p) return;
    const hop = flap ? 0 : Math.max(0, Math.sin(t * 2.3)) > 0.97 ? -2 : 0;
    this.bird.root.position.set(p[0], -(p[1] + hop), 0);
    this.bird.root.rotation.y = flip ? Math.PI : 0;
    this.bird.pose(t, flap);
  }
}

/** Can this browser draw WebGL? Checked once. */
let WEBGL_OK = null;
function supported() {
  if (WEBGL_OK !== null) return WEBGL_OK;
  try {
    const c = document.createElement('canvas');
    const gl = c.getContext('webgl2') || c.getContext('webgl');
    WEBGL_OK = !!gl;
    if (gl && gl.getExtension('WEBGL_lose_context')) gl.getExtension('WEBGL_lose_context').loseContext();
  } catch (e) {
    WEBGL_OK = false;
  }
  return WEBGL_OK;
}

return { scenes: { walking: WalkScene3D, bike: BikeScene3D }, supported };
})();


